(window.GIM_TS=window.GIM_TS||{})["Ketubot.4"]={"from":96,"a":[["\u0003ועשיתינהו לזניה\u0004 \u0005[וכפיתי אותם שיזונו אותו],\u0006 ומשום כך היה מכיר לי טובה. ולענייננו: \u0003אי אמרת בשלמא לאו דינא\u0004 \u0005[נניח אם אומר אתה\u0006 ש\u0005אין\u0006 זה מן \u0005הדין],\u0006 שמעיקר הדין היו רשאים שלא לפרנסו — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003עשיינהו\u0004 \u0005[כפה אותם],\u0006 \u0003אלא אי אמרת דינא\u0004 \u0005[אם אומר אתה\u0006 ש\u0005הדין\u0006 הוא כן\u0005]\u0006 — \u0003עשיינהו בעי\u0004 \u0005[\u0006האם היה \u0005צריך לכפות אותם]?\u0006 הלא יכולים היו לרדת לנכסיהם ולקחת מהם! משמע שאין הלכה כר' אילעא.","כיון שהוזכרו תקנות אושא, מביאים מהן עוד. \u0003אמר ר' אילעא, ב\u0004עיר \u0003אושא התקינו\u0004 תקנה ש\u0003המבזבז\u0004 (המפזר) מנכסיו לצדקה — \u0003אל יבזבז יותר מחומש\u0004 (חמישית). \u0003תניא נמי הכי\u0004 \u0005[שנויה גם כן כך\u0006 ברייתא\u0005]:\u0006 \u0003המבזבז אל יבזבז יותר מחומש, שמא\u0004 על ידי כך יתרושש ו\u0003יצטרך לבריות. ומעשה באחד שבקש לבזבז יותר מחומש\u0004 מנכסיו לצדקה \u0003ולא הניח לו חבירו. ומנו\u0004 \u0005[ומי הוא\u0006 חבירו זה\u0005] —\u0006 \u0003ר' ישבב. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003ר' ישבב\u0004 היה זה שרצה לבזבז, \u0003ולא הניחו חבירו, ומנו\u0004 \u0005[ומי הוא\u0006 חבירו זה\u0005] —\u0006 \u0003ר' עקיבא.\u0004","\u0003אמר רב נחמן ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אחא בר יעקב: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על שיעור זה לצדקה — \u0003\"וכל אשר תתן לי עשר אעשרנו לך\"\u0004 (בראשית כח, כב), והוא דורש: \"עשר אעשרנו\", שיעקב דיבר פעמיים על מעשר, ושני מעשרות יחד הם חומש.","ומקשים: \u0003והא לא דמי עישורא בתרא לעישורא קמא\u0004 \u0005[והרי אינו דומה העישור האחרון לעישור הראשון]\u0006 לפי שהמעשר השני שיעקב הזכיר הוא ממה שנשאר לאחר שנתן המעשר הראשון, ושני המעשרות יחד הם קצת פחות מחומש! \u0003אמר רב אשי\u0004 צריך לפרש: \u0003\"אעשרנו\" לבתרא\u0004 \u0005[לאחרון]\u0006 \u0003כי קמא\u0004 \u0005[כמו\u0006 את \u0005הראשון],\u0006 כלומר, אתן פעם נוספת מעשר כמו הראשון.","על אופן מסירת השמועות של תקנות אושא \u0003אמר רב שימי בר אשי: ושמועות הללו מתמעטות והולכות.\u0004 שהרי בשמועה ראשונה נאמרו דברי ר' אילעא בשם ריש לקיש שאמר בשם ר' יוסי בר חנינא; בשניה, ר' אילעא שאמר בשם ריש לקיש; ובשלישית, ר' אילעא לבדו. \u0003וסימניך\u0004 כדי לזכור את סדר ההלכות הללו — \u0003קטנים כתבו ובזבזו:\u0004 \"קטנים\" — מצוה לזון את הקטנים, \"כתבו\" — מי שכתב נכסיו לבניו, \"בזבזו\" — המבזבז יותר מחומש.","\u0003אמר רב יצחק, ב\u0004עיר \u0003אושא התקינו\u0004 תקנה נוספת: \u0003שיהא אדם מתגלגל\u0004 (נוהג ברכות) \u0003עם בנו,\u0004 גם אם אינו רוצה ללמוד \u0003עד\u0004 גיל \u0003שתים עשרה שנה. מכאן ואילך, יורד עמו לחייו.\u0004 כלומר, יכול לכפותו לכך בדרך קשה. ושואלים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב שמואל בר\u0004 (בן) \u0003שילת\u0004 שהיה מלמד תינוקות: \u0003בציר מבר שית\u0004 \u0005[פחות מבן שש] —\u0006 \u0003לא תקבל\u0004 ללמוד אצלך. \u0003בר שית\u0004 \u0005[בן שש] —\u0006 \u0003קביל וספי ליה כתורא\u0004 \u0005[קבל, והלעט אותו\u0006 בלימוד התורה \u0005כמו שור]\u0006 שאובסים אותו בעל כורחו, משמע שמכריחים ילד ללמוד אף לפני שיהיה בן שתים עשרה!","ומשיבים: אין זו סתירה; \u0003אין, ספי ליה כתורא\u0004 \u0005[אכן,\u0006 הוא צריך \u0005להלעיט אותו כשור]\u0006 וללמד אותו הרבה, \u0003מיהו\u0004 \u0005[מכל מקום]\u0006 \u0003אינו יורד עמו לחייו\u0004 אם אינו לומד \u0003עד לאחר\u0004 שהוא בן \u0003שתים עשרה שנה. ואיבעית אימא לא קשיא\u0004 \u0005[ואם תרצה אמור\u0006 כי \u0005אין זה קשה]\u0006 ואפשר לומר: \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שהוא מתחיל להלעיטו בדברי תורה כשור כבר כשהוא כבן שש, הוא \u0003למקרא, הא\u0004 \u0005[זה]\u0006 שהוא כופה אותו רק בגיל שתים עשרה הוא \u0003למשנה.\u0004","ש\u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003בר שית\u0004 \u0005[בן שש] —\u0006 ללימוד \u0003מקרא, בר\u0004 \u0005[בן]\u0006 \u0003עשר — למשנה,\u0004 אבל עדיין לא כופהו עד גיל שתים עשרה, \u0003בר תליסר\u0004 \u0005[בן שלוש עשרה] —\u0006 \u0003לתעניתא\u0004 \u0005[לתענית]\u0006 \u0003מעת לעת,\u0004 כלומר, שעליו להתענות בתעניות יממה שלימה כשאר המבוגרים. \u0003ובתינוקת\u0004 (בת) הגיל שחייבת להתענות — \u0003בת תריסר\u0004 \u0005[שתים עשרה].\u0006","ואגב כך מסופר עוד: \u0003אמר אביי, אמרה לי אם: האי בר שית דטרקא ליה עקרבא ביומא דמישלם שית\u0004 \u0005[\u0006ילד \u0005זה בן שש שעוקץ אותו עקרב ביום ש\u0006הוא \u0005משלים שש\u0006 שנים\u0005] —\u0006 \u0003לא חיי\u0004 \u0005[איננו חי].\u0006 \u0003מאי אסותיה\u0004 \u0005[מה רפואתו] —\u0006 \u0003מררתא\u0004 \u0005[מרה]\u0006 של \u0003דיה חיורתא\u0004 \u0005[לבנה]\u0006 \u0003בשיכרא\u0004 \u0005[ב\u0006תוך \u0005שיכר],\u0006 \u0003נשפייה ונשקייה\u0004 \u0005[ישפשפוהו\u0006 בזה \u0005וישקוהו]\u0006 במשקה זה. ועוד אמרה לו: \u0003האי בר שתא דטריק ליה זיבורא ביומא דמישלם שתא\u0004 \u0005[\u0006ילד \u0005זה בן שנה שעוקצת אותו צירעה ביום שמשלים שנה] —\u0006 \u0003לא חיי\u0004 \u0005[איננו חי].\u0006 \u0003מאי אסותיה\u0004 \u0005[מה רפואתו] —\u0006 \u0003אצותא דדיקלא במיא\u0004 \u0005[סיב הדקל במים],\u0006 \u0003נשפייה ונשקייה\u0004 \u0005[ישפשפנו\u0006 בו \u0005וישקנו\u0006 ממנו\u0005].\u0006","\u0003אמר רב קטינא: כל המכניס את בנו\u0004 לבית הספר \u0003פחות מבן שש — רץ אחריו ואינו מגיעו,\u0004 כלומר, הוא צריך לדאוג לו, לשלומו, זמן רב אחר כך, מפני שהילד נחלש מחמת הלימוד. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003חביריו רצין אחריו\u0004 בלימוד \u0003ואין מגיעין אותו,\u0004 שכיון שהוא מקדים אותם הרי הוא מצליח הרבה יותר בלימודו. ומעירים: \u0003ותרוייהו איתנהו\u0004 \u0005[ושניהם ישנם\u0006 בו\u0005]:\u0006 \u0003חליש וגמיר\u0004 \u0005[\u0006שהוא גם \u0005נחלש\u0006 וגם \u0005לומד].\u0006 \u0003איבעית אימא\u0004 \u0005[\u0006ו\u0005אם תרצה אמור]\u0006 אפשר להסביר את שתי הדעות באופן אחר: \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שבהכנסתו ללמוד בגיל צעיר הוא נחלש, הרי זה באופן \u0003דכחיש\u0004 \u0005[ש\u0006הילד הוא \u0005כחוש],\u0006 ובשל כך הוא נחלש מאד. \u0003הא\u0004 \u0005[\u0006ו\u0005זה]\u0006 שאמרנו שאפשר להכניסו מוקדם ללמוד בגיל צעיר והוא מצליח, הרי זה באופן שהוא \u0003בריא.\u0004","ועוד \u0003אמר ר' יוסי בר חנינא, באושא התקינו\u0004 עוד ש\u0003האשה שמכרה בנכסי מלוג\u0004 (שהם הנכסים השייכים לה, ובעלה רק אוכל פירותיהם) \u0003בחיי בעלה ומתה — הבעל מוציא מיד הלקוחות.\u0004 שחכמים רואים אותו כאילו היה הוא הלקוח הראשון (ולא כיורש), ולכן הנכסים שייכים לו. מסופר: \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003רב יצחק בר יוסף לר' אבהו דהוה קאי באוכלוסא\u0004 \u0005[שהיה עומד ב\u0006תוך \u0005קהל]\u0006 של \u0003אושא, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאן מרה דשמעתא\u0004 \u0005[מי\u0006 הוא \u0005בעל השמועות]\u0006 של \u0003אושא,\u0004 כלומר, מי בקי בהלכות הללו שתיקנו באושא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ר' יוסי בר חנינא. תנא מיניה ארבעין זימנין\u0004 \u0005[שנה ממנו\u0006 מר' יוסי בר חנינא \u0005ארבעים פעמים],\u0006 \u0003ודמי ליה כמאן דמנחא ליה בכיסתיה\u0004 \u0005[ודומה\u0006 היה \u0005לו\u0006 מאז \u0005כמו שמונח לו בכיסו],\u0006 משום שנעשה בקי היטב בתקנות אושא.","ועוד בקשר לתקנות אושא, נאמר: \u0003\"אשרי שמרי משפט עשה צדקה בכל עת\"\u0004 (תהלים קו, ג), ויש להבין: \u0003וכי אפשר לעשות צדקה בכל עת?\u0004 הלא לא תמיד מצויים עניים לפניו! לכן \u0003דרשו רבותינו שביבנה, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אליעזר: זה הזן בניו ובנותיו כשהן קטנים,\u0004 שכפי שאמרנו אין עליו חיוב גמור לפרנסם, ואם כך, כאשר מפרנס אותם נמצא שבכל עת הוא עושה צדקה. \u0003ר' שמואל בר נחמני אמר: זה המגדל יתום\u0004 או \u0003יתומה בתוך ביתו\u0004 ודואג להם \u0003ומשיאן,\u0004 ונמצא שהוא עושה צדקה כל הזמן.","ועוד דרשו על הכתוב \u0003\"הון ועשר בביתו וצדקתו עמדת לעד\"\u0004 (תהלים קיב, ג): איך ייתכן שישאר הון ועושר בביתו וגם שצדקתו עומדת לעד? \u0003רב הונא ורב חסדא\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: זה הלומד תורה ומלמדה,\u0004 שאינו מאבד דבר משלו, אבל צדקתו עומדת לעד, שעשה צדקה בלמדו אחרים. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: זה הכותב תורה נביאים וכתובים ומשאילן לאחרים,\u0004 שהספרים הם שלו, ואחרים נהנים מצדקתו.","ועוד דרשו על הכתוב \u0003\"וראה בנים לבניך שלום על ישראל\"\u0004 (תהלים קכח, ו): \u0003אמר ר' יהושע בן לוי: כיון ש\u0004יש \u0003בנים לבניך\u0004 — נעשה אז \u0003שלום על ישראל.\u0004 ומדוע — \u0003דלא אתי\u0004 \u0005[שאינו בא]\u0006 \u0003לידי חליצה ויבום,\u0004 שהרי דין יבום או חליצה שייכים רק כאשר אין בנים (ילדים) לאחד הבנים, שנפטר בלי ילדים. \u0003ר' שמואל בר נחמני אמר: כיון שבנים לבניך — שלום על דייני ישראל,\u0004 ומדוע — \u0003דלא אתי לאינצויי\u0004 \u0005[שאינם באים\u0006 הקרובים \u0005להתקוטט]\u0006 עם הדיינים בענייני ירושה, שהרי הנחלה עוברת במישרין לבנים, ואין מקום לקטטה.","מכאן חוזרים לביאור המשנה. שנינו שם: \u0003זה מדרש דרש ר' אלעזר בן עזריה לפני חכמים\u0004 בכרם דיבנה, שאין הבנות ניזונות מנכסי אביהן אלא לאחר מותו."],["\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב יוסף קמיה\u0004 \u0005[לפני]\u0006 \u0003רב המנונא\u0004 בבית המדרש, \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב המנונא וקאמר\u0004 \u0005[ואמר]\u0006 הלכה זו: \u0003כשם שאין הבנים יורשין אלא מן הקרקע — כך אין בנות ניזונות אלא מן הקרקע.\u0004 כאשר רב המנונא אמר הלכה זו \u0003אווש עליה כולי עלמא\u0004 \u0005[רעש עליו כל העולם],\u0006 כלומר, כל השומעים התחילו בינם לבין עצמם להביע את תמיהתם: \u0003דשביק ארעא\u0004 \u0005[\u0006מי \u0005שמניח קרקע] —\u0006 \u0003הוא דירתי ליה בניה\u0004 \u0005[שיורשים אותו בניו],\u0006 ומי \u0003דלא שביק ארעא\u0004 \u0005[שאינו מניח קרקע] —\u0006 \u0003לא ירתי ליה בניה\u0004 \u0005[אין יורשים אותו בניו]?!\u0006 שהרי מדברי רב המנונא יוצא שהבנים יורשים רק קרקע ולא דבר אחר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: ודלמא\u0004 \u0005[ושמא]\u0006 בענין \u0003כתובת בנין דכרין\u0004 \u0005[בנים זכרים]\u0006 \u0003קאמר מר\u0004 \u0005[אמר אדוני],\u0006 שאחד מתנאי הכתובה הוא שהבנים הזכרים מאשה זו יורשים את סכום כתובתה יותר על חלקם בירושת האב עם שאר אחיהם, ובענין זה אמר רב המנונא ש\"כתובת בנים זכרים\" אינה אלא מן הקרקע?! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב המנונא: \u0003מר, דגברא רבה\u0004 \u0005[אדוני, שאדם גדול]\u0006 \u0003הוא, ידע מאי קאמינא\u0004 \u0005[יודע מה אמרתי],\u0006 כי אכן זו היתה כוונתו, ואחרים לא הבינו אותה.","\u0003אמר ר' חייא בר יוסף: רב\u0004 היה \u0003זן\u0004 יתומות \u0003מחיטי\u0004 \u0005[מחיטים]\u0006 שב\u0003עלייה,\u0004 כשלא היו לאב קרקעות. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם דבר זה שפסק רב לתת \u0003פרנסה הויא\u0004 \u0005[היתה],\u0006 כלומר, פרנסה של נדוניה, \u0003ו\u0004לפי זה יש לפרש \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שזן מחיטים שב\u0003עלייה\u0004 — \u0003מעילוייא\u0004 \u0005[\u0006לפי \u0005מעלת]\u0006 ה\u0003אב, וכ\u0004דברי \u0003שמואל.\u0004 ש\u0003אמר שמואל: לפרנסה,\u0004 כלומר, לענין נדוניה \u0003שמין באב,\u0004 שמעריכים לפי מעלתו, אופיו, וכוחו הכלכלי של האב ולפי זה נותנים לבנות מנכסיו לאחר מותו.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 מה שאמרו שזן את הבנות \u0003מזוני\u0004 \u0005[מזונות]\u0006 \u0003ממש הוה\u0004 \u0005[היו],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"עלייה\"\u0004 זו שאמרנו — \u0003מדברים טובים שנאמרו בעלייה,\u0004 כלומר, על סמך ההלכות שנאמרו בעלייה. ש\u0003אמר רב יצחק בר יוסף: בעלייה\u0004 כאשר ישבו חכמים בעלייה, כשלא יכלו מחמת הגזירה לשבת בבית המדרש, ופסקו כמה הלכות, \u0003התקינו שיהו בנות ניזונות מן המטלטלין\u0004 ולא רק מן הקרקעות.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו: \u0003בידיה\u0004 \u0005[בידיו]\u0006 של \u0003ר' בנאי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' חייא בר אבא הוו\u0004 \u0005[היו]\u0006 \u0003מטלטלין דיתמי\u0004 \u0005[של יתומים]\u0006 שהופקדו אצלו על ידי האב. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003שמואל\u0004 בנותיו של אותו אדם שמת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל לר' בנאי: \u0003זיל זון\u0004 \u0005[לך\u0006 ו\u0005פרנס]\u0006 אותן מאותם מטלטלים ששייכים ליתומים.","\u0003מאי לאו למזוני\u0004 \u0005[האם אין\u0006 הכוונה לתת להן \u0005מזונות]\u0006 מהמטלטלים, \u0003וכ\u0004דברי \u0003רב יצחק בר יוסף סבירא ליה\u0004 \u0005[סבור הוא]?\u0006 שהיתה תקנה בעלייה ליזון אף ממטלטלים. ודוחים: \u0003לא, התם\u0004 \u0005[שם]\u0006 \u0003ל\u0004ענין \u0003פרנסה הואי\u0004 \u0005[היה]\u0006 שאמר לו לתת. \u0003ושמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר שמואל: לפרנסה שמין באב\u0004 לפי מצבו, ואפילו ממטלטלים.","מספרים: \u0003הוה עובדא\u0004 \u0005[היה מעשה]\u0006 \u0003ב\u0004עיר \u0003נהרדעא,\u0004 שבאה בעיה כזו של מזונות הבת לפני בית הדין \u0003ודון\u0004 \u0005[ודנו]\u0006 אותו \u0003דייני\u0004 העיר \u0003נהרדעא,\u0004 וכן היה מעשה \u0003ב\u0004עיר \u0003פומבדיתא ואגבי\u0004 \u0005[והגבה]\u0006 את הסכום הזה מן המטלטלים \u0003רב חנא בר ביזנא. אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן\u0004 לדיינים: \u0003זילו אהדרו\u0004 \u0005[לכו\u0006 ו\u0005החזירו]\u0006 את מה שהוצאתם מרכוש היתומים, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — מגבינא לכו לאפדנייכו מינייכו\u0004 \u0005[אגבה אני את בתיכם מכם],\u0006 שדיינים שדנו שלא כדין גובים מהם כדי לשלם את הנזק שגרמו.","מסופר: \u0003ר' אמי ור' אסי סבור למיזן ממטלטלי\u0004 \u0005[חשבו לזון\u0006 את הבנות היתומות \u0005מן המטלטלים]\u0006 שהשאיר אביהן, \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יעקב בר אידי: מילתא\u0004 \u0005[דבר]\u0006 ש\u0003ר' יוחנן וריש לקיש לא עבדו\u0004 \u0005[עשו]\u0006 \u0003בה עובדא\u0004 \u0005[מעשה]\u0006 \u0003אתון עבדין\u0004 \u0005[אתם עושים]\u0006 \u0003בה עובדא\u0004 \u0005[מעשה]?!\u0006 שאם חכמים גדולים אלה לא היו בטוחים מה הדין, ולא הגיעו בו לכלל מעשה, האם ייתכן שאתם תחליטו בו?!","וכן מסופר: \u0003ר' אלעזר סבר למיזן\u0004 \u0005[חשב לזון]\u0006 את הבנות \u0003ממטלטלין. אמר לפניו ר' שמעון בן אליקים: רבי, יודע אני בך שאין מדת הדין אתה עושה,\u0004 שאין אתה נוהג כך משום שזו ההלכה, \u0003אלא מדת רחמנות,\u0004 שאתה חס על הבנות הללו, ורוצה לפרנסן. \u0003אלא,\u0004 אל תעשה זאת, \u0003שמא יראו התלמידים ויקבעו הלכה לדורות,\u0004 ואין הלכה כן.","מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[אחד שבא לפני]\u0006 \u0003רב יוסף\u0004 לשאול בנושא זה, \u0003אמר להו\u0004 \u0005[להם]\u0006 ליתומים: \u0003הבו\u0004 \u0005[תנו]\u0006 \u0003לה\u0004 לבת \u0003מתמרי דעל בודיא\u0004 \u0005[מהתמרים ש\u0006מונחים לייבוש \u0005על המחצלות]\u0006 שהם מטלטלים גמורים, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003אילו בעל חוב הוה כי האי גוונא\u0004 \u0005[היה, כגון זה],\u0006 \u0003מי הוה יהיב ליה מר\u0004 \u0005[האם היה נותן לו אדוני]?\u0006 כלומר, אפילו בעל חוב הטורף מנכסים משועבדים אינו גובה ממטלטלים שהם עכשיו נכסי היתומים, וכל שכן מזון הבנות, שאף הוא כעין חוב, שהרי הוא כתוב בשטר הכתובה, ובכל זאת אינן גובות מנכסים משועבדים, ודאי שאינן זכאיות ליטול ממטלטלים השייכים ליתומים!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 לא התכוונתי לתמרים ממש המונחים במחצלות אלא \u0003דחזייא לבודיא קאמינא\u0004 \u0005[\u0006תמרים בשלים \u0005הראויים למחצלות,\u0006 שעומדים להקצץ \u0005אמרתי],\u0006 שכיון שעדיין הם מחוברים, אינם נחשבים כמטלטלים."],["\u0003סוף סוף, כל העומד לגזוז כגזוז דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ולכן תמרים כאלה דינן כבר עתה כמטלטלים, ואין גובים ממטלטלים! אמר לו רב יוסף: \u0003דצריכא לדיקלא קאמינא\u0004 \u0005[ש\u0006הפירות עדיין \u0005צריכים לדקל אמרתי]\u0006 וקרובים לגמר בישולם, וכיון שהם עדיין מחוברים — נותנים אותם למזונות היתומות.","מסופר: \u0003ההוא\u0004 \u0005[אותם]\u0006 \u0003יתום ויתומה\u0004 קטנים \u0003דאתו לקמיה\u0004 \u0005[שבאו לפני]\u0006 \u0003רבא אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא: העלו ליתום\u0004 מזונות יתירים כדי שיהיה מספיק גם \u0003בשביל\u0004 ה\u0003יתומה. אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לרבא: והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 זה ש\u0003אמר\u0004 שגובים \u0003ממקרקעי\u0004 \u0005[מקרקעות]\u0006 \u0003ולא ממטלטלי\u0004 \u0005[ממטלטלים],\u0006 \u0003בין למזוני\u0004 \u0005[למזונות]\u0006 \u0003בין לכתובה ובין לפרנסה\u0004 (נדוניה) של הבנות, ושם לא היו אלא מטלטלים!","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אילו רצה\u0004 יתום זה \u0003שפחה לשמשו\u0004 (לשרתו) \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא יהבינן ליה\u0004 \u0005[היינו נותנים לו]?\u0006 והיינו מוציאים מהרכוש לצורך זה, \u0003כל שכן הכא דאיכא תרתי\u0004 \u0005[כאן שיש שתיים],\u0006 שהיא אחותו והיא תשרת אותו, ואם כן אנו עושים דבר שהוא לתועלת היתום וגם לתועלת היתומה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אחד נכסים שיש להן אחריות\u0004 (כלומר, קרקעות) \u0003ואחד נכסים שאין להן אחריות\u0004 (מטלטלין) — \u0003מוציאין\u0004 מן היורשים היתומים \u0003למזון אשה ולבנות,\u0004 אלו \u0003דברי רבי. ר' שמעון בן אלעזר אומר: נכסים שיש להן אחריות,\u0004 קרקעות — \u0003מוציאין ל\u0004צורך ה\u0003בנות מן הבנים\u0004 שירשו, \u0003ולבנות מן הבנות,\u0004 שאם היו למת רק בנות, לוקחים מן הבנות הגדולות ונותנים לבנות הקטנות חלק שווה בירושה. \u0003ו\u0004כן \u0003לבנים\u0004 הקטנים \u0003מן הבנים\u0004 הגדולים,","\u0003ולבנים מן הבנות בנכסים מרובין,\u0004 שיש שם ירושה מספיקה לבנות כדי לשלם את כל התחייבויות האב כלפיהן. \u0003אבל לא\u0004 נותנים \u0003לבנים מן הבנות בנכסים מועטין\u0004 שאינם מספיקים אלא למזונות הבנות.","אבל \u0003נכסים שאין להן אחריות מוציאין לבנים\u0004 הקטנים \u0003מן הבנים\u0004 הגדולים, \u0003ולבנות מן הבנות, ולבנים מן הבנות, אבל לא\u0004 נותנים \u0003לבנות מן הבנים,\u0004 שעל פי תנאי הכתובה אין לבנות זכות לקבל מזונות מירושה של מטלטלים.","ומעירים: \u0003אף על גב דקיימא לן\u0004 \u0005[אף על פי שמוחזק בידינו]\u0006 ש\u0003הלכה כרבי מחבירו,\u0004 והיתה צריכה להיות הלכה כמותו במחלוקתו עם ר' שמעון בן אלעזר, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003הלכה כר' שמעון בן אלעזר.\u0004 שכן \u0003אמר רבא: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003ממקרקעי\u0004 \u0005[מקרקעות]\u0006 \u0003ולא ממטלטלי\u0004 \u0005[ממטלטלים]\u0006 \u0003בין לכתובה בין למזוני בין לפרנסה\u0004 (נדוניה).","אם מפני סיבה כל שהיא \u0003לא כתב לה\u0004 הבעל \u0003כתובה,\u0004 הרי אם נישאה לו כשהיא \u0003בתולה\u0004 ונתאלמנה או נתגרשה \u0003גובה\u0004 מנכסיו \u0003מאתים\u0004 דינר, \u0003ו\u0004אם נישאה כשהיא \u0003אלמנה\u0004 אינה גובה אלא \u0003מנה\u0004 (מאה דינר), \u0003מפני שהוא תנאי בית דין.\u0004 ואין תלוי ברצונו אלא להוסיף על סכום זה אך לא לפחות ממנו. אם \u0003כתב לה\u0004 לאשתו כשיעבוד לכתובתה \u0003שדה שוה מנה תחת\u0004 (במקום) \u0003מאתים זוז\u0004 שהוא מתחייב בכתובה, אף על פי ש\u0003לא כתב לה\u0004 נוסף לכך \u0003\"כל נכסים דאית\u0004 \u0005[שיש]\u0006 \u0003לי אחראין ל\u0004פרעון \u0003כתובתיך\" — חייב\u0004 להשלים עד מאתים גם מן הנכסים האחרים, ואינו יכול לומר שתקח רק את השדה ששועבד לכתובה, מפני \u0003שהוא תנאי בית דין,\u0004 שיתחייב באחריות כזאת.","וכן אם \u0003לא כתב לה\u0004 בכתובה: \u0003\"אם תשתבאי, אפרקינך ואותבינך\u0004 \u0005[תלקחי בשבי, אפדך ואשיבך]\u0006 להיות \u0003לי לאינתו\u0004 \u0005[לאשה]\u0006 \u0003\". ובכהנת\u0004 (אשת כהן), שאם נבעלה באונס אסורה לבעלה, כותב את הנוסח: \u0003\"אהדרינך\u0004 \u0005[אחזירך]\u0006 \u0003למדינתך\" — חייב\u0004 מכל מקום לעשות זאת, לפי \u0003שהוא תנאי בית דין.\u0004","\u0003נשבית\u0004 האשה — \u0003חייב\u0004 בעלה \u0003לפדותה. ואם אמר: \"הרי\u0004 אני נותן לה \u0003גיטה וכתובתה, ותפדה את עצמה\" — אינו רשאי,\u0004 כיון שכבר התחייב לפדות אותה משעה שנשבתה. אם \u0003לקתה\u0004 (חלתה) אשתו — \u0003חייב לרפאותה.\u0004 אבל אם \u0003אמר: \"הרי גיטה וכתובתה, תרפא את עצמה\" — רשאי,\u0004 משום שעל כך לא התחייב בשעת כתיבת הכתובה.","שואלים: משנה זו \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' מאיר היא.\u0004 ש\u0003אמר\u0004 כלל: \u0003כל הפוחת\u0004 בכתובה \u0003לבתולה ממאתים ולאלמנה ממנה — הרי זו בעילת זנות.\u0004 שסכום זה הוא תקנת חכמים קבועה, שאי אפשר לשנות אותה.","\u0003דאי\u0004 \u0005[שאם]\u0006 לשיטת \u0003ר' יהודה, האמר\u0004 \u0005[הרי אמר]\u0006 ר' יהודה: \u0003רצה, כותב לבתולה שטר של מאתים\u0004 בכתובה, \u0003והיא כותבת\u0004 מיד \u0003\"התקבלתי ממך מנה\".\u0004 כלומר, שמוחלת לו על מנה, ובפועל אינו מתחייב אלא מנה. \u0003ו\u0004כן כותב \u0003לאלמנה מנה\u0004 בכתובה \u0003והיא כותבת\u0004 לו: \u0003\"התקבלתי ממך חמשים זוז\".\u0004 ובמשנה משמע שאינו יכול לפחות מסכום הכתובה אפילו היא מסכימה.","ומקשים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה שנאמר בה: \u0003כתב לה שדה שוה מנה תחת\u0004 (במקום) \u0003מאתים זוז, ולא כתב לה \"כל נכסים דאית\u0004 \u0005[שיש]\u0006 \u0003לי\u0004 יהיו \u0003אחראין לכתובתיך\" — חייב\u0004 לשלם משאר הנכסים, לפי \u0003שהוא תנאי בית דין.\u0004 ואם כן \u0003אתאן\u0004 \u0005[הגענו]\u0006 איפוא \u0003ל\u0004שיטה אחרת של \u0003ר' יהודה,\u0004 ש\u0003אמר: אחריות טעות סופר הוא.\u0004 שכל שטר התחייבות, גם אם לא נכתבה בו אחריות לכל הנכסים — אנו מניחים שהשמטת האחריות היא טעות סופר בלבד ויש אחריות נכסים להתחייבות זו, אלא אם כן מפורש בשטר שאין בו אחריות.","\u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' מאיר — האמר\u0004 \u0005[הרי אמר]\u0006 \u0003אחריות,\u0004 כלומר, אם היא חסרה בשטר — \u0003לאו טעות סופר הוא,\u0004 וצריכים לכתוב אחריות בכל שטר ושטר. ומקור הדברים, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מצא\u0004 אדם \u0003שטרי חוב\u0004 — \u0003אם\u0004"],["\u0003יש בהן אחריות נכסים לא יחזיר\u0004 למלוה, שהרי אינו יודע ממי אבדו, ושמא כבר נפרע החוב והוחזרו ללווה וממנו אבדו, וגם אם הלווה מודה שעדיין לא פרע חובו, כיון \u0003שבית דין נפרעין מהן\u0004 מן הלקוחות, יש לחשוש שמא עשו הלווה והמלווה ביניהם קנוניה כדי לגבות מנכסים שקנו אותם הלקוחות.","אולם אם היו השטרות כאלה ש\u0003אין בהן אחריות נכסים — יחזיר, שאין בית דין נפרעין מהן\u0004 ואין גובים על ידי שטרות אלו מנכסים משועבדים, אלו \u0003דברי ר' מאיר. וחכמים אומרים: אחד זה ואחד זה לא יחזיר, שבית דין נפרעין מהן,\u0004 משום שמניחים שהעדר אחריות בשטר הוא רק טעות סופר.","ואם כן נמצא שבמשנתנו \u0003רישא\u0004 \u0005[ראשה]\u0006 כשיטת \u0003ר' מאיר וסיפא\u0004 \u0005[וסופה]\u0006 כשיטת \u0003ר' יהודה! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שכל המשנה \u0003כולה\u0004 כשיטת \u0003ר' מאיר היא, ושאני ליה\u0004 \u0005[ושונה לו]\u0006 \u0003לר' מאיר בין כתובה לשטרי\u0004 \u0005[לשטרות\u0006 אחרים\u0005],\u0006 שרק בכתובה האחריות היא תנאי קבוע וגם אם אינה כתובה הרי זו טעות סופר, מה שאין כן בשאר שטרות. אולם \u0003ומי שאני ליה\u0004 \u0005[והאם שונה לו],\u0006 לדעתו, בין כתובה לשאר שטרות?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חמשה גובין מן המחוררין\u0004 (מנכסים בני חורין, שאין עליהם שעבוד) ואין טורפים מן הלקוחות נכסים משועבדים, \u0003ואלו הן: פירות ושבח פירות,\u0004 שאם יש לאדם זכות לקבל פירות מנכס מסויים, או את הרווח הבא מן הפירות הללו — אין מוציאים לתשלום זה מנכסים משועבדים, \u0003ו\u0004כן \u0003המקבל עליו לזון את בן אשתו\u0004 או את \u0003בת אשתו\u0004 — מפרנסים אותם רק מנכסים בני חורין, \u0003ו\u0004כן \u0003גט\u0004 (שטר) \u0003חוב שאין בו אחריות, וכתובת אשה שאין בה אחריות.\u0004","ונברר, כמו מי היא שיטת ברייתא זו, \u0003מאן שמעת ליה\u0004 \u0005[מי שמעת אותו]\u0006 ש\u0003אמר\u0004 כי \u0003אחריות לאו טעות סופר הוא — ר' מאיר, וקתני\u0004 \u0005[ושנה]\u0006 בין יתר הדברים גם \u0003כתובת אשה\u0004 שאין בה אחריות, משמע שלדעת ר' מאיר אף בכתובה אין האחריות תנאי הכרחי, וממילא בהעדרה אין אומרים שזו טעות הסופר.","את הקושי בפירוש משנתנו דוחים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמשנתנו כשיטת \u0003ר' מאיר, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהיא כשיטת \u0003ר' יהודה.\u0004 ומסבירים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שהיא כשיטת \u0003ר' יהודה\u0004 אולם \u0003התם\u0004 \u0005[שם]\u0006 במשנה שממנה הקשינו מדובר באופן ש\u0003כתבה ליה\u0004 \u0005[לו]\u0006 \u0003\"התקבלתי\",\u0004 שהיא עצמה ויתרה על חלק מן הכתובה, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא כתבה ליה\u0004 \u0005[לו]\u0006 \u0003\"התקבלתי\"\u0004 — ולכן גובים ממנו את כל הסכום הקצוב לכתובה.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמשנתנו כשיטת \u0003ר' מאיר\u0004 היא, ונסביר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"חייב\" דקתני\u0004 \u0005[ששנה]\u0006 בסוף המשנה — כוונתו, שאם לא כתב אחריות נכסים, חייב לפחות לשלם \u0003מן המחוררין\u0004 (המשוחררים, מנכסים בני חורין).","שנינו במשנה שאף אם \u0003לא כתב לה\u0004 בעלה שאם יקחו אותה בשבי יפדנה ויחזירנה אליו — חייב לפדותה, משום שזה תנאי בית דין. \u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: אשת ישראל שנאנסה — אסורה לבעלה.\u0004 וטעם הדבר: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תחלתה\u0004 של הבעילה היה \u0003באונס, ו\u0004אולם \u0003סופה\u0004 היה \u0003ברצון,\u0004 שתוך הבעילה נתרצתה, ואשה שזנתה ברצון תחת בעלה — אסורה עליו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב לאבוה\u0004 \u0005[לאביו]\u0006 של \u0003שמואל:\u0004 הרי אומרים בתנאי הכתובה: \u0003\"אם תשתבאי\u0004 \u0005[תישבי],\u0006 \u0003אפרקינך ואותבינך\u0004 \u0005[אפדך ואשיבך]\u0006 \u0003לי לאינתו\u0004 \u0005[לאשה]\u0006 \u0003\",\u0004 משמע שאף שיש חשש שמא נאנסה שם — מכל מקום מותרת לבעלה ישראל ולא חוששים שמא נתרצתה בסוף! \u0003אישתיק\u0004 \u0005[שתק]\u0006 אביו של שמואל ולא ענה.","\u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רב עליה דאבוה\u0004 \u0005[עליו,\u0006 על \u0005אביו]\u0006 של \u0003שמואל\u0004 את הפסוק: \u0003\"שרים עצרו במלים וכף ישימו לפיהם\"\u0004 (איוב כט, ט). ושואלים: כיון שקרא עליו פסוק זה, משמע מכאן שאביו של שמואל עצר בדברים ונמנע מלענות, אף שהיה לו מקום להשיב על דברי רב. \u0003מאי אית ליה למימר\u0004 \u0005[מה יש לו לומר]\u0006 ולתרץ? ומשיבים: היה יכול לענות כי \u0003בשבויה הקילו,\u0004 שכיון שאין כל ודאות שאכן נאנסה בזמן השבי, לכן הקילו חכמים בשבויה, אבל באונס ודאי שמא לא הקילו.","ושואלים: אם כן, \u0003ולאבוה\u0004 \u0005[ול\u0006דעת \u0005אביו]\u0006 של \u0003שמואל אונס דשריא רחמנא\u0004 \u0005[שמתירה התורה]\u0006 לאחר מכן את האשה לבעלה \u0003היכי משכחת לה\u0004 \u0005[איך מוצא אתה אותו],\u0006 נחשוש תמיד שמא היה בסופו של דבר ברצון? ומשיבים: \u0003כגון דקאמרי\u0004 \u0005[שאומרים]\u0006 \u0003עדים\u0004 שנכחו שם בכל מהלך האונס וראו \u0003שצווחה\u0004 והתנגדה \u0003מתחלה ועד סוף\u0004 הביאה.","ומעירים: \u0003ו\u0004דעת אביו של שמואל \u0003פליגא\u0004 \u0005[חלוקה]\u0006 על \u0003רבא.\u0004 ש\u0003אמר רבא: כל שתחלתה באונס וסוף ברצון,\u0004 ו\u0003אפילו היא אומרת\u0004 לבסוף: \u0003הניחו לו, שאלמלא (לא) נזקק לה\u0004 באונס היתה \u0003היא שוכרתו\u0004 לבעול אותה, בכל זאת \u0003מותרת. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — לפי שאותו בועל במעשהו \u0003יצר אלבשה\u0004 \u0005[הלבישה],\u0006 שגרם לה שבתוך כדי הבעילה יתעורר בה יצרה, וגם יצר עז כזה שבא לה בעל כורחה נחשב כאונס.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא,\u0004 נאמר בדין הסוטה: \u0003\"\u0004ושכב איש אותה... \u0003והוא לא נתפשה\"\u0004 (במדבר ה, יג), שמדובר שם באשה שלא נתפשה באונס ולכן היא \u0003אסורה.\u0004 ומכאן, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003נתפשה\u0004 (נאנסה) — \u0003מותרת.\u0004 ומדיוק לשון הכתוב \"והיא\" משמע \u0003ויש לך אחרת, שאף על פי שלא נתפשה מותרת, ואיזו — זו כל שתחלתה באונס וסופה ברצון.\u0004 שאף על פי שלא היה הכל באונס (\"לא נתפשה\") מותרת היא, וכדברי רבא.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 המדייקת באופן אחר מאותו כתוב עצמו \u0003\"והיא לא נתפשה\" — אסורה, הא\u0004 \u0005[הרי]\u0006 \u0003נתפשה\u0004 — \u0003מותרת,\u0004 ואנחנו מדייקים מהלשון: \u0003ויש לך אחרת, שאף על פי שנתפשה — אסורה, ואיזו — זו אשת כהן\u0004 שגם אם נבעלה באונס — אסורה לבעלה.","\u0003אמר רב יהודה אמר שמואל משום\u0004 (בשם) \u0003ר' ישמעאל\u0004 דרשה נוספת על פסוק זה: \u0003\"והיא לא נתפשה\" — אסורה, הא\u0004 \u0005[הרי]\u0006 אם \u0003נתפשה — מותרת, ויש לה אחרת, שאף על פי שלא נתפשה\u0004 ושכב איש אותה, בכל זאת \u0003מותרת. ואיזו — זו שקדושיה קדושי טעות, שאפילו\u0004 אם \u0003בנה\u0004 מנישואין אלה \u0003מורכב על כתיפה — ממאנת והולכת לה,\u0004 והנישואין בטלים מעיקרם והיא מותרת לאחרים.","\u0003אמר רב יהודה: הני נשי דגנבו גנבי\u0004 \u0005[אותן הנשים שגונבים\u0006 אותן \u0005הגנבים\u0006 מבעליהן\u0005]\u0006 — \u0003שריין לגוברייהו\u0004 \u0005[מותרות לבעליהן],\u0006 שגם אם הן נבעלות להם, הרי זה באונס. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לרב יהודה: והא קא ממטיאן להו נהמא\u0004 \u0005[והרי\u0006 אנחנו רואים שבעודן שבויות \u0005מביאות\u0006 הן \u0005להם\u0006 לגנבים \u0005לחם],\u0006 משמע שברצון הן עושות! ענה להם: הן עושות זאת \u0003מחמת יראה.\u0004 ושאלו: \u0003והא קא משלחן להו גירי\u0004 \u0005[והרי הן שולחות להם חיצים],\u0006 שבמהלך הלחימה מגישות הן להם חיצים! והשיב: גם זה עושות \u0003מחמת יראה.\u0004 אולם \u0003ודאי,\u0004 אם \u0003שבקינהו ואזלן מנפשייהו\u0004 \u0005[עזבו אותן\u0006 הגנבים \u0005והן הולכות מעצמן]\u0006 חזרה אליהם — \u0003אסירן\u0004 \u0005[\u0006הן \u0005אסורות\u0006 לבעליהן\u0005],\u0006 שכבר אין זה מחמת יראה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבויי מלכות\u0004 — \u0003הרי הן\u0004 נידונות \u0003כשבויין,\u0004 שאם לוקח המלך נשים באונס לשם תשמיש — יש עליהן דין של שבויות, שודאי באונס הן נבעלות. \u0003גנובי ליסטות\u0004 \u0005[גנובות שודדים] —\u0006 \u0003אינן\u0004 נידונות \u0003כשבויין,\u0004 שיש לחשוש שמא האשה מתרצה לבועלה, וסבורה שישא אותה לאשה. ומקשים: \u0003והתניא איפכא\u0004 \u0005[והרי שנויה\u0006 ברייתא אחרת האומרת \u0005להיפך]\u0006 ששבויות מלכות אינן כשבויות, וגנובות ליסטות הרי הן כשבויות!","ומתרצים: מ\u0003מלכות\u0004 על \u0003מלכות לא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 בברייתא הראשונה מדובר \u0003במלכות אחשורוש,\u0004 כלומר, מלכות של מלך גדול שהאשה הנבעלת לו יודעת שהוא משתמש בה רק לפי שעה לתאוותו, ובודאי לא ישא אותה לאשה, ולכן הדבר נחשב כאונס. ואילו \u0003הא\u0004 \u0005[זה]\u0006 בברייתא השניה שמחשיבה זאת כנבעלת ברצון, מדובר \u0003במלכות בן נצר,\u0004 שהקים על ידי מסעות שוד וכיבושים ממלכה קטנה, ואשה עשויה לחשוב שלבסוף ישאנה.","וכן מ\u0003ליסטות\u0004 על \u0003ליסטות לא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 בברייתא הראשונה מדובר \u0003ב\u0004ליסטות של \u0003בן נצר,\u0004 שהאשה עשויה להתרצות בבעילתו שאם ישא אותה תהיה אשת מלך, \u0003הא בליסטים דעלמא\u0004 \u0005[זו,\u0006 הברייתא השניה, מדברת \u0005בשודד סתם]\u0006 שיש לשער שאין האשה מרוצה בבעילתו, שגם אם ירצה לשאתה — היא לא תחפוץ בכך. ושואלים, \u0003ובן נצר\u0004 זה, כיצד מסבירים כי \u0003התם קרי ליה\u0004 \u0005[שם\u0006 במקום אחד אתה אומר ש\u0005קוראים לו]\u0006 \u0003\"מלך\" והכא קרי ליה \"לסטים\"\u0004 \u0005[וכאן\u0006 במקום אחר אתה אומר ש\u0005קוראים לו שודד]!\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003גבי\u0004 \u0005[אצל,\u0006 בהשוואה\u0005]\u0006 ל\u0003אחשורוש לסטים\u0004 בלבד \u0003הוא, גבי לסטים דעלמא\u0004 \u0005[אצל שודד סתם]\u0006 \u0003מלך הוא\u0004 נחשב.","שנינו במשנה: \u0003ובכהנת\u0004 (אשת כהן) הוא כותב לה: \u0003\"\u0004אם תישבי — \u0003אהדרינך\u0004 \u0005[אחזירך]\u0006 \u0003למדינתך\". אמר אביי: אלמנה לכהן גדול,\u0004 אף על פי שנשאה באיסור (שהרי כהן גדול אסור באלמנה), מכל מקום, אם נשא אותה וכתב לה כתובה — \u0003חייב לפדותה,\u0004 משום \u0003שאני קורא בה\u0004 ויכול לקיים את האמור שם \u0003\"ובכהנת אהדרינך\u0004 \u0005[אחזירך]\u0006 \u0003למדינתך\",\u0004"],["\u0003ממזרת\u0004 או \u0003נתינה\u0004 הנשואה \u0003לישראל,\u0004 שגם היא יש לה כתובה וכל התנאים של הכתובה, למרות שהנישואין היו באיסור — \u0003אינו חייב לפדותה,\u0004 הואיל \u0003שאין אני קורא בה \"ואותבינך\u0004 \u0005[ואשיבך]\u0006 להיות \u0003לי לאנתו\u0004 \u0005[לאשה]\u0006 \u0003\",\u0004 שהרי היא אסורה עליו. \u0003רבא אמר:\u0004 אין הדבר כן, אלא \u0003כל שאיסור שבייה גורם לה\u0004 להיאסר — \u0003חייב לפדותה,\u0004 אבל אם \u0003איסור דבר אחר גורם לה,\u0004 כגון אלמנה לכהן גדול, שגם אם לא נשבית אסורה — \u0003אינו חייב לפדותה.\u0004","ומציעים: \u0003לימא כתנאי\u0004 \u0005[\u0006האם \u0005לומר\u0006 שיש מחלוקת \u0005תנאים]\u0006 בדבר זה, ששנינו בברייתא: \u0003המדיר את אשתו,\u0004 שנדר שלא תיהנה ממנו, שבמקרה זה חייב לגרשה, \u0003ו\u0004בינתיים \u0003נשבית\u0004 — \u0003ר' אליעזר אומר: פודה\u0004 אותה, אף על פי שבסופו של דבר הוא צריך לגרשה מחמת הנדר, \u0003ונותן לה\u0004 את \u0003כתובתה. ר' יהושע אומר: נותן לה כתובתה, ואינו פודה,\u0004 שהרי אינו יכול להחזירה אליו מחמת הנדר.","\u0003אמר ר' נתן, שאלתי את סומכוס: כשאמר ר' יהושע\u0004 ש\u0003נותן לה כתובתה ואינו פודה,\u0004 האם מדובר שם במקרה \u0003כשהדירה ולבסוף נשבית, או בנשבית\u0004 בתחילה \u0003ולבסוף הדירה?\u0004","\u0003ואמר לי: לא שמעתי\u0004 מסורת בדבר זה, \u0003ו\u0004אולם \u0003נראין\u0004 ה\u0003דברים\u0004 שמדובר שם במקרה \u0003שהדירה ולבסוף נשבית,\u0004 שבכגון זה אין ר' יהושע מחייב אותו לפדות. \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שהוא הדין ב\u0003נשבית ולבסוף הדירה — אתי לאיערומי\u0004 \u0005[יבוא להערים],\u0006 שאם רוצה להיפטר מלפדותה — ידירנה הנאה, ויתחייב רק בכתובתה.","ועתה משווים את הדברים למחלוקת אביי ורבא: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 גם \u0003במדיר אשת כהן קמיפלגי\u0004 \u0005[נחלקו]\u0006 \u0003ואביי\u0004 הוא ש\u0003אמר כר' אליעזר,\u0004 שבכל מקום שיש דרך להחזירה, מחזירה אפילו כשאסורה עליו מחמת דבר אחר, וכיון שחיובו הוא להחזירה למדינתו, צריך לעשות זאת, שאין בכך איסור, \u0003ורבא\u0004 ש\u0003אמר כר' יהושע?\u0004","ודוחים: \u0003לא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שנדרה איהי\u0004 \u0005[היא]\u0006 שלא ליהנות ממנו, \u0003וקיים לה הוא,\u0004 ששמע את הנדר ולא הפירו. ונחלקו בסברה, \u0003ר' אליעזר סבר: הוא נותן אצבע בין שיניה,\u0004 שהרי זה כאילו הוא שם אצבע בין שיניה וגרם לה שהיא נושכת אותה, שבעצם האשמה היא בו שלא התיר לה, ולכן הוא צריך לפדותה ולהחזירה למדינתה. \u0003ור' יהושע סבר: היא\u0004 עצמה \u0003נתנה אצבע בין שיניה,\u0004 שהרי היא זו שנדרה מתחילה.","ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 סבור ר' יהושע ש\u0003היא נתנה אצבע בין שיניה — כתובה\u0004 בכלל \u0003מאי עבידתה\u0004 \u0005[מה מעשיה],\u0006 מה מקומה כאן? שאם סבור הוא שזו אשמתה שלה, מדוע עליו לתת לה כתובה?","\u0003ותו\u0004 \u0005[ועוד],\u0006 הרי \u0003אמר ר' נתן, שאלתי את סומכוס: כשאמר ר' יהושע\u0004 כי \u0003נותן לה כתובתה ואינו פודה,\u0004 באיזה אופן דיבר, האם \u0003כשהדירה ולבסוף נשבית או בשנשבית ולבסוף הדירה? ואמר: לא שמעתי.\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 מדובר באופן ש\u0003נדרה איהי\u0004 \u0005[היא],\u0006 אם כן היא זו שהתחילה בדבר מרצונה ואם כן \u0003מה לי,\u0004 מה ההבדל, בין \u0003הדירה ולבסוף נשבית, מה לי\u0004 אם בתחילה \u0003נשבית ולבסוף הדירה,\u0004 הלא אין כאן חשש שמא יבוא להערים?","\u0003אלא, לעולם\u0004 יש לפרש \u0003דאדרה איהו\u0004 \u0005[שהדיר אותה הוא],\u0006 \u0003ואביי מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003ורבא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 \u0003אביי מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כך: \u0003אלמנה לכהן גדול — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003חייב לפדותה,\u0004 שיכול לקיים תנאו להחזירה למדינתה. \u0003ממזרת ונתינה לישראל — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003אינו חייב לפדותה. מדיר אשת כהן — נמי כולי עלמא לא פליגי\u0004 \u0005[גם כן הכל אינם חולקים]\u0006 ש\u0003חייב לפדותה. דהיינו\u0004 \u0005[שהוא]\u0006 כמו דין \u0003אלמנה לכהן גדול,\u0004 שהרי יכול לקיים התנאי להחזירה למדינתה.","\u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה רק \u0003במדיר אשת ישראל. ר' אליעזר אזיל בתר מעיקרא\u0004 \u0005[הולך אחר ההתחלה],\u0006 שכיון שבתחילה, בזמן שכתב את הכתובה, היתה לו אפשרות להחזירה אליו כאשתו, הרי ההתחייבות הזו קיימת, אף כי עכשיו אינו יכול לעשות זאת מחמת הנדר. \u0003ור' יהושע אזיל בתר\u0004 \u0005[הולך אחר\u0006 מה שקורה\u0005]\u0006 \u0003בסוף,\u0004 וכיון שבסוף, בגלל הנדר, אינו יכול להחזירה להיות לו לאשה — בטל התנאי ואינו צריך לפדותה.","וכן \u0003רבא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003אלמנה לכהן גדול\u0004 ו\u0003ממזרת ונתינה לישראל — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003אינו חייב לפדותה,\u0004 שהרי איסורן בא מחמת דבר אחר ולא בגלל השבי. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003במדיר\u0004 את אשתו, \u0003בין אשת כהן ובין אשת ישראל.\u0004","\u0003ר' אליעזר אזיל בתר מעיקרא\u0004 \u0005[הולך אחר ההתחלה]\u0006 וכיון שבהתחלה עם כתיבת הכתובה התחייב להחזירן — הוא צריך לעשות זאת, \u0003ור' יהושע אזיל בתר\u0004 \u0005[הולך אחר\u0006 המצב\u0005]\u0006 \u0003בסוף.\u0004 וכיון שאינו יכול לקיים את התנאי להשיבן לביתו מחמת איסור שאינו תלוי בשבי, אלא מחמת שהדירה, — פטור לגמרי.","שנינו במשנה שאם \u0003נשבית\u0004 אשתו — \u0003חייב לפדותה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נשבית\u0004 אשה \u0003בחיי בעלה, ואחר כך מת בעלה\u0004 בלי שהספיק לפדותה. אם \u0003הכיר בה בעלה,\u0004 כלומר, נודע לבעלה טרם מותו שנשבתה — \u0003יורשין חייבין לפדותה. לא הכיר בה בעלה — אין יורשין חייבין לפדותה.\u0004","ומספרים: \u0003לוי סבר למיעבד עובדא כי הא מתניתא\u0004 \u0005[חשב לעשות מעשה כמו הברייתא הזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: הכי\u0004 \u0005[כך]\u0006 \u0003אמר חביבי\u0004 \u0005[דודי\u0006 ר' חייא\u0005]:\u0006 \u0003לית הלכתא כי הא מתניתא\u0004 \u0005[אין הלכה כברייתא זו],\u0006 \u0003אלא כי הא דתניא\u0004 \u0005[כמו זו ששנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003נשבית לאחר מיתת בעלה — אין היתומין חייבין לפדותה. ולא עוד, אלא אפילו נשבית בחיי בעלה\u0004 ונודע לו הדבר \u0003ואחר כך מת בעלה — אין היתומין חייבין לפדותה.\u0004 ומדוע — \u0003שאין אני קורא בה\u0004 את התנאי הכתוב בכתובה \u0003\"ואותבינך לאינתו\u0004 \u0005[ואחזירך לאשה]\u0006 \u0003\",\u0004 וכיון שאי אפשר לקיים תנאי זה, בטלה חובת הפדיון.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נשבית, והיו\u0004 השובים \u0003מבקשין ממנו,\u0004 מבעלה, \u0003עד עשרה בדמיה,\u0004 כלומר, פי עשרה מהמחיר הראוי לשבויה כזו, \u0003פעם ראשונה\u0004 שנשבתה — \u0003פודה, מכאן ואילך,\u0004 כלומר, אם נשבתה פעם שניה \u0003רצה — פודה, רצה — אינו פודה,\u0004 שלא תיקנו חובת פדיון אלא פעם אחת. \u0003רבן שמעון בן גמליאל אומר:\u0004"],["\u0003אין פודין את השבויין יותר על כדי דמיהם מפני תקון העולם.\u0004 שאם יבואו לפדות את השבויים במחירים גבוהים מאוד — יגרום הדבר שיבואו לשבות אנשים נוספים. על כל פנים נדייק מכאן \u0003הא\u0004 \u0005[הרי]\u0006 אם ביקשו \u0003בכדי דמיהן — פודין, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003פרקונה\u0004 \u0005[\u0006סכום כסף \u0005פדיונה]\u0006 \u0003יותר על כתובתה.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו שאינו פודה יותר מדמי כתובתה: \u0003נשבית, והיו מבקשין ממנו עד\u0004 (פי) \u0003עשרה בכתובתה — פעם ראשונה פודה, מכאן ואילך, רצה — פודה, רצה — אינו פודה. רבן שמעון בן גמליאל אומר: אם היה פרקונה כנגד כתובתה — פודה, אם לאו — אינו פודה\u0004 אלא נותן לה כתובתה! והטעם, משום שלא ייתכן שיהיה התנאי שבכתובה (התחייבותו לפדותה), שהוא טפל, יתר על הכתובה עצמה שהיא העיקר.","ומשיבים: אין זו סתירה, אלא \u0003רבן שמעון בן גמליאל תרי קולי אית ליה\u0004 \u0005[שתי קולות יש לו]\u0006 בדין פדיון, אחת לגבי סכום הפדיון בכלל, שאינו פודה ביותר מכדי דמיה, והשניה שאין הוא נותן בפדיונה יותר מדמי כתובתה.","שנינו במשנה שאם \u0003לקתה\u0004 \u0005[חלתה]\u0006 — \u0003חייב לרפאותה. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלמנה\u0004 שהיתה \u0003ניזונת מנכסי יתומין וצריכה רפואה — הרי\u0004 הרפואה \u0003היא כמזונות\u0004 ומוטל עליהם גם לשלם עבור רפואתה. \u0003רבן שמעון בן גמליאל\u0004 מחלק ו\u0003אומר: רפואה שיש לה קצבה,\u0004 כלומר, שיש סכום קבוע בשביל לרפא אותה — \u0003נתרפאת מכתובתה\u0004 ומנכים מסכום הכתובה. רפואה \u0003שאין לה קצבה — הרי היא כמזונות,\u0004 ונותנים לה כפי צורכה.","\u0003אמר ר' יוחנן: עשו\u0004 דין \u0003הקזת דם בארץ ישראל כרפואה שאין לה קצבה,\u0004 והיא כמזונות, והיורשים משלמים. מסופר: \u0003קריביה\u0004 \u0005[קרובו]\u0006 של \u0003ר' יוחנן הוה להו איתת אבא\u0004 \u0005[היתה להם אשת אב]\u0006 \u0003דהות\u0004 \u0005[שהיתה]\u0006 \u0003צריכה רפואה כל יומא\u0004 \u0005[יום]\u0006 והיו להם הוצאות מרובות לרפואתה. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יוחנן\u0004 לשאול. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איזילו קוצו ליה מידי\u0004 \u0005[לכו\u0006 ו\u0005קיצבו לו דבר,\u0006 סכום מסויים\u0005]\u0006 \u0003לרופא\u0004 עבור כלל הוצאות רפואתה לתמיד, ואז יהיה זה בגדר של רפואה שיש לה קיצבה, ותוכלו לנכות אותה מן הכתובה.","אחר כך \u0003אמר ר' יוחנן\u0004 בצער: \u0003עשינו עצמינו כעורכי הדיינין\u0004 המסייעים לאדם לטעון בדינו, שהצטער על שנתן עצה בהלכה לבעל דין. ושואלים: \u0003מעיקרא מאי סבר ולבסוף מאי סבר\u0004 \u0005[מתחילה\u0006 כאשר נתן להם עצה זו \u0005מה חשב, ולבסוף\u0006 שהתחרט \u0005מה חשב]?\u0006 ומסבירים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003סבר\u0004 הלא נאמר: \u0003\"ומבשרך לא תתעלם\"\u0004 (ישעיה נח, ז), שצריך אדם לסייע לקרוביו, \u0003ולבסוף סבר: אדם חשוב שאני\u0004 \u0005[שונה],\u0006 שאם עושה הוא דבר כזה, הריהו נראה כעורכי הדיינים, ולא היה צריך לעשות זאת.","\u0003לא כתב לה\u0004 בכתובה \u0003\"בנין דכרין דיהוו ליכי מינאי אינון ירתון\u0004 \u0005[בנים זכרים שיהיו לך ממני הם יירשו]\u0006 \u0003כסף כתובתיך יתר על חולקהון\u0004 \u0005[חלקם]\u0006 בירושה שהם נוטלים \u0003עם אחוהון\u0004 \u0005[אחיהם]\u0006 \u0003\"\u0004\u0005—\u0006 \u0003חייב\u0004 לתת להם, לפי \u0003שהוא תנאי בית דין\u0004 שיהא כתוב כך, ואף שלא כתב זאת, אין הדבר גורע מהתחייבותו. וכן אם לא כתב לה \u0003\"בנן נוקבן דיהוין ליכי מינאי יהוין יתבן בביתי ומיתזנן\u0004 \u0005[בנות נקבות שיהיו לך ממני יהיו יושבות בביתי וניזונות]\u0006 \u0003מנכסי עד דתלקחון לגוברין\u0004 \u0005[שתילקחנה,\u0006 תינשאנה \u0005לבעלים]\u0006 \u0003\" — חייב\u0004 לעשות זאת, לפי \u0003שהוא תנאי בית דין.\u0004","וכן אם השמיט בכתובה את התנאי \u0003\"את תהא יתבא\u0004 \u0005[תהיי יושבת בביתי]\u0006 \u0003בביתי ומיתזנא\u0004 \u0005[וניזונת]\u0006 \u0003מנכסי כל ימי מיגר אלמנותיך\u0004 \u0005[מגורייך כאלמנה]\u0006 \u0003בביתי\"\u0004 — \u0003חייב\u0004 היורש לעשות כן, לפי \u0003שהוא תנאי בית דין.\u0004 ומעירים: \u0003כך היו אנשי ירושלים כותבין\u0004 בנוסח זה, שהאלמנה נשארת בבית בעלה כל ימי אלמנותה וכן \u0003אנשי גליל היו כותבין כאנשי ירושלים. אנשי\u0004 ארץ \u0003יהודה היו כותבין\u0004 בנוסח הכתובה: \u0003\"עד שירצו היורשין ליתן לך כתובתיך\". לפיכך אם רצו\u0004 ה\u0003יורשין\u0004 שלא תדור בבית ולא תיזון מכסף הירושה — \u0003נותנין לה כתובתה ופוטרין אותה,\u0004 והיא צריכה לדאוג לעצמה למגורים ולמזונות.","\u0003אמר ר' יוחנן משום\u0004 (בשמו של) \u0003ר' שמעון בן יוחאי: מפני מה התקינו כתובת בנין דכרין\u0004 \u0005[בנים זכרים],\u0006 שבני האשה יורשים את כתובתה (ובכלל זה הנדוניה שהביאה בנישואיה), יתר על חלקם בירושת האב — \u0003כדי שיקפוץ אדם ויכתוב לבתו\u0004 נדוניה גדולה \u0003כ\u0004מו החלק של ירושת \u0003בנו,\u0004 שהרי הוא מובטח שכסף זה יישאר תמיד בידי צאצאיו.","ושואלים: \u0003ומי איכא מידי דרחמנא אמר ברא לירות\u0004 \u0005[והאם יש דבר שהתורה אמרה\u0006 ש\u0005הבן יירש]\u0006 ואילו \u0003ברתא\u0004 \u0005[הבת]\u0006 \u0003לא תירות\u0004 \u0005[תירש],\u0006 \u0003ואתו רבנן ומתקני דתירות ברתא\u0004 \u0005[ובאו חכמים ומתקנים שתירש הבת]?\u0006 שהרי בפועל הם גרמו לכך שהבת יורשת נכסים כמו הבן!","ומשיבים: \u0003הא נמי דאורייתא\u0004 \u0005[גם\u0006 דבר \u0005זה מן התורה]\u0006 \u0003הוא, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"קחו נשים והולידו בנים ובנות וקחו לבניכם נשים ואת בנותיכם תנו לאנשים\"\u0004 (ירמיה כט, ו), ויש לשאול על כתוב זה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בנים בידיה קיימי\u0004 \u0005[בידו\u0006 הם \u0005עומדים],\u0006 שהוא מחפש ומוצא להם נשים, שהרי מדרך האיש לחפש לו אשה. \u0003אלא בנתיה מי קיימן בידיה\u0004 \u0005[האם\u0006 הן \u0005עומדות\u0006 נמצאות \u0005בידו]\u0006 שהוא יכול למצוא להן בעלים? שהרי אין דרך האשה לחזר אחר האיש!","אלא \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 \u0003דנלבשה וניכסה וניתיב\u0004 \u0005[שילבישנה ויכסנה ויתן]\u0006 \u0003לה מידי\u0004 \u0005[דבר,\u0006 רכוש\u0005]\u0006 \u0003כי היכי דקפצי עלה ואתו נסבי לה\u0004 \u0005[כדי שיקפצו עליה ויבואו ויישאו אותה],\u0006 הרי שמן הכתוב האומר לתת את הבנות לאנשים משמע שצריך להשתדל בזה, ולכתוב לה נדוניה כדי שירצו לקחתה. ושואלים: \u0003ועד כמה,\u0004 מה השיעור של נתינה זו לבנות? \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003עד לעישור נכסי\u0004 \u0005[לעשירית\u0006 מן \u0005הנכסים]\u0006 נותנים לבת כנדוניה.","ושואלים: אם זה הוא טעם תקנת כתובת בנין דכרין, אולי \u0003ואימא\u0004 \u0005[ונאמר]:\u0006 את מה שנתן ה\u0003אב\u0004 בנדוניה \u0003לירות\u0004 \u0005[יירשו\u0006 הבנים\u0005],\u0006 אבל של ה\u0003בעל,\u0004 כלומר, חלק הכתובה שהבעל נותן משלו, \u0003לא לירות\u0004 \u0005[יירשו\u0006 הבנים\u0005]!\u0006 ומשיבים: \u0003אם כן\u0004 יעשו, שלא ירשו בני האשה את חלק הכתובה שמתחייב לה בעלה, ה\u0003אב נמי מימנע\u0004 \u0005[גם כן יימנע]\u0006 \u0003ולא כתב\u0004 \u0005[יכתוב],\u0006 שאם אינם יורשים את כתובת הבעל, גם האב איננו רוצה לתת הרבה.","ושואלים עוד: אם אכן זה החשש שימנע האב לכתוב, אם כן \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003כתב אב\u0004 ונתן לבת נדוניה גדולה — \u0003לכתוב\u0004 \u0005[שיכתוב]\u0006 גם ה\u0003בעל\u0004 בכתובה תנאי זה של ירושת הנדוניה, ואולם \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003לא כתב\u0004 ה\u0003אב\u0004 — \u0003לא לכתוב\u0004 \u0005[יכתוב]\u0006 גם ה\u0003בעל!\u0004 ומשיבים: \u0003לא פלוג רבנן\u0004 \u0005[חילקו חכמים]\u0006 שאף שעיקר התקנה היה כדי לעודד את האבות לכתוב נדוניה גדולה — לא חילקו חכמים, וכיון שרוב הנשים יש להן נדוניה, הדין שווה בכל הנשים.","ושואלים: אם הכוונה היא שיישאר ממון הכתובה ברשות צאצאי האשה, אזי כשיש לו \u0003בת\u0004 מאשה אחת \u0003בין הבנים\u0004 מאשה אחרת \u0003נמי תירות\u0004 \u0005[גם כן תירש]\u0006 נדוניית אמה, ומדוע רק הבנים הזכרים יורשים את דמי הכתובה? ומשיבים: \u0003כ\u0004דין \u0003נחלה שויוה רבנן\u0004 \u0005[עשו אותה חכמים]\u0006 וכפי שבנחלה רגילה הבנים יורשים ולא הבנות, אף בכתובה כך.","ושואלים: מדוע לא נאמר שלפחות \u0003בת בין הבנות תירות\u0004 \u0005[תירש]\u0006 שאם היתה לו מאשה זו בת, וגם שאר ילדיו מאשה אחרת הן בנות, ואז כולן יורשות, שתקבל בת זו את מה שכתב סבה כנדוניה לאמה! ומשיבים: \u0003לא פלוג רבנן\u0004 \u0005[חילקו חכמים]\u0006 בתקנתם. ועוד שואלים: \u0003ותיגבי\u0004 \u0005[ושתיגבה]\u0006 כתובת בנין זכרים גם \u0003ממטלטלי\u0004 \u0005[ממטלטלים]\u0006 וכגון באופן שהשאיר רק מטלטלים! ומדוע להלכה אינם יורשים את אמם אלא מן הקרקע שהביאה עמה בנדונייתה? ומשיבים: \u0003ככתובה\u0004 רגילה \u0003שויוה רבנן\u0004 \u0005[עשו אותה חכמים]\u0006 שנגבית רק מן הקרקעות.","ועוד שואלים: \u0003תטרוף\u0004 (תגבה) גם \u0003ממשעבדי\u0004 \u0005[מ\u0006נכסים \u0005משועבדים]!\u0006 ומשיבים: \u0003\"ירתון\" תנן\u0004 \u0005[\"יירשו\" שנינו]\u0006 ודין ירושה הוא רק בנכסים המצויים לפניהם ואינם יורשים נכסים שמכר האב. ושואלים: מכיון שזה הוא הטעם לתנאי כתובה זו, \u0003ואימא אף על גב דליכא\u0004 \u0005[ואמור\u0006 שירושת כתובת האם תהיה \u0005אף על פי שאין]\u0006 בנכסים שהשאיר האב ירושה, \u0003מותר\u0004 של \u0003דינר\u0004 יתר על דמי כתובת שתי נשיו. שהרי אמרו חכמים שכאשר פרט לסכום הכתובות לא נשארו כלל נכסים כלשהם לירושה, מתבטלת תקנת \"בנין דכרין\", וכל הבנים מתחלקים בירושה כדין תורה! ומשיבים: \u0003במקום דקא מיעקרא\u0004 \u0005[שנעקר]\u0006 בו לגמרי דין \u0003נחלה דאורייתא\u0004 \u0005[שמן התורה]\u0006 כתוצאה מדין ירושה שמדברי סופרים (כתובת בנין דכרין), \u0003לא תקינו רבנן\u0004 \u0005[תיקנו חכמים]\u0006 תנאי זה של כתובת בנין דכרין.","מסופר: \u0003רב פפא איעסק ליה לבריה בי\u0004 \u0005[היה עסוק\u0006 בהשאת \u0005בנו\u0006 לאחת מבנות \u0005בית]\u0006 \u0003אבא סוראה\u0004 \u0005[מ\u0006העיר \u0005סורא].\u0006 \u0003אזיל למיכתב לה\u0004 \u0005[הלך ל\u0006סדר לאשה את \u0005כתיבת]\u0006 \u0003כתובתה. שמע יהודה בר מרימר\u0004 שבא רב פפא למקום, \u0003נפק אתא איתחזי ליה\u0004 \u0005[יצא, בא,\u0006 ו\u0005נראה לו]\u0006 מפני כבודו לקבל את פניו. \u0003כי מטו לפיתחא, הוה קא מפטר מיניה\u0004 \u0005[כאשר באו לפתח\u0006 של אבא סוראה, אביה, \u0005נפרד ממנו]\u0006 יהודה בר מרימר ולא רצה להיכנס. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003ניעול מר בהדאי\u0004 \u0005[יכנס אדוני אתי]\u0006 פנימה!"],["\u0003חזייה\u0004 \u0005[ראהו]\u0006 רב פפא ש\u0003לא הוה ניחא ליה\u0004 \u0005[היה נוח לו]\u0006 ליהודה בר מרימר להיכנס, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי דעתיך\u0004 \u0005[מה דעתך],\u0006 מדוע אינך נכנס — אם \u0003משום\u0004 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב יהודה: שיננא\u0004 \u0005[גדול השיניים],\u0006 \u0003לא תיהוי בעבורי אחסנתא\u0004 \u0005[אל תהיה\u0006 שותף \u0005בהעברת ירושה]\u0006 \u0003אפילו מברא בישא לברא טבא\u0004 \u0005[מבן רע לבן טוב],\u0006 והטעם — ש\u0003לא ידיעא\u0004 \u0005[ידוע]\u0006 \u0003מאי זרעא נפיק מיניה\u0004 \u0005[איזה זרע יצא ממנו],\u0006 ושמא מבניו של הבן הרע יצאו ילדים מעולים, \u0003וכל שכן\u0004 שלא תשתתף בהעברת ירושה \u0003מברא לברתא\u0004 \u0005[מבן לבת],\u0006 ואתה חושש שמא על ידי בואך יתן רב אבא סוראה נדוניה גדולה יותר לבתו, אולם","\u0003האי נמי תקנתא דרבנן\u0004 \u0005[זו גם כן תקנת חכמים]\u0006 \u0003היא\u0004 שהאב כותב לבתו נדוניה, ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' שמעון בן יוחי\u0004 לעיל: כדי שיקפוץ וכו'. \u0003אמר ליה\u0004 \u0005[לו]\u0006 יהודה בר מרימר: \u0003הני מילי מדעתיה, לעשוייה נמי\u0004 \u0005[דברים אלה\u0006 אמורים כשאדם נותן \u0005מדעתו,\u0006 אבל \u0005לאלץ אותו גם כן]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003אטו מי קאמינא\u0004 \u0005[וכי אמרתי]\u0006 \u0003לך דעול ועשייה\u0004 \u0005[שתיכנס ותאלץ אותו]?\u0006 \u0003עול ולא תעשייה קאמינא\u0004 \u0005[היכנס ואל תאלץ אותו אמרתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 יהודה בר מרימר: \u0003מעלאי דידי היינו עשייה\u0004 \u0005[כניסתי שלי זו\u0006 תהיה \u0005כפייתו],\u0006 שבשביל כבודי ירבה במתן נדוניה.","בסופו של דבר \u0003אכפייה ועול\u0004 \u0005[כפה אותו\u0006 רב פפא ליהודה בר מרימר \u0005ונכנס].\u0006 \u0003אישתיק ויתיב\u0004 \u0005[שתק וישב]\u0006 כל אותו זמן ולא אמר דבר. \u0003סבר ההוא מירתח רתח\u0004 \u0005[חשב\u0006 אבא סוראה שיהודה בר מרימר \u0005כועס]\u0006 עליו, וסבור כי איננו נותן נדוניה ראויה. \u0003כתביה לכל מאי דהוה ליה\u0004 \u0005[כתב\u0006 בנדוניה \u0005את כל מה שהיה לו]\u0006 כדי שיתרצה. \u0003לסוף\u0004 \u0005[בסוף]\u0006 כשעדיין שתק יהודה \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבא סוראה: \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003לא מישתעי מר\u0004 \u0005[מדבר אדוני]?\u0006 \u0003חיי דמר\u0004 \u0005[אדוני],\u0006 \u0003לא שביקי\u0004 \u0005[הנחתי]\u0006 \u0003מידי לנפשאי\u0004 \u0005[דבר לעצמי].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 יהודה: \u0003אי מינאי דידי\u0004 \u0005[אם ממני\u0006 מדעתי \u0005שלי]\u0006 אתה עושה, כלומר, אילו היית מתייעץ איתי מראש — \u0003אפילו האי נמי דכתבת\u0004 \u0005[גם זה מה שכתבת]\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי.\u0004 כיון שהבין אבא סוראה את הדבר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבא סוראה: \u0003השתא נמי אהדר\u0004 \u0005[עכשיו גם כן אחזור]\u0006 \u0003בי,\u0004 כיון שעשיתי כל זה בטעות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 יהודה בר מרימר: \u0003שוייה נפשך הדרנא\u0004 \u0005[\u0006ש\u0005תעשה\u0006 את \u0005עצמך\u0006 לאדם ש\u0005חוזר\u0006 בו מדיבורו\u0005]\u0006 — \u0003לא קאמינא\u0004 \u0005[אמרתי],\u0006 שכיון שכבר עשית כך — עשית, אבל לא לרצוני היה הדבר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב יימר סבא\u0004 \u0005[הזקן]\u0006 \u0003מרב נחמן:\u0004 אשה ש\u0003מכרה כתובתה לבעלה,\u0004 שמכרה לבעלה את הזכות שאם תתגרש או תתאלמן לא יצטרך לשלם לה כתובה, האם \u0003יש לה כתובת בנין דכרין או אין לה כתובת בנין דכרין?\u0004 האם יורשים בניה את חלק הנדוניה שהביאה מבית אביה כפי שמצויין בכתובתה, יתר על אחיהם מאשה אחרת? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ותבעי לך\u0004 \u0005[ותישאל לך]\u0006 השאלה גם ביחס ל\u0003מוחלת:\u0004 אשה שמחלה את כתובתה לבעלה מרצונה, מה יהא הדין ביחס לכתובת בנין דכרין?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יימר: \u0003השתא\u0004 \u0005[עכשיו],\u0006 הרי דין \u0003מוכרת קמיבעיא\u0004 \u0005[מסופק]\u0006 \u0003לי דאף על גב דאיכא למימר זוזי אנסוה\u0004 \u0005[שאף על פי שיש\u0006 מקום \u0005לומר\u0006 כי \u0005הכסף\u0006 הוא ש\u0005אנס אותה],\u0006 שהיתה זקוקה לפי שעה לכסף, ובאונס היא מוכרת, \u0003דאמינא כמאן דקא מחו לה מאה עוכלי בעוכלא\u0004 \u0005[שאני אומר\u0006 שהיא \u0005כמי שמכים אותה מאה מכות במשקולת]\u0006 שעושה רק בעל כורחה, ובכל זאת אני מסתפק אם ויתרה גם על תנאי בנין דכרין, \u0003מוחלת מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006 שמסתבר שכיון שמחלה על כתובתה מרצונה, ודאי מחלה גם על כתובת בנין דכרין.","\u0003אמר רבא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי\u0004 שאם \u0003מוכרת כתובתה לאחרים\u0004 ולא לבעלה, אלא לאיש אחר, הרוצה לקנות ממנה את הזכות שאולי בסוף תתגרש או תתאלמן והוא יקבל את כתובתה — \u0003יש לה כתובת בנין דכרין\u0004 \u0005[בנים זכרים].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003זוזי\u0004 \u0005[הכספים]\u0006 הם ש\u0003אנסוה\u0004 למכור, ולא התכוונה לוותר על הכל. וכן ברור לי כי \u0003מוחלת כתובתה לבעלה אין לה כתובת בנין דכרין\u0004 \u0005[בנים זכרים],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003אחולי אחילתא\u0004 \u0005[מחלה אותה]\u0006 את הכל ואינה רוצה לתבוע מבעלה דבר.","אלא \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: מוכרת כתובתה לבעלה, כמוכרת לאחרים דמי\u0004 \u0005[נחשב]\u0006 ולא ויתרה על כתובת בנין דכרין, \u0003או כמוחלת לבעלה דמי\u0004 \u0005[נחשב]\u0006 שמחלה הכל? \u0003בתר דבעיא הדר פשטא\u0004 \u0005[אחר ששאל\u0006 את השאלה \u0005חזר ופשט\u0006 אותה\u0005]:\u0006 \u0003מוכרת כתובה לבעלה כמוכרת לאחרים דמי\u0004 \u0005[נחשבת],\u0006 שברור שעשתה זאת מפני דוחק כספי.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אידי בר אבין:\u0004 שנינו במשנה שאשה שהלך בעלה למדינת הים, והעיד לה עד אחד שמת, והלכה ונישאה על פי עדות זו לאחר, ואחר כך חזר בעלה — חייבים שניהם (הבעל הראשון והאחרון) לגרש אותה, ואין לה כתובה משניהם. ונאמר שם: אם \u0003מתה — אין\u0004 ה\u0003יורשין של זה\u0004 (של הבעל הראשון) \u0003ואין\u0004 ה\u0003יורשין של זה\u0004 (של הבעל השני) \u0003יורשין\u0004 את \u0003כתובתה. והוינן\u0004 \u0005[והיינו עוסקים\u0006 ומתקשים\u0005]\u0006 \u0003בה\u0004 בשאלה זו: \u0003כתובתה מאי עבידתה\u0004 \u0005[מה מעשיה]?!\u0006 הרי אמרנו שאין לה כתובה, ואם כן מה יש להם לרשת?","\u0003ואמר רב פפא:\u0004 הכוונה היא ל\u0003כתובת בנין דכרין\u0004 \u0005[בנים זכרים].\u0006 שלא זו בלבד שאיבדה כתובתה, אלא שאף את זכות כתובת בנין דכרין איבדה, ובניה אינם יורשים אותה כלל. ולפי מה שאמרנו שאם מכרה כתובתה לא ויתרה על כתובת בנין דכרין, אפשר לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הכא נמי לימא\u0004 \u0005[כאן גם כן נאמר]\u0006 שה\u0003יצר אנסה,\u0004 כיון שרצתה כבר להינשא לאחר שחשבה שמת בעלה, ומדוע מפסידה את כתובת בנין דכרין!","ומשיבים: \u0003התם קנסא\u0004 \u0005[שם קנס]\u0006 \u0003הוא\u0004 ש\u0003קנסוה רבנן\u0004 \u0005[חכמים],\u0006 כלומר, שם אין סיבת הדבר שכיון שאיבדה את כתובתה איבדה גם כל תנאי כתובה, אלא הטעם הוא שקנסו אותה חכמים בכמה קנסות שונים על שנישאת על פי עדותו של עד אחד בלבד ולא ביררה כיאות, ואיבוד כתובת בנין דכרין הוא אחד הקנסות, ואין איפוא להוכיח מכאן לענייננו.","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבין בר חנינא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב חסדא, ויתיב וקאמר משמיה\u0004 \u0005[וישב ואמר משמו]\u0006 של \u0003ר' אלעזר\u0004 הלכה זו: \u0003מוחלת כתובתה לבעלה —\u0004 לאחר שמת \u0003אין לה מזונות\u0004 מנכסיו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003אי לאו דקאמרת\u0004 \u0005[אם לא שאמרת]\u0006 \u0003לי\u0004 הלכה זו \u0003משמיה דגברא רבא\u0004 \u0005[משמו של אדם גדול],\u0006 \u0003הוה אמינא לך\u0004 \u0005[הייתי אומר לך]\u0006 שדבר זה הוא עוול, כפי שאומר הכתוב: \u0003\"משיב רעה תחת טובה לא תמוש רעה מביתו\"\u0004 (משלי יז, יג), שלא זו בלבד שמחלה לבעלה את כתובתה, אלא נמצאת מפסידה אף את מזונותיה?!","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב נחמן ועולא ואבימי בר רב פפי, ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב חייא בר אמי גבייהו\u0004 \u0005[עימם].\u0006 \u0003אתא ההוא גברא דשכיבא\u0004 \u0005[בא אדם אחד שמתה]\u0006 \u0003ארוסתו, אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003זיל קבר\u0004 \u0005[לך קבור]\u0006 אותה, \u0003או הב\u0004 \u0005[תן]\u0006 \u0003לה,\u0004 כלומר, ליורשיה, את \u0003כתובתה. אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חייא,\u0004 שישב איתם, ותמה על דבריהם: \u0003תנינא\u0004 \u0005[\u0006הרי \u0005שנינו]:\u0006 \u0003אשתו ארוסה\u0004 — הוא \u0003לא אונן\u0004 (אבל) \u0003ולא מיטמא לה\u0004 אם כהן הוא, \u0003וכן היא לא אוננת ולא מיטמאה לו.\u0004 ואם \u0003מתה — אינו יורשה,\u0004 ואם \u0003מת הוא\u0004 בחייה — \u0003גובה כתובתה.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003מת הוא\u0004 אולם, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003מתה היא — אין לה,\u0004 כלומר, ליורשיה, \u0003כתובה\u0004 ולא שאר תנאי כתובה, ובכלל זה שאף אינו חייב בקבורתה, שכיון שהחובה לקוברה באה תמורת ירושתו אותה, כיון שאינו יורשה, אף אינו חייב לקוברה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שהכתובה שלה בטלה כשמתה? \u0003אמר רב הושעיא: שאין אני קורא בה\u0004 את התנאי הכתוב בכתובה \u0003\"לכשתנשאי לאחר תטלי מה שכתוב ליכי\u0004 \u0005[לך]\u0006 \u0003\"\u0004— שהרי איננה יכולה להינשא לאחר.","מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ריש לקיש: ארוסה שמתה אין לה כתובה. אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי\u0004 לאלה שמסרו לו הלכה זו בשמו של רבין: \u0003זילו אמרי ליה\u0004 \u0005[לכו אמרו לו]\u0006 לרבין:"],["\u0003שקילא טיבותך שדיא אחיזרי\u0004 \u0005[נטולה טובתך\u0006 ו\u0005מוטלת על הקוצים],\u0006 כלומר, אין אנחנו צריכים להחזיק לך טובה עבור אימרה זו שמסרת לנו, כי \u0003כבר תרגמא\u0004 \u0005[תרגם,\u0006 פסק\u0005]\u0006 \u0003רב הושעיא לשמעתיך\u0004 \u0005[את ההלכה\u0006 הזו \u0005שלך]\u0006 \u0003בבבל\u0004 בעצמו.","שנינו במשנה שאחד מתנאי כתובה הוא כי \u0003\"בנן נוקבן דיהויין ליכי מינאי\u0004 \u0005[בנות נקבות שיהיו לך ממני]\u0006 יזונו מנכסיי \u0003\". רב תני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 בנוסח התנאי שהבנות יהיו ניזונות \u0003\"עד דתלקחן לגוברין\u0004 \u0005[שתלקחנה,\u0006 תינשאנה, \u0005לאנשים]\u0006 \u0003\", ולוי תני\u0004 \u0005[\u0006היה \u0005שונה]:\u0006 \u0003\"עד דתבגרן\u0004 \u0005[שתתבגרנה]\u0006 \u0003\".\u0004 ושואלים: האם הכוונה \u0003לרב\u0004 היא \u0003אף על גב דבגר\u0004 \u0005[אף על פי שבגרו]\u0006 הבנות ולא נישאו הן ניזונות? והרי בנות בוגרות אינן עוד ברשות אביהן גם אם היה חי! \u0003ולוי,\u0004 האם הוא סבור כי \u0003אף על גב דאינסיב\u0004 \u0005[אף על פי שנישאו]\u0006 הן ממשיכות לקבל מזונות כל עוד לא בגרו?!","\u0003אלא\u0004 יש לומר: כאשר \u0003בגר\u0004 \u0005[בגרו]\u0006 \u0003ולא אינסיב\u0004 \u0005[נישאו],\u0006 או כאשר \u0003אינסיב\u0004 \u0005[נישאו]\u0006 \u0003ולא בגר\u0004 \u0005[בגרו] —\u0006 \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שאין הן מקבלות. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003בארוסה ו\u0004עדיין \u0003לא בגר\u0004 \u0005[בגרה],\u0006 וסובר לוי שכיון שלא נישאו הן עדיין ברשות אביהם וניזונות משלו. \u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003לוי במתניתיה\u0004 \u0005[בברייתא שלו]\u0006 בנוסח: \u0003\"עד דתבגרן\u0004 \u0005[שתתבגרנה]\u0006 \u0003וימטי זמניהון דאינסבן\u0004 \u0005[ויגיע זמנן שתינשאנה]\u0006 \u0003\".\u0004 ושואלים: \u0003תרתי\u0004 \u0005[שנים]\u0006 וכי צריכים שני תנאים, הרי באחד מהם כבר יוצאות מרשות אביהם? \u0003אלא\u0004 יש להבין: \u0003או תבגרן\u0004 \u0005[\u0006ש\u0005תתבגרנה]\u0006 \u0003או ימטי זמניהון לאיתנסבא\u0004 \u0005[\u0006ש\u0005יגיע זמנן להינשא],\u0006 כלומר שנים עשר חודש מיום שתבעה הארוס להינשא. אבל ארוסה, כל עוד לא בגרה, הריהי ממשיכה לאכול.","ומעירים: מחלוקת זו בין רב ולוי היא \u0003כתנאי\u0004 \u0005[כ\u0006מחלוקת \u0005תנאים]\u0006 שנחלקו בשאלה זו, שכן שנינו: \u0003עד מתי הבת נזונית — עד שתארס, משום ר' אלעזר אמרו: עד שתבגר. תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בנוסח: \u0003\"עד דיהוויין\u0004 \u0005[שתהיינה]\u0006 לאנשים \u0003\".\u0004 משמעות לשון זו אינה ברורה, ולכן \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם הכוונה היא \u0003הויה\u0004 של \u0003אירוסין\u0004 (קידושין), \u0003או הויה\u0004 של \u0003נישואין?\u0004 לשאלה זו לא נמצאה תשובה, והריהי \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב יוסף: מי שמיע לך מיניה\u0004 \u0005[האם שמעת ממנו]\u0006 מ\u0003רב יהודה\u0004 באותו ענין, האם יתומה \u0003ארוסה יש לה מזונות\u0004 מן האחים, כלומר, מירושת האב, \u0003או אין לה מזונות? אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003משמע\u0004 \u0005[לשמוע]\u0006 במפורש \u0003לא שמיע לי\u0004 \u0005[שמעתי],\u0006 \u0003אלא מ\u0004צד ה\u0003סברא\u0004 נראה כי \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות מן הירושה, והטעם הוא: \u0003כיון\u0004 שבעלה \u0003אירסה, לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003דתיתזיל\u0004 \u0005[שתתבזה]\u0006 בתביעת מזונות מן הירושה, והוא עצמו מפרנס אותה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003אם משמע\u0004 \u0005[לשמוע]\u0006 את הדבר במפורש \u0003לא שמיע לך\u0004 \u0005[שמעת],\u0006 \u0003מ\u0004צד ה\u0003סברא אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 מזונות מן האחים, משום שאין הארוס נותן לה מזונות, כי \u0003כיון\u0004 ש\u0003לא קים ליה בגוה\u0004 \u0005[מוחזק לו בה],\u0006 שעדיין לא נישאה לו ממש, ויתכן שבסופו של דבר לא ירצה לשאתה, \u0003לא שדי זוזי בכדי\u0004 \u0005[איננו זורק זוזים,\u0006 כסף, \u0005לחינם]\u0006 על ארוסתו.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שמועה זו בנוסח אחר. שרב יוסף \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משמע\u0004 \u0005[לשמוע]\u0006 במפורש \u0003לא שמיע לי\u0004 \u0005[שמעתי],\u0006 אבל \u0003מ\u0004צד ה\u0003סברא אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 מזונות מן האחים, ומדוע — \u0003כיון\u0004 ש\u0003לא קים ליה בגוה\u0004 \u0005[מוחזק לו בה],\u0006 \u0003לא שדי זוזי בכדי\u0004 \u0005[איננו זורק זוזים,\u0006 כסף, \u0005לחינם].\u0006 ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003אי משמע\u0004 \u0005[לשמוע]\u0006 זאת במפורש \u0003לא שמיע לך\u0004 \u0005[שמעת],\u0006 \u0003מ\u0004צד ה\u0003סברא לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות מן הירושה, כי \u0003כיון\u0004 ש\u0003אירסה\u0004 שוב \u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003דתיתזיל\u0004 \u0005[שתתבזה]\u0006 בבקשת מזונות מן האחים, והארוס הוא שזן אותה.","\u0003סימן דגברי\u0004 \u0005[האנשים],\u0006 כלומר, סימן לשמות החכמים המוזכרים בדיון הבא הוא: \u0003שק זרף\u0004 (רב \u0003ש\u0004שת, ריש ל\u0003ק\u0004יש, ר' אלע\u0003ז\u0004ר, \u0003ר\u0004בא, רב \u0003פ\u0004פא), והבעיות שאנחנו דנים בהן הן: \u0003מאנה, ויבמה, שניה, ארוסה, ואנסה.\u0004","ואלו הן הבעיות: \u0003בעו מיניה\u0004 \u0005[שאלו ממנו],\u0006 \u0003מרב ששת: ממאנת,\u0004 כלומר, יתומה קטנה שהשיאוה אמה או אחיה ומיאנה בבעלה, ועל ידי כך היא מבטלת את הנישואין הללו, וחוזרת לבית אביה, האם \u0003יש לה מזונות\u0004 מירושת האב, \u0003או אין לה מזונות?\u0004 האם יש לראותה כאילו נישאה כבר ופקעה זכותה למזונות, או שמא כיון שהמיאון עוקר את הנישואין מעיקרם, הריהי כאילו לא נישאה כלל?","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם,\u0006 למדתם, \u0005אותה],\u0006 שכן שנינו בברייתא: קטנה שנתארסה ובטלו קידושיה, כגון שנשארה \u0003אלמנה בבית אביה,\u0004 או \u0003גרושה בבית אביה,\u0004 או \u0003שומרת יבם בבית אביה — יש לה מזונות. ר' יהודה אומר:\u0004 אם \u0003עודה בבית אביה — יש לה מזונות, אינה בבית אביה — אין לה מזונות.\u0004","ולכאורה שיטת \u0003ר' יהודה היינו\u0004 \u0005[הריהי\u0006 זהה\u0005]\u0006 לשיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 ומה ההבדל ביניהם?! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 לגבי \u0003ממאנת איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 כי \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 מזונות, ויהא דינה כגרושה מן האירוסין, שכיון שבטלו קידושיה יש לה מזונות, \u0003ור' יהודה סבר\u0004 כי \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות, שכל עוד היא בבית אביה — יש לה מזונות, אבל כיון שנישאה פעם ויצאה מבית אביה — שוב אין לה מזונות.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ריש לקיש: בת\u0004 של \u0003יבמה,\u0004 שהתייבמה האם וילדה בת, ומת היבם, האם \u0003יש לה מזונות\u0004 מנכסי היבם \u0003או אין לה מזונות?\u0004","וצדדי השאלה: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 ש\u0003כתובתה\u0004 של יבמה \u0003על נכסי בעלה הראשון\u0004 ולא מנכסי היבם, אם כן \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות מנכסי היבם, שהמזונות הם תנאי כתובה, וכשאין כתובה — גם במזונות אינו חייב. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאי לית\u0004 \u0005[שאם אין]\u0006 \u0003לה\u0004 ליבמה כדי כתובה \u0003מ\u0004נכסי הבעל ה\u0003ראשון, תקינו\u0004 \u0005[תיקנו]\u0006 \u0003לה רבנן\u0004 \u0005[חכמים]\u0006 כתובה \u0003מ\u0004ן ה\u0003שני,\u0004 אם כן \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 גם לבת מזונות, שאף תנאי זה שבכתובה חל על היבם? לשאלה זו לא נמצאה תשובה, והריהי \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: בת\u0004 של \u0003שניה\u0004 שאם נשא אשה שהיא לגביו שניה לערווה, שהם נישואין האסורים מדברי חכמים, וקנסוה חכמים שאין לה כתובה, האם בתה הנולדת ממנו \u0003יש לה מזונות, או אין לה מזונות?\u0004"],["וצדדי השאלה הם: \u0003כיון דלית\u0004 \u0005[שאין]\u0006 \u0003לה\u0004 לאם \u0003כתובה\u0004 מפני שקנסוה חכמים, אם כן \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 גם \u0003מזוני\u0004 \u0005[מזונות]\u0006 לבת, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אמה דעבדא איסורא\u0004 \u0005[שעשתה איסור] —\u0006 \u0003קנסוה רבנן\u0004 \u0005[חכמים]\u0006 שלא תקבל כתובה, ואולם \u0003איהי\u0004 \u0005[היא],\u0006 הבת, ש\u0003לא עבדא איסורא\u0004 \u0005[עשתה איסור] —\u0006 \u0003לא קנסוה רבנן\u0004 \u0005[חכמים].\u0006 והרי שאלה זו \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: בת ארוסה,\u0004 אם בא אדם על ארוסתו לפני הנישואין והוליד ממנה בת ומת, האם \u0003יש לה,\u0004 לבת זו, \u0003מזונות\u0004 מנכסי אביה, \u0003או אין לה מזונות?\u0004 וצדדי השאלה: האם לומר כי \u0003כיון דאית\u0004 \u0005[שיש]\u0006 \u0003לה\u0004 (לאמה), מעיקר הדין \u0003כתובה,\u0004 שהרי אם כתב לה כתובה מן האירוסין, זוכה היא בה, ואם כן \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 מזונות לבת, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא תקינו רבנן\u0004 \u0005[תיקנו חכמים]\u0006 לכתוב לה \u0003כתובה עד שעת נישואין,\u0004 הרי בתה של זו שלא היתה לה כתובה — \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות שהם מתנאי הכתובה, ואף זו נשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: בת\u0004 של \u0003אנוסה,\u0004 אם אנס נערה ונשא אותה ואחר כך ילדה לו בת, ומת, האם \u0003יש לה,\u0004 לבת, \u0003מזונות\u0004 מנכסיו, \u0003או אין לה מזונות?\u0004 ומעירים: \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003ר' יוסי בר' יהודה לא תיבעי\u0004 \u0005[תישאל,\u0006 תסתפק\u0005]\u0006 \u0003לך,\u0004 שהרי \u0003אמר\u0004 שאנוסה \u0003יש לה כתובה מנה,\u0004 ואם כן הרי היא ככל הנשים שיש להן גם תנאי כתובה ובכלל זה גם מזונות הבת.","\u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי היא \u0003אליבא דרבנן דאמרי\u0004 \u0005[ל\u0006שיטת \u0005חכמים שאומרים]:\u0006 \u0003יצא כסף קנסה בכתובתה,\u0004 שכיון שקיבלה את תשלומי הקנס עבור האונס שוב אין לה כתובה לעצמה, אם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין בבתה?","האם נאמר כי \u0003כיון דלית\u0004 \u0005[שאין]\u0006 \u0003לה\u0004 לאם \u0003כתובה,\u0004 אם כן גם \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה,\u0004 לבת, \u0003מזוני\u0004 \u0005[מזונות],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 תקנת \u0003כתובה\u0004 בכלל \u0003טעמא מאי\u0004 \u0005[מה הטעם]\u0006 בה — \u0003כדי שלא תהא קלה בעיניו להוציאה, והא\u0004 \u0005[וזו],\u0006 האנוסה — הלא \u0003לא מצי מפיק לה\u0004 \u0005[אינו יכול להוציא אותה]\u0006 ולגרשה, ככתוב \"לא יוכל שלחה כל ימיו\" (דברים כב, כט), ולכן לא תיקנו לה חכמים כתובה, אבל מכל מקום כל התקנות שיש בתנאי הכתובה קיימות אף בה, ובכלל זה מזונות הבת. אף שאלה זו הריהי \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה שבתוך תנאי הכתובה הוא כותב לה שאם תתאלמן \u0003\"את תהא יתבא\u0004 \u0005[תהי יושבת]\u0006 \u0003בביתי\u0004 וניזונת מנכסיי כל ימי אלמנותיך \u0003\". תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: \"בביתי\" — ולא בביקתי\u0004 \u0005[בביקתתי,\u0006 בצריף קטן שלי\u0005],\u0006 שאם אין בבית מקום מתאים בשבילה — אין חובה על היורשים להחזיק אותה בבית. \u0003אבל\u0004 בכל מקרה \u0003מזוני אית\u0004 \u0005[מזונות\u0006 מן היורשים \u0005יש]\u0006 \u0003לה. מר בר רב אשי אמר: אפילו מזוני נמי לית\u0004 \u0005[מזונות גם כן אין]\u0006 \u0003לה,\u0004 שכן המזונות ניתנים לה רק כאשר היא יושבת בבית בעלה. ואם אינה יושבת בבית בעלה מכל טעם שהוא — אין לה מזונות. ומסכמים: \u0003ולית הלכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003כמר בר רב אשי,\u0004 אלא ניזונת מנכסיו.","\u0003אמר רב נחמן אמר שמואל:\u0004 אלמנה ש\u0003תבעוה להנשא ונתפייסה\u0004 (הסכימה לכך), אפילו עדיין לא נישאת — \u0003אין לה\u0004 עוד \u0003מזונות\u0004 מן היורשים. ומעירים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא נתפייסה,\u0004 אף שתבעוה להינשא, \u0003יש לה מזונות? אמר רב ענן: לדידי מפרשא לי מיניה\u0004 \u0005[לי נתפרש הדבר ממנו],\u0006 מ\u0003מר שמואל,\u0004 שיש להבדיל מן מקרים שונים: שאם \u0003אמרה\u0004 שאינה נישאת \u0003\"מחמת פלוני בעלי\"\u0004 שמת, שהיא עדיין קשורה בו — \u0003יש לה מזונות,\u0004 אבל אם אמרה שאינה נענית להצעה \u0003מחמת\u0004 שהתובעים אותה הם \u0003בני אדם שאינן מהוגנין לה\u0004 שהם התובעים אותה — \u0003אין לה מזונות,\u0004 שהרי מצד עצמה רצונה להינשא.","\u0003אמר רב חסדא:\u0004 אם \u0003זינתה — אין לה מזונות,\u0004 שאינה נקראת אשה היושבת בכבוד כאלמנה. \u0003אמר רב יוסף:\u0004 אם \u0003כיחלה\u0004 (צבעה את עיניה) \u0003ופירכסה\u0004 (צבעה את לחייה) — בכך היא מראה שרוצה למצוא חן בעיני אנשים ולהינשא, ולכך \u0003אין לה מזונות\u0004 מנכסי בעלה.","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי אם \u0003זינתה\u0004 הפסידה מזונותיה — \u0003כל שכן\u0004 אם \u0003כיחלה ופירכסה,\u0004 משום שמגלה בכך כוונתה שרוצה להינשא. אולם \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי אם \u0003כיחלה ופירכסה\u0004 אין לה מזונות, \u0003אבל\u0004 אם \u0003זינתה — אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 מזונות, \u0003מאי טעמא\u0004 \u0005[מה טעם] —\u0006 \u0003יצר אנסה,\u0004 שתקפה יצרה וזנתה, והרי זה כאילו עשתה באונס.","ומסכמים: \u0003ולית הלכתא\u0004 \u0005[ואין הלכה]\u0006 \u0003ככל הני שמעתתא\u0004 \u0005[השמועות הללו],\u0006 \u0003אלא כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב יהודה אמר שמואל: התובעת כתובתה בבית דין — אין לה מזונות\u0004 מנכסיו, שבזה שתובעת כתובתה מראה שרצונה לנתק את הקשר עם בעלה שמת.","ושואלים: \u0003ולא,\u0004 ואין לה?! \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מכרה\u0004 את \u0003כתובתה\u0004 או \u0003משכנה\u0004 את \u0003כתובתה\u0004 או \u0003עשתה\u0004 את \u0003כתובתה אפותיקי לאחר — אין לה מזונות.\u0004 ונדייק: \u0003הני\u0004 \u0005[אלה]\u0006 — \u0003אין\u0004 \u0005[כן],\u0006 כלומר, רק במקרים אלה היא מפסידה את מזונותיה, \u0003אבל תובעת\u0004 כתובה בלבד — \u0003לא!\u0004","ומשיבים: לא כך צריך לדייק אלא: \u0003הני\u0004 \u0005[אלה]\u0006 כשמכרה או משכנה, באם עושה אותם \u0003בין בבית דין, בין שלא בבית דין\u0004 — איבדה מזונותיה, אבל \u0003תובעת\u0004 כתובתה, אם תבעה \u0003בבית דין — אין\u0004 \u0005[כן],\u0006 \u0003שלא בבית דין — לא.\u0004","שנינו במשנה: \u0003וכך היו אנשי ירושלים\u0004 כותבים לאלמנה, שתתגורר בבית בעלה ותיזון מנכסיו כל ימי אלמנותה. וכן נהגו אנשי הגליל. ואילו אנשי יהודה היו כותבים, שתתגורר ותיזון מן הנכסים עד שיתנו לה היורשים את הכתובה. \u0003אתמר\u0004 \u0005[נאמר],\u0006 \u0003רב אמר: הלכה כאנשי יהודה, ושמואל אמר: הלכה כאנשי גליל\u0004 וכמנהג ירושלים.","ומעירים: \u0003בבל וכל פרוודהא\u0004 \u0005[העיירות\u0006 סביב לה\u0005]\u0006 \u0003נהוג\u0004 \u0005[נהגו]\u0006 \u0003כ\u0004שיטת \u0003רב, נהרדעא וכל פרוודהא\u0004 \u0005[העיירות\u0006 סביב לה\u0005]\u0006 \u0003נהוג\u0004 \u0005[נהגו]\u0006 \u0003כ\u0004שיטת \u0003שמואל.\u0004 מסופר: \u0003ההיא\u0004 \u0005[\u0006אשה \u0005אחת]\u0006 \u0003בת\u0004 העיר \u0003מחוזא דהות נסיבא\u0004 \u0005[שהיתה נשואה]\u0006 \u0003ל\u0004איש מ\u0003נהרדעא. אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב נחמן\u0004 לדון בענין כתובתה, \u0003שמעה לקלה\u0004 \u0005[שמע את קולה]\u0006 ש\u0003בת\u0004 העיר \u0003מחוזא היא,\u0004 שהיה המבטא במחוזא שונה ממקומות אחרים.","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003בבל וכל פרוודהא\u0004 \u0005[העיירות\u0006 סביב לה\u0005]\u0006 \u0003נהוג\u0004 \u0005[נוהגים]\u0006 \u0003כרב. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ל\u0004בן העיר \u0003נהרדעא נסיבא\u0004 \u0005[נישאה]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי הכי, נהרדעא וכל פרוודהא\u0004 \u0005[העיירות\u0006 סביב לה\u0005]\u0006 \u0003נהוג\u0004 \u0005[נוהגים]\u0006 \u0003כשמואל.\u0004 ושואלים: \u0003ועד היכא\u0004 \u0005[היכן]\u0006 גבולה של העיר \u0003נהרדעא — עד היכא דסגי קבא\u0004 \u0005[המקום שמהלך,\u0006 שנוהג, בו \u0005הקב,\u0006 המידה\u0005]\u0006 של \u0003נהרדעא.\u0004 שבאזור בו נהוגות המידות של נהרדעא הוא נחשב למקומה של נהרדעא גם לענין הלכה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו ב\u0003אלמנה, רב אמר:\u0004 כשנותנים לה כתובתה \u0003שמין מה שעליה.\u0004 כלומר, מעריכים בתוך חישוב דמי הכתובה גם את הבגדים שהיא לובשת, ומנכים את ערכם מסכום הכתובה. \u0003ושמואל אמר: אין שמין מה שעליה. אמר רב חייא בר אבין: וחילופה בלקיט,\u0004 שכיר הגר בבית בעל הבית, ובעל הבית קונה לו בגדים משלו, גם בכך נחלקו רב ושמואל האם כאשר הוא יוצא שמים לו את הבגדים הללו שנשארו בידו ומנכים ממשכורתו. אלא שבענין זה רב אמר שאין שמים, ושמואל אמר ששמים.","\u0003רב כהנא מתני\u0004 \u0005[היה שונה]:\u0006 \u0003וכן בלקיט,\u0004 זו שיטתם גם בלקיט, שלדעת רב שמים את הבגדים, ולשמואל אין שמים. \u0003ומנח בה סימנא\u0004 \u0005[והיה מניח,\u0006 נותן, \u0005בה סימן]\u0006 לשיטת רב: \u0003\"יתמא וארמלתא שלח ופוק\u0004 \u0005[יתום ואלמנה הפשט והוצא]\u0006\u0003\",\u0004 כלומר, לשיטתו גם את הלקיט (\"יתום\", שהרי הוא כרגיל איש עני) וגם את האלמנה, כאילו פושטים בגדיהם ומעריכים אותם.","\u0003אמר רב נחמן: אף על גב דתנן במתניתין כוותיה\u0004 \u0005[אף על פי ששנינו במשנה כשיטתו]\u0006 של \u0003שמואל,\u0004 מכל מקום \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אחד המקדיש נכסיו, ואחד המעריך את עצמו,\u0004 שנדב ערך עצמו להקדש, ונתחייבו לשלם כספים להקדש, \u0003אין לו\u0004 לגזבר המקדש זכות \u0003לא בכסות אשתו\u0004 של האיש הזה, \u0003ולא בכסות בניו, ולא\u0004 בבגדים חדשים שנצבעו \u0003בצבע שצבע לשמן\u0004 (עבורם), ואפילו כשעדיין לא לבשום, \u0003ולא בסנדלים חדשים שלקח לשמן.\u0004 שמכאן נראה כדברי שמואל, שבגדי האשה אינם נחשבים כחלק מרכושו של הבעל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: וכי מאחר דתנן מתניתין כוותיה\u0004 \u0005[ששנויה משנתנו כשיטתו]\u0006 של \u0003שמואל, אמאי הלכתא כוותיה\u0004 \u0005[מדוע\u0006 אם כן \u0005הלכה כשיטתו]\u0006 של \u0003רב? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לכאורה כ\u0004דעת \u0003שמואל רהיטא\u0004 \u0005[\u0006היא \u0005רצה],\u0006 כלומר, כשאתה קורא את המשנה במהירות באופן שטחי, כך נראית משמעות הדברים, אולם \u0003כי מעיינת\u0004 \u0005[כאשר אתה מעיין]\u0006 \u0003בה,\u0004 אתה רואה ש\u0003הלכתא כוותיה\u0004 \u0005[\u0006ש\u0005הלכה כשיטתו]\u0006 של \u0003רב.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]?\u0006 \u0003כי אקני\u0004 \u0005[כאשר הקנה]\u0006 \u0003לה\u0004 את הבגדים הללו, היה זה \u0003אדעתא למיקם קמיה\u0004 \u0005[על דעת שתעמוד לפניו]\u0006 כשהיא לבושה בהם, כשהיא איתו. ואולם \u0003אדעתא למשקל ולמיפק\u0004 \u0005[על דעת לקחת ולצאת]\u0006 ממנו \u0003לא אקני\u0004 \u0005[הקנה]\u0006 \u0003לה.\u0004 וטעם המשנה הוא איפוא שהבעל נותן לאשתו את הבגדים שקונה לה — אבל רק בהיותה עמו. ולכן מאותו טעם שאין לגזבר זכות בהם, שהרי הבעל נתנם לה, מאותו הטעם גם לה אין זכות בהם כשהיא יוצאת ממנו. ואם כן שיטת המשנה לא רק שאינה נוגדת את דברי רב אלא אפילו מסייעת להם.","מסופר: \u0003כלתא דבי בר\u0004 \u0005[הכלה של בית בן]\u0006 \u0003אלישיב הוה קא תבעה\u0004 \u0005[היתה תובעת]\u0006 \u0003כתובתה מיתמי\u0004 \u0005[מן היתומים].\u0006 \u0003הוה קא ממטי להו לבי דינא\u0004 \u0005[\u0006ו\u0005היתה מביא אותם לבית הדין],\u0006 \u0003אמרי\u0004 \u0005[אמרו]\u0006 היתומים: \u0003זילא לן מילתא דתיזלי הכי\u0004 \u0005[מזולזל לנו הדבר שתלכי כך]\u0006 בלבושי בית, אלא לבשי בגדים יפים. \u0003אזלא לבישתינהו ואיכסתינהו לכוליה מנא\u0004 \u0005[הלכה לבשה והתכסתה בכל בגדיה].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבינא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב\u0004 ש\u0003אמר: אלמנה שמין מה שעליה\u0004 ואם כן אף כל מה שלבשה יש להביא בחשבון הכתובה המגיעה לה.","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם],\u0006 לבני ביתו בצוואתו: תנו \u0003נדוניא לברת\u0004 \u0005[לבתי]\u0006 והיה מנהג מקובל בשיעור נדוניה כזו, במספר הבגדים והתכשיטים. ובינתיים \u0003זל\u0004 \u0005[הוזלה]\u0006 ה\u0003נדוניא,\u0004 ואפשר היה לקנות את כל הדברים הרגילים בפחות כסף, והתעוררה השאלה לגבי ההפרש בין הסכום שהתכוון לתת לה בזמן הצוואה והסכום שהוציאו בפועל. \u0003אמר רב אידי בר אבין: פורנא ליתמי\u0004 \u0005[הרווח,\u0006 ההפרש, הוא \u0005ליתומים]\u0006 ולא לבת.","וכן מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לבני ביתו בצוואתו:"],["\u0003\"ארבע מאה זוזי מן חמרא לברת\u0004 \u0005[ארבע מאות זוז מהיין\u0006 הזה תנו \u0005לבת]\u0006 \u0003\",\u0004 ובינתיים \u0003אייקר חמרא\u0004 \u0005[התייקר היין]\u0006 ונשאר עודף. \u0003אמר רב יוסף: רווחא ליתמי\u0004 \u0005[הרווח\u0006 הוא \u0005ליתומים],\u0006 והם מקבלים את הסכום העודף.","מסופר: \u0003קריביה\u0004 \u0005[קרוביו]\u0006 של \u0003ר' יוחנן הוה להו איתת אבא דהוה קמפסדה מזוני\u0004 \u0005[היתה להם אשת אב שהיתה מפסידה מזונות],\u0006 שהיתה נוהגת בבזבזנות. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יוחנן\u0004 לבקש עצה. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003איזילו ואמרו ליה לאבוכון דנייחד\u0004 \u0005[לכו ואמרו לאביכם, שייחד]\u0006 \u0003לה ארעא\u0004 \u0005[קרקע]\u0006 מסויימת \u0003למזונה,\u0004 וכיון שתסכים לקבל קרקע זו למזונותיה הריהי בכך מוחלת על היתר. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ריש לקיש\u0004 לדון, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כל שכן שריבה לה מזונות.\u0004 כלומר, את מזונותיה הוא ודאי צריך לשלם, ומה שעשה היה ששיעבד לה עוד קרקע מסויימת לצורך זה שאם תזדקק יוסיפו לה מקרקע זו. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוחנן לא אמר הכי\u0004 \u0005[כך]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו הבו\u0004 \u0005[לכו ותנו]\u0006 \u0003לה\u0004 כל צורכה. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא — מפיקנא לכו\u0004 \u0005[אוציא לכם]\u0006 את \u0003ר' יוחנן מאונייכו\u0004 \u0005[מאוזניכם],\u0006 כלומר, אנהג כנגדכם בתוקף, עד שתשכחו את דברי ר' יוחנן. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יוחנן\u0004 להתלונן. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מה אעשה? שכנגדי,\u0004 כלומר, אדם חשוב כמוני, \u0003חלוק עלי\u0004 ואיני יכול לסתור את דבריו. \u0003אמר ר' אבהו: לדידי מפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו],\u0006 מ\u0003ר' יוחנן\u0004 עצמו שיש הבדל באיזו לשון ייחד לה את הקרקע. אם \u0003אמר\u0004 שהוא נותן לה דבר מסויים וקצב לה בלשון \u0003\"למזונות\"\u0004 — כוונתו ש\u0003ריבה לה מזונות,\u0004 כלומר, שנותן לה מזונותיה, אלא שאם לא יספיקו המזונות, גם היקצה בנוסף לכך שטח מסויים שהוא רק לצורך זה. אבל אם \u0003אמר\u0004 לה שמייחד לה דבר זה \u0003\"במזונות\"\u0004 — הרי \u0003קצץ לה מזונות,\u0004 כלומר, קבע גבול שלא תיקח יותר ממה שקבע לה.","","","","\u0003אף על פי שאמרו\u0004 שבכלל \u0003בתולה גובה\u0004 לכתובתה \u0003מאתים\u0004 זוז \u0003ואלמנה\u0004 — \u0003מנה\u0004 (מאה זוז), \u0003אם רצה להוסיף\u0004 לכתובתה \u0003אפילו מאה מנה — יוסיף.\u0004 ואם \u0003נתארמלה\u0004 (נתאלמנה) \u0003או נתגרשה, בין מן הארוסין בין מן הנשואין — גובה את הכל\u0004 שכתב לה. \u0003ר' אלעזר בן עזריה אומר:\u0004 אם נתאלמנה \u0003מן הנשואין — גובה את הכל. מן האירוסין — בתולה גובה מאתים ואלמנה מנה\u0004 בלבד, מפני \u0003שלא כתב לה\u0004 תוספת על הכתובה \u0003אלא על מנת לכונסה.\u0004 \u0003ר' יהודה אומר\u0004 דין אחר בכתובה. \u0003אם רצה כותב לבתולה\u0004 כראוי לה \u0003שטר של מאתים, והיא כותבת \"התקבלתי ממך מנה\",\u0004 שמוותרת על חצי מהכתובה, \u0003ו\u0004כן \u0003לאלמנה\u0004 כותב \u0003מנה והיא כותבת \"התקבלתי ממך חמשים זוז\".\u0004 ואילו \u0003ר' מאיר אומר:\u0004 אסור לעשות כן, והטעם: ש\u0003כל הפוחת לבתולה ממאתים ולאלמנה ממנה — הרי זו בעילת זנות,\u0004 שבפחות מזה אין לה דין כתובה, וכאילו לא כתב לה כלל.","","שנינו במשנה שאם רצה להוסיף מוסיף, ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 אם רצה, מדוע לא יוסיף? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003קיצותא עבדו רבנן\u0004 \u0005[קיצבה עשו חכמים]\u0006 בסכום הכתובה כדי \u0003שלא לבייש את מי שאין לו,\u0004 ולכן אין להוסיף על הסכום, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא הקפידו חכמים על כך, ואם רוצה להוסיף — יוסיף.","שנינו במשנה ש\u0003אם רצה להוסיף\u0004 על סכום הכתובה — אפילו מאה מנה יוסיף. ומעירים: \u0003\"רצה לכתוב לה\" לא קתני\u0004 \u0005[שנה],\u0006 שמלשון זו משמע שפרט לכתובה עצמה הוא כותב לה סכום אחר שאינו נחשב ככתובה עצמה, \u0003אלא\u0004 לשון \u0003\"רצה להוסיף\"\u0004 שנינו, שמלשון זו משמע שהסכום שכתב נחשב כחלק מהכתובה. והרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' איבו אמר ר' ינאי.\u0004 ש\u0003אמר ר' איבו אמר ר' ינאי: תנאי כתובה\u0004 וכן סכומים אחרים שהוסיף מדעתו לכתובה \u0003ככתובה\u0004 עצמה \u0003דמי\u0004 \u0005[\u0006הם \u0005נחשבים].\u0006","ו\u0003נפקא מינה\u0004 \u0005[\u0006ו\u0005יוצא מזה]\u0006 פסק להלכה בכמה וכמה עניינים: \u0003למוכרת\u0004 את כתובתה, שהמכירה כוללת גם את התוספת; \u0003ולמוחלת\u0004 כתובתה לבעלה או ליורשים, שאף את התוספת כללה במחילה זו; \u0003ל\u0004ענין \u0003מורדת\u0004 על בעלה, שמנכים לה מכתובתה סכום קצוב בכל שבוע וממשיכים לעשות כן עד שתכלה כל הכתובה, ולמדנו שפוחתים אף מתוספת הכתובה;","\u0003ולפוגמת\u0004 כתובתה, שהמודה שקיבלה מקצת מכתובתה (ואפילו דינר אחד) אינה נפרעת את השאר אלא בשבועה, ולענין זה אף אם מודה שקיבלה מקצת התוספת צריכה להישבע על השאר; ו\u0003לתובעת\u0004 כתובתה, שאמרו חכמים שמשעת תביעה מאבדת זכותה למזונות, והוא הדין אם תובעת תוספת כתובתה; \u0003ול\u0004ענין \u0003עוברת על דת,\u0004 שקנסוה שתצא מבעלה בלא כתובה, שמאבדת לא רק את עיקר כתובה אלא גם את התוספת;"],["\u0003ל\u0004ענין ה\u0003שבח,\u0004 שאם במות הבעל לא היה כדי תשלום כל הכתובה, אף על פי שאחר כך השביחו היתומים את הנכסים — אין האלמנה גובה מן השבח לא את עיקר ולא את תוספת הכתובה; וכן \u0003לשבועה,\u0004 שאם הוזקקה להישבע כדי שתוכל ליטול כתובתה — תוספת הכתובה הריהי בכלל שבועה זו; \u0003ולשביעית,\u0004 שאין שטר הכתובה נשמט בשביעית כשאר חובות, וכן לא התוספת;","\u0003ולכותב כל נכסיו לבניו\u0004 והניח לאשתו קרקע כלשהי לכתובתה, שנוטלת רק מאותה קרקע, בין עיקר ובין תוספת כתובה; וכן דין התוספת כעיקר כתובה \u0003לגבות\u0004 שתיהן \u0003מן הקרקע\u0004 דווקא \u0003ומן הזיבורית\u0004 דווקא, \u0003ו\u0004מאבדת האלמנה את הכתובה ואת התוספת \u0003כל זמן שהיא\u0004 שהיא אינה גרה בבית בעלה לאחר מותו אלא \u0003בבית אביה\u0004 יותר מעשרים וחמש שנים לאחר מות בעלה; \u0003ו\u0004כן \u0003לכתובת בנין דכרין\u0004 \u0005[בנים זכרים],\u0006 שיורשים את כתובת אימם כשמת הבעל בנוסף לירושה שיורשים עם שאר האחים, וכן הוא גם לענין התוספת.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בנושא \u0003כתובת בנין דכרין.\u0004 חכמי \u0003פומבדיתא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא טרפא ממשעבדי\u0004 \u0005[אינה טורפת מ\u0006נכסים \u0005משועבדים],\u0006 שאם מכר הבעל נכסים, אין הבנים יכולים לגבות ירושת כתובתה מנכסים אלה. ומדוע — \u0003\"ירתון\" תנן\u0004 \u0005[\"יירשו\" שנינו],\u0006 שבנוסח זה נאמר, שבנים זכרים \"ירתון כתובת אמהון\", וכיון שדינם כירושה, אין ירושה אלא מנכסים הנמצאים ברשות האב במותו, ולא מנכסים שמכר.","ואילו \u0003בני מתא מחסיא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003טרפא ממשעבדי\u0004 \u0005[טורפת מ\u0006נכסים \u0005משועבדים],\u0006 כלומר, בניה גובים כתובת אימם גם מנכסים שמכר האב, כי \u0003\"יסבון\" תנן\u0004 \u0005[\"יקחו\" שנינו],\u0006 (\"יסבון כתובת אמהון\"), שבשטר הכתובה הקנה לבני האשה את כתובתה כמכר, ונמצא ששטרם קודם לשאר הלקוחות וטורפים מהם. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא: \u0003לא טרפא ממשעבדי\u0004 \u0005[אינה טורפת מ\u0006נכסים \u0005משועבדים],\u0006 כי \u0003\"ירתון\" תנן\u0004 \u0005[\"יירשו\" שנינו].\u0006","מחלוקת נוספת נאמרה בין חכמי פומבדיתא לבני מתא מחסיא, אם ייחד לשם תשלום כתובתה \u0003מטלטלי\u0004 \u0005[מטלטלים]\u0006 \u0003ואיתנהו בעינייהו\u0004 \u0005[ו\u0006הם \u0005מצויים בעינם,\u0006 כמות שהם\u0005]\u0006 — ודאי נוטלת האשה מהם \u0003בלא שבועה,\u0004 שאינה צריכה להישבע ליתומים שלא השאיר לה בעלה כסף אחר לתשלום הכתובה, שכן מסתבר שמטלטלים אלה שייחד לה הם מה שהניח לצורך זה,","ואם \u0003ליתנהו בעינייהו\u0004 \u0005[אינם בעינם],\u0006 כגון שאבדו — חכמי \u0003פומבדיתא אמרי\u0004 \u0005[אומרים]:\u0006 נוטלת כתובתה מנכסים אחרים (שהרי כל נכסיו של הבעל משועבדים לכתובה) \u0003בלא שבועה.\u0004 ואילו \u0003בני מתא מחסיא אמרי\u0004 \u0005[אומרים]:\u0006 אינה נוטלת מנכסים אחרים אלא \u0003בשבועה. והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 נוטלת מנכסים אחרים אף \u0003בלא שבועה.\u0004","עוד נחלקו: אם \u0003ייחד לה ארעא\u0004 \u0005[קרקע]\u0006 שתיגבה ממנה כתובתה וסימן אותה \u0003בארבעה מצרנהא\u0004 \u0005[מצריה,\u0006 גבולותיה\u0005]\u0006 — הרי היא נוטלת אותה \u0003בלא שבועה.\u0004 אם ייחד אותה רק \u0003בחד מצרא\u0004 \u0005[בגבול אחד],\u0006 שאין זה סימון מובהק לגמרי — חכמי \u0003פומבדיתא אמרי\u0004 \u0005[אומרים]:\u0006 נוטלת אותה קרקע \u0003בלא שבועה.\u0004 ואילו \u0003בני מתא מחסיא אמרי\u0004 \u0005[אומרים]:\u0006 אינה נוטלתה אלא \u0003בשבועה. והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 נוטלת אותה אף \u0003בלא שבועה.\u0004","וכיוצא בזה נחלקו: אם \u0003אמר לעדים \"כתבו וחתמו\u0004 שטר מתנה \u0003והבו ליה\u0004 \u0005[ותנו לו]\u0006 \u0003\",\u0004 לאדם מסויים — אם \u0003קנו מיניה\u0004 \u0005[ממנו],\u0006 כלומר, עשו מעשה קנין באותה שעה — \u0003לא צריך אימלוכי ביה\u0004 \u0005[להימלך בו],\u0006 בנותן המתנה, בשנית, ונותנים למקבל, שלאחר קנין אי אפשר כבר לחזור. ואם \u0003לא קנו מיניה\u0004 \u0005[ממנו]\u0006 — חכמי \u0003פומבדיתא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא צריך אימלוכי ביה\u0004 \u0005[להימלך בו]\u0006 עוד, ואילו \u0003בני מתא מחסיא אמרי\u0004 \u0005[אמרו]:\u0006 \u0003צריך אימלוכי ביה\u0004 \u0005[להימלך בו].\u0006 \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003צריך אימלוכי ביה\u0004 \u0005[להימלך בו]\u0006 שנית.","שנינו במשנה כי \u0003ר' אלעזר בן עזריה\u0004 אומר שהמקבלת כתובתה מן הנישואין גובה את הכל עם התוספת, ומן האירוסין גובה רק את עיקר כתובה בלא תוספת. \u0003איתמר\u0004 \u0005[נאמר]\u0006 ש\u0003רב ור' נתן\u0004 נחלקו בכך, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: הלכה כר' אלעזר בן עזריה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין הלכה כר' אלעזר בן עזריה.\u0004","ומוסיפים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' נתן הוא\u0004 ש\u0003אמר\u0004 כי \u0003הלכה כר' אלעזר בן עזריה.\u0004 ומדוע — \u0003דשמעינן ליה\u0004 \u0005[ששמענו אותו]\u0006 את \u0003ר' נתן דאזיל בתר אומדנא\u0004 \u0005[ש\u0006הוא \u0005הולך אחר אומד,\u0006 השערה\u0005],\u0006 שגם במקום שלא פירש אדם דברים בצורה ברורה, הולכים אנחנו על פי מה שאנו מעריכים שהיתה כוונתו, ופוסקים הלכה לפי זה. והיכן שמענו אותו — ש\u0003אמר ר' נתן: הלכה כר' שמעון שזורי במסוכן.\u0004 שמי שהיה חולה מסוכן, ואמר \"כתבו גט לאשתי\", אנחנו מניחים שהתכוון לומר \"כתבו ותנו לה\", שרצה לפוטרה בגט כדי שלא תזדקק לייבום, ואף שלא פירש את הדברים, אומדים אנו שבמצבו המסויים אכן התכוון לכך, והולכים אחר כוונתו."],["\u0003ו\u0004כן הלכה כמותו \u0003בתרומת מעשר של דמאי\u0004 שהפריש אדם כתקנת חכמים מפירות שקנה מעם הארץ, שיש חשש שלא הפריש מעשרות, ותרומת מעשר זו התערבה בתוך יתר הפירות. שאם ידונו בה כדין תרומה ממש לא תהא תקנה לתערובת אלא למוכרה בזול לכהנים, שרק הם רשאים לאכול ממנה. שלדעת ר' שמעון שזורי יכול לשאול את מוכר הפירות, אף על פי שהוא עם הארץ, אם הפריש מעשרותיו כראוי, ואם אמר שהפריש — רשאי לסמוך עליו. שלא גזרו חכמים שאין סומכים על עם הארץ במקום שיש בו הפסד כגון זה.","ושואלים: \u0003ו\u0004כי \u0003רב לא אזיל\u0004 \u0005[הולך]\u0006 \u0003בתר אומדנא\u0004 \u0005[אחר אומדן]?\u0006 \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו בשאלה של \u0003מתנת שכיב מרע\u0004 (גוסס), \u0003ש\u0004היה \u0003כתוב בה\u0004 גם שעשו על כך \u0003קנין. בבי\u0004 \u0005[בבית]\u0006 \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003ארכביה אתרי רכשי\u0004 \u0005[הרכיב אותו על שני סוסים],\u0006 כלומר, עשה במתנה זו שני סוגים של חיזוק. \u0003ושמואל אמר: לא ידענא מאי אידון\u0004 \u0005[אין אני יודע מה לדון]\u0006 \u0003בה,\u0004 בצוואה כזו.","ומסבירים: \u0003בבי\u0004 \u0005[בבית]\u0006 \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003ארכביה אתרי רכשי\u0004 \u0005[הרכיב אותו על שני סוסים],\u0006 ולאיזה ענין: \u0003הרי היא\u0004 לצד מסויים \u0003כמתנת בריא,\u0004 כיון שעשה קנין כבריא, \u0003והרי היא כמתנת שכיב מרע,\u0004 שכן נתן אותה סמוך למיתתו.","ושניהם לחיזוק; \u0003הרי היא כמתנת בריא,\u0004 ש\u0003אם עמד\u0004 והבריא — \u0003אינו יכול לחזור בו,\u0004 ככל מתנה שנותן בריא, שהרי עשה על כך קנין. ו\u0003הרי היא כמתנת שכיב מרע, שאם אמר \"הלואתי\u0004 שהלויתי לפלוני, הריהי נתונה \u0003לפלוני\u0004 במתנה \u0003\"\u0004— הרי \u0003הלואתו לפלוני.\u0004 אף שכרגיל אין הלוואה עוברת מאדם אחד לחבירו בלא מעשה של העברת השטרות, ואולם כיון שהיא מתנת שכיב מרע — מועילה גם מתנה זו.","\u0003ושמואל אמר: לא ידענא מאי אידון\u0004 \u0005[אינני יודע מה אדון]\u0006 \u0003בה,\u0004 בצוואה כזו. ומהו החשש — \u0003שמא לא גמר להקנותו,\u0004 למתנה זו, \u0003אלא בשטר\u0004 שכתב לו, שהרי עשה בו קנין, \u0003ו\u0004כיון שנתכוון להקנאה בשטר לאחר מותו, הרי \u0003אין שטר לאחר מיתה.\u0004"],["\u0003אלא,\u0004 כך יש לומר: \u0003תרוייהו\u0004 \u0005[שניהם],\u0006 רב ור' נתן, \u0003אזלי בתר אומדנא\u0004 \u0005[הולכים אחר אומדן],\u0006 אלא שיש להסביר את מחלוקתם בדרך אחרת.","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003הלכה\u0004 כר' אלעזר בן עזריה — \u0003שפיר\u0004 \u0005[יפה],\u0006 שהרי גם כאן יש ענין של אומדנא, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי \u0003אין הלכה\u0004 כר' אלעזר בן עזריה — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003אומדן דעתא\u0004 \u0005[דעת]\u0006 \u0003הוא,\u0004 אבל באופן אחר. כי מדוע נתן לה את התוספת הזו — \u0003משום איקרובי דעתא\u0004 \u0005[קירוב\u0006 ה\u0005דעת]\u0006 \u0003הוא,\u0004 וכיון שנוצר ביניהם קשר וקירבה, שהתארסו, \u0003והא איקרבא ליה דעתא\u0004 \u0005[והרי התקרבה דעתו]\u0006 לאשה זו, ולכן גמר בליבו לתת לה את התוספת בכל מקרה.","מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב חנינא\u0004 בעל המקרא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' ינאי וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003הלכה כר' אלעזר בן עזריה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוק, קרי קראך לברא\u0004 \u0005[צא, קרא\u0006 את \u0005מקראך בחוץ]!\u0006 שאתה בקי במקרא ולא בהלכה, ומה שאמרת אינו ראוי להיאמר בבית המדרש, כי \u0003אין הלכה כר' אלעזר בן עזריה.\u0004","\u0003אמר רב יצחק בר אבדימי משום רבינו\u0004 (בשם רבי יהודה הנשיא): \u0003הלכה כר' אלעזר בן עזריה. אמר רב נחמן אמר שמואל: הלכה כר' אלעזר בן עזריה.\u0004","\u0003ורב נחמן דידיה\u0004 \u0005[משלו],\u0006 ולא בשם שמואל, \u0003אמר: אין הלכה כר' אלעזר בן עזריה. ונהרדעי משמיה\u0004 \u0005[ו\u0006חכמי \u0005נהרדעא משמו]\u0006 של \u0003רב נחמן אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הלכה כר' אלעזר בן עזריה.\u0004 ואומרים: \u0003ואף על גב דלט\u0004 \u0005[ואף על פי שקילל]\u0006 \u0003רב נחמן ואמר: כל דיינא דדאין\u0004 \u0005[דיין שדן]\u0006 \u0003כר' אלעזר בן עזריה — הכי והכי תיהוי\u0004 \u0005[כך וכך תהיה\u0006 לו\u0005],\u0006 שלא רצה לפרש פרטי הקללה, \u0003אפילו הכי\u0004 \u0005[כך] —\u0006 \u0003הלכה כר' אלעזר בן עזריה.\u0004 מכיון שהיו חילוקי דעות ושינויי דעות מרובים, ומסכמים: \u0003והלכה למעשה — כר' אלעזר בן עזריה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבין\u0004 שאלה זו: אשה ש\u0003נכנסה לחופה ולא נבעלה, מהו\u0004 דינה לענין תוספת? האם אנחנו אומרים ש\u0003חיבת חופה קונה\u0004 לה את התוספת ומשעה זו היא כאשה נשואה, \u0003או\u0004 שמא \u0003חיבת ביאה\u0004 בלבד \u0003קונה.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב יוסף\u0004 ברייתא זו: \u0003שלא כתב לה\u0004 תוספת \u0003אלא על חיבת לילה הראשון. אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ומפרש ש\u0003חיבת חופה קונה — היינו דאמר\u0004 \u0005[זהו שאמר]\u0006 \u0003לילה הראשון,\u0004 שהרי היא נעשית בלילה הראשון בלבד, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שדווקא \u0003חיבת ביאה קונה,\u0004 וכי \u0003ביאה בלילה הראשון איתא\u0004 \u0005[ישנה],\u0006 \u0003מכאן,\u0004 מהלילה הראשון, \u0003ואילך, ליתא\u0004 \u0005[אינה]?!\u0006 משמע לכאורה שדי בחיבת החופה, ומאז נקנית התוספת.","ודוחים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 אתה מפרש שחיבת לילה ראשון כוונתה \u0003חופה,\u0004 וכי \u0003חופה בלילה איתא\u0004 \u0005[ישנה],\u0006 ואילו \u0003ביממא ליתא\u0004 \u0005[ביום אינה]?\u0006 ותוהים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 אם אתה מקשה בדרך זו — וכי \u0003ביאה בלילה איתא\u0004 \u0005[יש]\u0006 \u0003ביממא ליתא\u0004 \u0005[ביום אין]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רבא\u0004 שלמרות שאמרו חכמים שאסור לבוא על אשה ביום, \u0003אם היה בבית אפל — מותר!\u0004 ודוחים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 \u0003אורח ארעא קא משמע לן\u0004 \u0005[דרך ארץ השמיע לנו]\u0006 דרך אגב ש\u0003ביאה\u0004 סתם מנהגה ודרכה \u0003בלילה.\u0004","ואומרים: \u0003אלא\u0004 מכל מקום ענין \u0003חופה קשיא\u0004 \u0005[קשה]\u0006 מדוע מייחסים אותה דווקא ללילה? ומשיבים: \u0003חופה נמי לא קשיא\u0004 \u0005[גם כן איננו קשה],\u0006 \u0003כיון\u0004 ש\u0003סתם חופה לביאה קיימא\u0004 \u0005[\u0006היא \u0005עומדת],\u0006 \u0003אורח ארעא קא משמע לן\u0004 \u0005[דרך ארץ השמיע לנו]\u0006 ש\u0003בלילה\u0004 צריך לעשות אותה. ומכל מקום אין מכאן הוכחה לצד זה או אחר.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 בהמשך לשאלת רבין: אם \u0003נכנסה\u0004 הכלה \u0003לחופה ופירסה נידה\u0004 ולא יכל לבוא עליה ומת מיד לאחר מכן, \u0003מהו\u0004 הדין לענין תוספת כתובה? \u0003אם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ותחליט בבעיה הקודמת ש\u0003חיבת חופה קונה,\u0004 האם הכוונה היא דווקא ל\u0003חופה דחזיא\u0004 \u0005[שראויה]\u0006 \u0003לביאה\u0004 שיש בה יותר קירוב דעת, \u0003אבל חופה דלא חזיא\u0004 \u0005[שאינה ראויה]\u0006 \u0003לביאה,\u0004 וכגון זו שפירסה מיד נידה — \u0003לא, או דלמא לא שנא\u0004 \u0005[שמא אין הבדל]?\u0006 לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה ש\u0003ר' יהודה אומר:\u0004 אם \u0003רצה, כותב לבתולה\u0004 בכתובתה מאתים זוז והיא כותבת לו שובר על חלק מהסכום. ושואלים: \u0003ו\u0004האמנם \u0003סבר ר' יהודה\u0004 ש\u0003כותבין שובר\u0004 (קבלה)? כי היו חכמים שאמרו שאין לכתוב שובר, שייתכן שהלווה יאבד את השובר, וכיון שגוף השטר קיים יבוא המלוה לגבות שנית בשטרו. \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003מי שפרע מקצת חובו\u0004 — \u0003ר' יהודה אומר: יחליף.\u0004 כלומר, יתן לו שטר חוב אחר שבו כתוב הסכום המגיע ממנו עתה. ו\u0003ר' יוסי אומר: יכתוב לו שובר\u0004 על הכסף שקיבל. משמע שר' יהודה סבור שאין כותבים שובר!","\u0003אמר ר' ירמיה: כששוברתה מתוכה,\u0004 כלומר, שכותבת את השובר על הכתובה עצמה, ואין הבעל צריך לשמור עוד את השובר ולכך מסכים גם ר' יהודה.","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003בשאין שוברתה מתוכה; בשלמא התם\u0004 \u0005[נניח שם]\u0006 במקרה של שטר חוב, הרי \u0003ודאי פרעיה\u0004 \u0005[פרע לו\u0006 הלווה חלק\u0005]\u0006 מן החוב, ויש לחשוש \u0003דלמא מירכס תברתא, ומפיק ליה לשטרא, והדר גבי זימנא אחרינא\u0004 \u0005[שמא יאבד\u0006 הלווה את \u0005השובר, ויוציא\u0006 המלווה \u0005את השטר, ויחזור\u0006 ו\u0005יגבה פעם אחרת]\u0006 את מלוא החוב, ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 במשנה, וכי \u0003ודאי יהב\u0004 \u0005[נתן]\u0006 \u0003לה\u0004 הבעל חלק מהכתובה? הלא \u0003מילתא בעלמא היא\u0004 \u0005[דבר בלבד הוא]\u0006 ש\u0003אמרה ליה\u0004 \u0005[לו],\u0006 שהיה כאן רק ויתור ומחילה, שמחלה לו על חלק מכתובתה, \u0003אי נטריה\u0004 \u0005[אם שמר]\u0006 על שטר המחילה — \u0003נטריה\u0004 \u0005[שמר אותו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא נטריה\u0004 \u0005[שמר אותו]\u0006 ואבד — \u0003איהו הוא דאפסיד אנפשיה\u0004 \u0005[הוא שהפסיד לעצמו]\u0006 ואין אנו צריכים לדאוג לכך, ולפיכך במקרה כזה מודה ר' יהודה שכותבים שובר.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003אביי לא אמר כר' ירמיה\u0004 וטעמו פשוט, שכן \u0003לא קתני\u0004 \u0005[שנה\u0006 שם\u0005]\u0006 \u0003שוברתה מתוכה. אלא ר' ירמיה מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כאביי?\u0004 ומשיבים: אף על פי שיש כאן טעם מיוחד שאין לחשוש לאיבוד השובר, בכל זאת \u0003גזירה שובר דהכא\u0004 \u0005[שכאן]\u0006 \u0003אטו\u0004 \u0005[בגלל]\u0006 \u0003שובר דעלמא\u0004 \u0005[בכלל],\u0006 ולא היה ר' יהודה מסכים לכתיבת שובר אלא כשהשובר נכתב בגוף הכתובה.","לגוף הענין מעירים: \u0003טעמא\u0004 \u0005[הטעם],\u0006 דווקא — ש\u0003כתבה ליה\u0004 \u0005[לו]\u0006 שובר, \u0003אבל\u0004 אם אמרה לו \u0003על פה\u0004 שהיא מוותרת — \u0003לא,\u0004 אין זה מועיל גם לר' יהודה. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הלא \u0003דבר שבממון הוא, ושמעינן ליה\u0004 \u0005[ושמענו אותו]\u0006 את \u0003ר' יהודה\u0004 ש\u0003אמר:\u0004 בכל \u0003דבר שבממון\u0004 שמתנה עם אדם אחר — \u0003תנאו קיים.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לאשה \"הרי את מקודשת לי על מנת שאין ליך\u0004 (לך) \u0003עלי,\u0004 כלומר, שאין אני מתחייב לך לא \u0003שאר,\u0004 לא \u0003כסות ו\u0004לא \u0003עונה\" — הרי זו מקודשת, ותנאו בטל,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: בדבר שבממון,\u0004 כגון בענין שאר וכסות — \u0003תנאו קיים!\u0004 ואם כן כאשר מוותרת על חלק מכתובתה הרי זה כתנאי שבממון ודי שיהיה בעל פה, ומדוע צריכה לכתוב זאת?!","ומשיבים: אף על פי שבכלל יכול התנאי להיות אף בעל פה, אבל \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה\u0004 כי \u0003כתובה דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ו\u0004אולם \u0003חכמים עשו חיזוק לדבריהם יותר משל תורה.\u0004 שהתחייבות מן התורה אין צורך לחזק אותה ורשאי להתנות לבטלה, אבל כאן, כיון שהכתובה היא מדברי סופרים, עשו חכמים חיזוק לתקנתם, ואם לא תכתוב את הדברים הללו במפורש, לא יתקיים התנאי.","ומקשים: \u0003הרי\u0004 זכות הבעל ב\u0003פירות\u0004 נכסי האשה שהיא רק תקנה מ\u0003דרבנן\u0004 \u0005[\u0006מ\u0005דברי סופרים],\u0006 \u0003ולא עבדו להו רבנן\u0004 \u0005[עשו להם חכמים]\u0006 \u0003חיזוק, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר:\u0004 גם אם כתב הבעל שהוא מוותר על פירות נכסי האשה, \u0003לעולם הוא אוכל פירי פירות\u0004 של נכסי מלוג של האשה, שאמנם מוכרים את הפירות ומצרפים את דמיהם לנכסי האשה, אבל פירות שעשו פירות אלה — של הבעל הם, \u0003עד שיכתוב לה\u0004 במפורש: \u0003\"דין ודברים אין לי בנכסיך, ובפירותיהן, ובפירות פירותיהן עד עולם\".\u0004"],["\u0003וקיימא לן\u0004 \u0005[ומוחזק לנו,\u0006 בידינו\u0005]\u0006 בענין זה כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כותב\"\u0004 שם — לאו דווקא כותב בשטר, אלא אפילו \u0003אומר\u0004 בעל פה. נמצא שיכול לבטל תקנת חכמים של אכילת פירות, אפילו שאין זה אלא דבר שבממון, ואפילו בתנאי שבעל פה בלבד!","\u0003אמר אביי,\u0004 יש לחלק: \u0003לכל\u0004 (לכל אשה) \u0003יש כתובה, ולא לכל יש פירות,\u0004 שלא לכל אשה יש נכסי מלוג שהבעל אוכל פירותיהם. ולכן, \u0003מילתא דשכיחא\u0004 \u0005[דבר ש\u0006הוא \u0005שכיח]\u0006 כמו כתובה — \u0003עבדו בה רבנן\u0004 \u0005[עשו בו חכמים]\u0006 \u0003חיזוק\u0004 ועמדו על כך שאת תקנת הסכום הקצוב לכתובה אי אפשר לבטל אלא על ידי שטר, אבל \u0003מילתא דלא שכיחא\u0004 \u0005[דבר שאינו שכיח],\u0006 כמו פירות — \u0003לא עבדו בה רבנן\u0004 \u0005[עשו בו חכמים]\u0006 \u0003חיזוק,\u0004 ואפשר להתנות בו תנאי בעל פה.","ומקשים: \u0003הרי\u0004 דין \u0003חמרים, דשכיחי\u0004 \u0005[ש\u0006הוא \u0005מצוי],\u0006 \u0003ולא עבדו\u0004 \u0005[עשו]\u0006 \u0003לה רבנן\u0004 \u0005[חכמים]\u0006 להלכה \u0003חיזוק\u0004 לדעת ר' יהודה!","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003החמרין שנכנסו לעיר\u0004 למכור סחורה, \u0003ואמר אחד מהן:\u0004 התבואה \u0003שלי\u0004 שאני מוכר היא מיבול \u0003חדש,\u0004 ועדיין היא לחה ואינה טובה כל כך, \u0003ושל חברי ישן.\u0004 או שאמר: \u0003שלי אינו מתוקן\u0004 (אינו מעושר), \u0003ושל חברי מתוקן — אין נאמנים.\u0004 שאנו חוששים שהם משקרים וגומלים זה לזה, ושמא במקום אחר הם מחליפים את דבריהם, אלא שאומרים כן כדי שייראו נאמנים ועל ידי כך מזרזים את המכירה. \u0003ר' יהודה אומר: נאמנים.\u0004 הרי שאף בדבר מצוי אין ר' יהודה גוזר ומחזק את דברי חכמים!","\u0003אמר אביי\u0004 יש לחלק ולומר כי בכל \u0003ודאי\u0004 של \u0003דבריהם,\u0004 גזירת חכמים בדבר ודאי, כמו תקנת חכמים בענין כתובה — \u0003עבדו רבנן\u0004 \u0005[עשו חכמים]\u0006 \u0003חיזוק,\u0004 ואילו ב\u0003ספק\u0004 בענין של \u0003דבריהם,\u0004 כגון בחמרים, שיש רק ספק בנאמנותם, שהרי אין ודאות שהפירות אינם מעושרים, \u0003לא עבדו רבנן\u0004 \u0005[עשו חכמים]\u0006 \u0003חיזוק. רבא אמר\u0004 טעם אחר: \u0003בדמאי הקילו\u0004 בכלל, שבדיני דמאי, מאחר שבעיקרם הם רק משום חומרה (משום שרוב עמי הארץ מעשרים) — הקילו חכמים ולא גזרו כל כך.","שנינו במשנה ש \u0003ר' מאיר אומר: כל הפוחת\u0004 בכתובה לבתולה ממאתים, ולאלמנה ממנה הרי זו בעילת זנות. ונדייק: \u0003כל הפוחת — אפילו בתנאה\u0004 \u0005[בתנאי],\u0006 שאפילו עשה על כך תנאי מפורש עם האשה, והיא קיבלה על עצמה תנאי זה אין בכך כלום — \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]\u0006 ש\u0003תנאו\u0004 במקרה כזה \u0003בטל, ואית\u0004 \u0005[ויש]\u0006 \u0003לה\u0004 כתובה במלוא הסכום שקצבו חכמים. \u0003ו\u0004למרות שמן הדין תנאו בטל, בכל זאת \u0003כיון\u0004 ש\u0003אמר לה לית ליך\u0004 \u0005[אין לך]\u0006 \u0003אלא מנה — לא סמכא\u0004 \u0005[אין סומכת]\u0006 \u0003דעתה\u0004 על הכתובה ואינה רואה בכך קשר נישואין אמיתי, \u0003והויא\u0004 \u0005[והרי\u0006 נעשית\u0005]\u0006 \u0003לה בעילתו בעילת זנות.\u0004","ומקשים: \u0003והא שמעינן ליה\u0004 \u0005[והרי שמענו אותו]\u0006 את \u0003ר' מאיר\u0004 ש\u0003אמר: כל המתנה על מה שכתוב בתורה — תנאו בטל.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם הוא מתנה \u0003בדרבנן\u0004 \u0005[ב\u0006דבר שהוא מ\u0005דברי סופרים] —\u0006 \u0003תנאו קיים,\u0004 ומדוע בכתובה תנאו בטל, הרי כתובה היא תקנת חכמים?! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' מאיר\u0004 ש\u0003כתובה דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005]\u0006 ולכן אם התנה להפחית מדמי הכתובה — הרי זה כמתנה על מה שכתוב בתורה ותנאו בטל.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מאיר אומר: כל הפוחת\u0004 לאשתו בכתובתה, \u0003לבתולה ממאתים ולאלמנה ממנה — הרי זו בעילת זנות. ר' יוסי אומר: רשאי\u0004 לפחות מסכום הכתובה אם היא מסכימה לכך. \u0003ר' יהודה אומר: רצה — כותב לבתולה שטר של מאתים, והיא כותבת לו \"התקבלתי ממך מנה\", ולאלמנה\u0004 הוא כותב \u0003מנה, והיא כותבת לו \"התקבלתי ממך חמשים זוז\".\u0004","ושואלים: \u0003ו\u0004האם \u0003סבר ר' יוסי\u0004 ש\u0003רשאי\u0004 אדם לפחות מדמי הכתובה? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אין עושין כתובת אשה מטלטלין,\u0004 כלומר, אין מייחדים לה מטלטלים לפרעון כתובתה, \u0003מפני תיקון העולם,\u0004 שמא יאבדו המטלטלים או יפחת ערכם. \u0003אמר ר' יוסי: וכי מה תיקון העולם יש בזו? והלא\u0004 מטלטלים \u0003אין\u0004 דמיהם \u0003קצובין\u0004 לעולם \u0003ו\u0004עלול להיות שיהיו \u0003פוחתין\u0004 דמיהם!","ותחילה מבררים את לשון הברייתא האחרונה: ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003\"אין עושין\" קאמר\u0004 \u0005[אמר],\u0006 ור' יוסי שבא לחלוק עליו לכאורה אומר אותו דבר עצמו! \u0003אלא לאו הכי קאמר\u0004 \u0005[\u0006האם \u0005לא כך אמר]\u0006 התנא הראשון: \u0003במה דברים אמורים\u0004 שאין עושים כתובה מטלטלים — \u0003בשלא קבל עליו אחריות\u0004 על המטלטלים הללו, \u0003אבל\u0004 אם \u0003קבל עליו אחריות\u0004 במקרה שיאבדו — \u0003עושין. ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוסי למימר\u0004 \u0005[לומר]\u0006 אף \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003קיבל עליו אחריות אמאי\u0004 \u0005[מדוע]\u0006 \u0003עושין? והלא אין קצובין ופוחתין!\u0004 שאפילו כשיש אחריות לגבי אבידה אין הדבר מועיל, לפי שהמטלטלים עצמם אפילו כשלא נאבדו עשויים לפחות מערכם לפי שינוי המחירים בשוק, ואינם עשויים להבטיח את סכום הכתובה.","ולענייננו: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי, \u0003ומה התם דדלמא פחתי, חייש\u0004 \u0005[שם ש\u0006רק \u0005שמא יפחתו\u0006 המטלטלים, \u0005חושש]\u0006 \u0003ר' יוסי\u0004 שמא נמצא פוחת מסכום הכתובה — \u0003הכא\u0004 \u0005[כאן]\u0006 ש\u0003ודאי קא פחתה\u0004 \u0005[היא פוחתת]\u0006 מן הכתובה, \u0003לא כל שכן\u0004 שיאסור?! ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם לא ידעה דתחיל\u0004 \u0005[שם,\u0006 כשנתן לה מטלטלים, \u0005אינה יודעת\u0006 אם יפחת ערכם כדי \u0005שתמחל]\u0006 על הפחת, וכיון שלא מחלה — נמצא שמטעה אותה. \u0003הכא ידעה וקא מחלה\u0004 \u0005[כאן\u0006 היא \u0005יודעת ומוחלת],\u0006 וסבור ר' יוסי שכאשר היא יודעת ומוחלת מדעת — מותר לכתחילה לפחות מן הסכום הקצוב.","מסופר: \u0003אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003רמי בר חמא הות נסיבא\u0004 \u0005[היתה נשואה]\u0006 \u0003לרב אויא\u0004"],["\u0003אירכס\u0004 \u0005[אבד]\u0006 שטר \u0003כתובתה, אתו לקמיה\u0004 \u0005[באו\u0006 האשה ובעלה \u0005לפני]\u0006 \u0003רב יוסף\u0004 לשאול מה לעשות, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה אמר שמואל: זו דברי ר' מאיר\u0004 לגבי כתובה שאף הפוחת ממנה סכום כלשהו כאילו הוא בועל בעילת זנות, ואם כן הוא הדין כאן כאשר איבדה כתובתה, כיון שאין לו כל התחייבות כלפיה, אסור לו לדעת ר' מאיר לדור עימה.","\u0003אבל חכמים אומרים:\u0004 אין חוששים עד כדי כך, והאשה סומכת שבסופו של דבר תקבל את הכתובה, ולכן \u0003משהא אדם את אשתו\u0004 אפילו \u0003שתים ושלש שנים בלא כתובה,\u0004 ואין איפוא כל דבר דחוף בכתיבת כתובה, כיון שיש התחייבות מצד הבעל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן אמר שמואל: הלכה כר' מאיר בגזירותיו,\u0004 וכיון שדבריו לענין כתובה הם משום גזירה — הלכה כמותו. אמר רב יוסף: \u0003אי הכי, זיל\u0004 \u0005[אם כך, לך]\u0006 \u0003כתוב לה\u0004 כתובה חדשה.","מסופר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' שמעון בן פזי\u0004 ש\u0003אמר\u0004 בשם \u0003ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: מחלוקת\u0004 זו של ר' יהודה ור' יוסי אם יכול לעשות תנאי עם האשה בעל פה לגבי שיעור כתובתה היא רק \u0003בתחלה, אבל בסוף — לדברי הכל אינה מוחלת\u0004 באמירה בלבד, וצריכה לכתוב על זה שטר. \u0003ור' יוחנן אמר: בין בזו ובין בזו מחלוקת. אמר ר' אבהו: לדידי מיפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' יוחנן\u0004 עצמו, שכך אמר: \u0003דאנא\u0004 \u0005[שאני]\u0006 \u0003ור' יהושע בן לוי לא פלגינן אהדדי\u0004 \u0005[איננו חולקים זה על זה]\u0006 אלא שלא השתמשנו באותה לשון;","\u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 \u0003\"בתחלה\" דקאמר\u0004 \u0005[שאומר]\u0006 \u0003ר' יהושע בן לוי\u0004 — כוונתו היא \u0003תחלת חופה, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"סוף\" — סוף ביאה,\u0004 אם כן לפי זה המחלוקת היא בתחילת חופה, אבל לאחר ביאה — לדעת הכל אינה יכולה למחול בעל פה. \u0003וכי קאמינא אנא\u0004 \u0005[וכאשר אמרתי אני]\u0006 \u0003בין בזו ובין בזו מחלוקת,\u0004 התכוונתי ל\u0003תחלת חופה וסוף חופה\u0004 ש\u0003היא תחילת ביאה.\u0004 ואם כן שניהם מסכימים שהמחלוקת היא רק עד הביאה, אבל לאחר הביאה — הכל מודים שאינה מוחלת על הבטחת כתובה בעל פה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, אמר את הדברים באופן אחר מרב דימי: \u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: מחלוקת לבסוף, אבל בתחלה — דברי הכל מוחלת, ור' יוחנן אמר בין בזו ובין בזו מחלוקת.\u0004 ועל כך \u0003אמר ר' אבהו: לדידי מיפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו],\u0006 מ\u0003ר' יוחנן\u0004 עצמו, \u0003דאנא\u0004 \u0005[שאני]\u0006 \u0003ור' יהושע בן לוי לא פלגינן אהדדי\u0004 \u0005[איננו חולקים זה על זה];\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"לבסוף\"\u0004 ש\u0003אמר ר' יהושע בן לוי\u0004 — כוונתו \u0003סוף חופה\u0004 שהיא תחילת ביאה, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"תחלה\"\u0004 שאמר — כוונתו \u0003תחלת חופה. וכי קאמינא אנא\u0004 \u0005[וכאשר אמרתי אני]\u0006 \u0003בין בזו בין בזו מחלוקת\u0004 — דברתי על \u0003תחלת ביאה וסוף ביאה.\u0004 ואם כן גם לדעת רבין, ר' יהושע בן לוי ור' יוחנן אינם חלוקים, ושניהם מסכימים שבזמן החופה ודאי מוחלת, ומחלוקת התנאים היא לאחר מכן, בסוף חופה שהיא תחילת ביאה. לפי זה יש שתי שיטות בפירוש מחלוקת התנאים, שיטת רב דימי ושיטת רבין.","\u0003אמר רב פפא: אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר ר' אבהו \"לדידי מיפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מ\u0003ר' יוחנן דאנא\u0004 \u0005[שאני]\u0006 \u0003ור' יהושע בן לוי לא פלגינן אהדדי\u0004 \u0005[איננו חולקים זה על זה]\u0006 \u0003\", הוה אמינא\u0004 \u0005[הייתי אומר],\u0006 שעל פי כל המימרות שהגיעו לפנינו יש להסביר כי \u0003ר' יוחנן ור' יהושע בן לוי פליגי\u0004 \u0005[חולקים]\u0006 באמת זה על זה, ואילו \u0003רב דימי ורבין לא פליגי\u0004 \u0005[אינם חולקים]\u0006 זה על זה, ושניהם הביאו מארץ ישראל רק מסורת על מחלוקת אחת.","והייתי מפרש כך: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"סוף\" דקאמר\u0004 \u0005[שאומר]\u0006 \u0003רבין\u0004 שנחלקו, כוונתו היא — \u0003סוף חופה, ומאי\u0004 \u0005[ומהי]\u0006 \u0003\"תחלה\" דקאמר\u0004 \u0005[שאומר]\u0006 \u0003רב דימי\u0004 שנחלקו — \u0003תחלת ביאה,\u0004 שר' יהושע בן לוי ור' יוחנן אכן נחלקו בפירוש מחלוקת ר' יהודה ור' יוסי, ואילו רב דימי ורבין אומרים אותו דבר עצמו, שסוף חופה הוא גם תחילת ביאה.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 רב פפא בזה? הרי לכאורה הוא עצמו מסכים שדרך פירוש זו אינה נכונה, שהרי אמר שדבריו אלה היו מסתברים אלא שאין אומרים כן בגלל דברי ר' אבהו, ומה טעם בדברי רב פפא שאפשר היה לפרש את המחלוקת באופן אחר?","ומסבירים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 שאם אנחנו דנים בפירוש מחלוקת, שיש לנו בה מסורות שונות, מוטב לפרש \u0003דפליגי תרי אמוראי אטעמא דנפשייהו\u0004 \u0005[שחולקים שני אמוראים בטעם של עצמם],\u0006 \u0003ולא פליגי תרי אמוראי אליבא דחד אמורא\u0004 \u0005[ואין חולקים שני אמוראים לשיטתו של אמורא אחד],\u0006 שסביר יותר לומר שיש מחלוקת בטעמים ובסברות, מאשר שיש מחלוקת בהעברתן־מסירתן, של הלכות מפי אחרים. ואף כאן, לולא דברי ר' אבהו, היה גם כאן סביר יותר לפרש שיש מחלוקת בסברה בין ר' יהושע בן לוי ור' יוחנן, ולא לומר שהמחלוקת היא לגבי דיוק פרטי המסורת בין רב דימי ורבין.","\u0003נותנין לבתולה שנים עשר חודש משתבעה הבעל,\u0004 כלומר, משעה שהוא אומר שרוצה לכנוס אותה לאחר הקדושין, ושנים עשר חודש אלה מיועדים \u0003לפרנס את עצמה,\u0004 כלומר, להכין לעצמה מלבושים ותכשיטים לחתונה. \u0003וכשם שנותנין לאשה\u0004 זמן זה — \u0003כך נותנין לאיש לפרנס את עצמו,\u0004 שגם הוא יכין בזמן זה את כל הדרוש לצורך החתונה. דברים אלה אמורים דווקא ברווקים, \u0003ולאלמנה\u0004 שכבר יש לה דברים מוכנים מנישואיה הקודמים נותנים לה \u0003שלשים יום\u0004 בלבד. \u0003הגיע\u0004 ה\u0003זמן\u0004 שקבעו הצדדים לחתונה \u0003ולא נישאו\u0004 בשל איזשהו עיכוב מצידו של הבעל, הרי אותן נשים שהגיע זמנן להינשא \u0003אוכלות משלו,\u0004 מרכושו של הבעל, \u0003ו\u0004אם היה כהן, אף שהן עצמן בנות ישראל — \u0003אוכלות בתרומה.\u0004 לגבי אכילת תרומה זו שנותנים לאשת הכהן שעדיין לא נישאה לו, נחלקו תנאים.","\u0003ר' טרפון אומר: נותנין לה הכל תרומה.\u0004 כלומר, בעלה הכהן יכול לתת לה את הכל מתרומה שיש לו, ובימי טומאתה (כגון בנידתה) שאסור לה לאכול בתרומה, תמכור את התרומה למי שרשאי לאוכלה ותקנה בהם חולין. \u0003ר' עקיבא אומר:\u0004 נותנים לה \u0003מחצה חולין ומחצה תרומה,\u0004 שתוכל לאכול מן החולין בימי טומאתה.","ועוד אמרו: \u0003היבם אינו מאכיל בתרומה,\u0004 שאף על פי שהיתה לכהן שומרת יבם, מכל מקום אינה אוכלת עדיין בתרומה מכוחו. אם \u0003עשתה ששה חדשים\u0004 מאותם תריסר חודשי ההמתנה לנישואין \u0003בפני הבעל\u0004 ומת הבעל, \u0003ו\u0004חיכתה עוד \u0003ששה חדשים בפני היבם\u0004 כדי להשלים שנים עשר חודש אלה לתאריך החתונה, \u0003ואפילו\u0004 עשתה \u0003כולן בפני הבעל חסר יום אחד\u0004 בלבד שעשתה \u0003בפני היבם, או כולן בפני היבם חסר יום אחד\u0004 שעשתה \u0003בפני הבעל\u0004 — עדיין \u0003אינה אוכלת בתרומה,\u0004 משום שהזמן שבו אוכלת בתרומה הוא רק כשהגיע הזמן בפני הבעל לחתונה, ולא נישאה.","כל הדברים האמורים כאן שארוסה שהגיע זמנה להינשא אוכלת בתרומה, \u0003זו\u0004 שיטת \u0003משנה ראשונה.\u0004 ואולם \u0003בית דין של אחריהן\u0004 (של דור מאוחר יותר) \u0003אמרו:\u0004"],["\u0003אין האשה אוכלת בתרומה עד שתכנס\u0004 בפועל \u0003לחופה.\u0004","שואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]\u0006 שנותנים לבתולה שנים עשר חודש להכנות? \u0003אמר רב חסדא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויאמר אחיה ואמה תשב הנער אתנו ימים או עשור\"\u0004 (בראשית כד, נה).","וקודם מבררים את הלשון: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ימים\"? אילימא תרי יומי\u0004 \u0005[אם תאמר שני ימים]\u0006 שהם מיעוט \"ימים\", וכי \u0003משתעי איניש הכי\u0004 \u0005[מדבר אדם כך]?\u0006 שהם \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003תרי יומי\u0004 \u0005[שני ימים]\u0006 תמתין, והוא \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא,\u0004 שרצה שלא תמתין הנערה אפילו יומיים. אם כן הייתכן ש\u0003אמרו ליה\u0004 \u0005[לו]\u0006 אחר סירובו לעיכובה יומיים שתתעכב \u0003עשרה יומי\u0004 \u0005[ימים]?!\u0006 ולכן אי אפשר לפרש \"ימים\" — שני ימים, \"עשור\" — עשרה ימים, שאם כן היו צריכים לומר להיפך \"עשור או ימים\". \u0003אלא מאי\u0004 \u0005[מה\u0006 הפירוש\u0005]\u0006 שם \u0003\"ימים\" — שנה,\u0004 כמו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ימים תהיה גאלתו\"\u0004 (ויקרא כה, כט), ומפורש שם (פרק ל) שהוא שנה, ולכן יש לפרש שאמרו לו שתתעכב הנערה שנה או לפחות עשרה חודשים.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\"ימים\" פירושו \u0003חדש, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"עד חדש ימים\"\u0004 (במדבר יא, כ), וכוונתם היתה שתתעכב חודש או לפחות עשרה ימים. \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003דנין\u0004 (למדים) \u0003\"ימים\" סתם מ\"ימים\" סתם,\u0004 שפירושם שנה, \u0003ואין דנין \"ימים\" סתם מ\"ימים\" שנאמר בהן חדש.\u0004 ומכתוב זה (\"תשב הנערה איתנו ימים...\") למדים שהזמן הרגיל להכנה לנישואין הוא שנים עשר חודש.","\u0003אמר ר' זירא: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003קטנה, בין היא ובין אביה יכולין לעכב,\u0004 ששניהם יכולים לומר שלא תינשא עד שתגדל. ושואלים: \u0003בשלמא איהי מצי מעכבא\u0004 \u0005[נניח היא יכולה לעכב]\u0006 ומובן הדבר. \u0003אלא אביה,\u0004 מדוע יעכב — \u0003אי איהי ניחא\u0004 \u0005[אם היא נוח]\u0006 \u0003לה, אביה מאי נפקא ליה מינה\u0004 \u0005[מה יוצא לו מזה]\u0006 שמעכבה? ומסבירים: \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005],\u0006 \u0003השתא לא ידעה\u0004 \u0005[עכשיו אינה יודעת]\u0006 מה היא עושה, ומסכימה להתחתן, \u0003למחר,\u0004 לאחר זמן, \u0003מימרדא ונפקא, ואתיא ונפלה עילואי\u0004 \u0005[תמרוד\u0006 בבעלה \u0005ותצא, ו\u0006היא \u0005באה ונופלת עלי\u0006 למשא\u0005],\u0006 ולכן הוא מעונין בעצמו שתמתין עד שתגדל, ותינשא בדעה שלימה.","\u0003אמר ר' אבא בר לוי: אין פוסקין\u0004 (קובעים, מסכימים) \u0003על הקטנה להשיאה כשהיא קטנה, אבל פוסקין על הקטנה להשיאה כשהיא גדולה.\u0004 על ההלכה האחרונה שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 וכי מדוע לא יעשו כן? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש דלמא מעיילא פחדא מהשתא וחלשה\u0004 \u0005[נחשוש שמא ייכנס\u0006 בה \u0005פחד\u0006 מן הנישואין \u0005מעכשיו ותיחלש]\u0006 ולכן גם כשתהיה גדולה יהיו לה עיכובים בדבר, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין חוששים לכך, ואפשר לפסוק עליה כשהיא קטנה שתינשא לכשתגדל.","\u0003אמר רב הונא: בגרה יום אחד ונתקדשה — נותנין לה\u0004 להכין צרכי החתונה \u0003שלשים יום\u0004 מיום האירוסין, \u0003כאלמנה.\u0004 שאנו מניחים שלפני שבגרה כבר הכינה לה את כל צרכי הנישואין כדי שלא לעכב את מועד הנישואין. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003בגרה — הרי היא כתבועה\u0004 להינשא. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003כתבועה\u0004 שהיא \u0003בתולה,\u0004 שיש לה שנים עשר חודש? ודוחים: \u0003לא,\u0004 מה שאמרו בגרה דינה כתבועה, הכוונה היא \u0003כתבועה\u0004 שהיא \u0003אלמנה\u0004 שיש לה רק שלושים יום.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003בוגרת ששהתה שנים עשר חדש, ר' אליעזר אומר: הואיל וחייב בעלה במזונותיה\u0004 לאחר שנים עשר חודש — \u0003יפר\u0004 גם את נדריה. על כל פנים רואים כאן שבוגרת גם היא שוהה שנים עשר חודש! ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003בוגרת\u0004 ששהתה שלושים יום, \u0003ו\u0004כן נערה \u0003ששהתה שנים עשר חודש,\u0004 ועל כך \u0003ר' אליעזר אומר: הואיל ובעלה חייב במזונותיה — יפר.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003המארס את הבתולה, בין שתבעה הבעל\u0004 להינשא \u0003והיא מעכבת,\u0004 שאומרת שדרוש לה יותר זמן, \u0003ובין שתבעה היא\u0004 להינשא \u0003ובעל מעכב,\u0004 שאיננו מוכן עדיין — בכל מקרה \u0003נותנין לה שנים עשר חדש משעת תביעה, אבל לא משעת אירוסין,\u0004 גם אם היו האירוסין זמן רב קודם לכן, שהזמן הקובע לענין זה הוא זמן התביעה. \u0003ו\u0004זו ש\u0003בגרה, הרי היא כתבועה. כיצד, בגרה יום אחד ונתקדשה — נותנין לה שנים עשר חדש\u0004 משעה שנתקדשה, \u0003ולארוסה\u0004 נותנים \u0003שלשים יום.\u0004 הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב הונא\u0004 הסובר כי זו שבגרה יום אחד ונתקדשה אין נותנים לה אלא שלושים יום כאלמנה, שהרי הברייתא הזו ממש נגד דבריו! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונידחו דבריו.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ולארוסה שלשים יום\"? אמר רב פפא: הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003בוגרת שעברו עליה שנים עשר חדש בבגרות ונתקדשה — נותנין לה שלשים יום כאלמנה,\u0004 ולא עוד שנים עשר חודש.","שנינו במשנה: \u0003הגיע זמן\u0004 שקבעו להינשא \u0003ולא נישאו\u0004 — אוכלות בתרומה. \u0003אמר עולא: דבר תורה\u0004 אפילו \u0003ארוסה בת ישראל אוכלת\u0004 מיד עם אירוסיה לכהן \u0003בתרומה,\u0004 גם לפני שהגיע זמן הנישואין, \u0003שנאמר: \"וכהן כי יקנה נפש קנין כספו\u0004 הוא יאכל בו\u0003\"\u0004 (ויקרא כב, יא), \u0003והאי נמי\u0004 \u0005[וזו,\u0006 האשה, \u0005גם כן]\u0006 \u0003קנין כספו הוא\u0004 על ידי הקידושין, ומן הדין היתה צריכה לאכול בתרומה. ו\u0003מה טעם אמרו\u0004 חכמים ש\u0003אינה אוכלת — שמא ימזגו לה כוס\u0004 יין של תרומה \u0003בבית אביה,\u0004 שאם היא נחשבת כאשת כהן יכולה היא לשתותו, אך כיון שהיא עדיין בבית אביה עד הנישואין יש חשש ש\u0003תשקה לאחיה ולאחותה\u0004 מיין התרומה, והרי הם זרים לכהונה ואסורים בתרומה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה חושש, אם כן, אף כש\u0003הגיע זמן ולא נישאו נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש שתיתן לבני משפחתה שעדיין היא בבית אביה! ומשיבים: \u0003התם, דוכתא\u0004 \u0005[שם, מקום]\u0006 הוא \u0003מייחד לה,\u0004 שכיון שהוא חייב במזונותיה הריהו דואג שתקבל את מזונותיה במקום מיוחד, כדי שלא תוציא מהם לבני משפחתה ותפסידו.","ומקשים: \u0003אלא מעתה,\u0004 שאתה חושש שאדם מאכיל משלו לאנשים הקרובים לו, אם כן \u0003לקיט\u0004 (שכיר) שהוא \u0003כהן\u0004 הנמצא בבית \u0003ישראל\u0004 ש\u0003לא ליכול\u0004 \u0005[יאכל]\u0006 \u0003בתרומה דלמא אתו למיכל בהדיה\u0004 \u0005[שמא יבואו לאכול\u0006 בני הבית הישראלים יחד \u0005איתו]\u0006 מן התרומה! ודוחים: \u0003השתא מדידהו ספו ליה\u0004 \u0005[עכשיו,\u0006 הרי, \u0005משלהם\u0006 הם \u0005מאכילים אותו],\u0006 שהרי הוא שכיר שלהם — וכי \u0003מדידיה אכלי\u0004 \u0005[משלו\u0006 הם \u0005אוכלים]?!\u0006 ובודאי אין כלל לחשוש שיאכיל אותם משלו. זה היה טעמו של עולא.","ואילו \u0003רב שמואל בר רב יהודה אמר:\u0004 הטעם לגזירת חכמים הוא \u0003משום סימפון\u0004 (ביטול תנאי), שמא יתברר אחר זמן האירוסין שיש בה מומים, ויתבטלו הנישואין ונמצא שאכלה בתרומה שלא כדין.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 גם אם \u0003נכנסה לחופה ולא נבעלה נמי\u0004 \u0005[גם כן]\u0006 לא תאכל בתרומה, שהרי אינו יודע אם יש בה מומים! ומשיבים: \u0003התם, מיבדק בדיק לה והדר מעייל\u0004 \u0005[שם, בודק\u0006 הוא \u0005אותה\u0006 על ידי קרובותיו \u0005ואחר כך מכניסה\u0006 לחופה\u0005],\u0006 ולכן אין חשש לסימפון.","ומקשים: \u0003אלא מעתה,\u0004 לפי טעם זה, \u0003עבד\u0004 של \u0003כהן שלקחו\u0004 (קנאו) \u0003מישראל לא ליכול\u0004 \u0005[יאכל]\u0006 \u0003בתרומה, משום\u0004 חשש של \u0003סימפון,\u0004 והקנין יהיה קנין בטעות, ויחזור העבד לידי ישראל לאחר שכבר אכל תרומה שלא כדין! ומשיבים: \u0003סימפון בעבדים ליכא\u0004 \u0005[אין]\u0006 שאין מקום למציאת פגם כזה שיבטל את המכירה. וטעמו של דבר: \u0003דאי\u0004 \u0005[שאם]\u0006 המום הוא \u0003דאבראי\u0004 \u0005[מבחוץ] —\u0006 \u0003הא קחזי ליה\u0004 \u0005[הרי\u0006 הוא \u0005רואה אותו]\u0006 בשעת קניה ובוודאי נתרצה בו. \u0003ואי דגואי\u0004 \u0005[ואם\u0006 מום \u0005שבפנים]\u0006 — הלא \u0003למלאכה קא בעי\u0004 \u0005[צריך\u0006 אותו\u0005],\u0006 \u0003ו\u0004מומים \u0003שבסתר לא איכפת ליה\u0004 \u0005[לו].\u0006 ואם תאמר שנמצא בו מום מסוג אחר, וכגון \u0003שנמצא\u0004 העבד שהוא \u0003גנב או\u0004"],["\u0003קוביוסטוס\u0004 \u0005[גונב נפשות]\u0006 — \u0003הגיעו,\u0004 כלומר, תפסו, המוכר \"תפס\" את הלוקח, שאינו יכול לבטל את המכירה, שאין המקח בטל בגלל מומים אלה. אלא \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 בעבד חסרון חמור שיש בו כדי לבטל את החוזה — שנמצא שהעבד הוא \u0003לסטים\u0004 (שודד) \u0003מזויין או מוכתב למלכות\u0004 (נידון למוות), והמלכות תתפוס ותהרוג אותו, אולם \u0003הנהו קלא אית להו\u0004 \u0005[\u0006מומים \u0005אלה קול יש להם]\u0006 שבמקרים נדירים וחמורים כאלה יודעים הכל על כך, ואף הוא ידע על כך, ומאחר וקנאו — ודאי קיבל עליו עבד שכזה, ולכן אין לחשוש לביטול המקח בעבדים.","ושואלים: \u0003מכדי\u0004 \u0005[הרי],\u0006 \u0003בין למר\u0004 \u0005[לחכם\u0006 זה, עולא\u0005]\u0006 \u0003ובין למר\u0004 \u0005[לחכם\u0006 זה, רב שמואל בר יהודה\u0005]\u0006 בת ישראל שנתארסה לכהן \u0003לא אכלה\u0004 \u0005[אינה אוכלת]\u0006 בתרומה כל עוד היא ארוסה, אם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 למעשה\u0005]\u0006 אם הטעם הוא זה או זה? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 במקרים של \u0003קבל, מסר, והלך.\u0004 אם קיבל הבעל על עצמו את המומים, שאז קיים החשש שתשקה האשה לבני משפחתה כוס של תרומה, ואין חשש לסימפון. ולהיפך, אם מסר האב את האשה לשלוחי הבעל לנישואין, או שהלכו שלוחי האב עם שלוחי הבעל, שאין לחשוש שתשקה לבני משפחתה שהרי כבר אינה נמצאת איתם, אבל לעומת זאת יש לחוש לסימפון.","שנינו במשנה שנחלקו מה נותן הכהן למזונות ארוסתו כשהגיע זמן הנישואין, ש \u0003ר' טרפון אומר: נותנין לה הכל תרומה\u0004 ור' עקיבא אומר: נותנים לה מחצה חולין כדי שיהיה לה מה לאכול בימי נידותה שאסורה אז לאכול בתרומה, ומחצה תרומה. \u0003אמר אביי: מחלוקת\u0004 זו היא \u0003בבת כהן\u0004 שנישאה \u0003לכהן, אבל בבת ישראל\u0004 שנישאה \u0003לכהן — דברי הכל\u0004 נותן לה \u0003מחצה חולין ומחצה תרומה.\u0004 כי בת כהן בקיאה בשמירת התרומה ויודעת כיצד להיזהר בה בימי טומאתה, ומשמגיעים ימי טומאתה יודעת היא שצריכה למכור מפירות התרומה ולקנות תמורתם פירות חולין, אבל בת ישראל שעדיין אינה בקיאה בכך, יש לחשוש שמא תטמא את התרומה, ולכן מתחילה נותנים לה גם מקצת חולין שתאכל אותם.","\u0003ו\u0004עוד \u0003אמר אביי: מחלוקת\u0004 זו היא דווקא \u0003בארוסה\u0004 שהגיע זמנה ועדיין היא גרה בבית אביה, ובימי טומאתה מתעסקים אביה או אחיה במכירת התרומה לצורך קניית חולין, \u0003אבל בנשואה\u0004 שעוסקת בצרכיה בעצמה — \u0003דברי הכל\u0004 נותן לה בעלה \u0003מחצה חולין ומחצה תרומה.\u0004 שאינו מן הראוי שאשתו תצטרך לטרוח ולמכור את התרומה כדי לקבל חולין.","\u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' טרפון אומר: נותנין לה הכל תרומה, ר' עקיבא אומר: מחצה חולין ומחצה תרומה. במה דברים אמורים — בבת כהן לכהן, אבל בת ישראל לכהן — דברי הכל מחצה חולין ומחצה תרומה. במה דברים אמורים — בארוסה, אבל בנשואה — דברי הכל מחצה חולין ומחצה תרומה.\u0004","\u0003ר' יהודה בן בתירא אומר:\u0004 לא מחצה ומחצה, אלא \u0003נותנין לה שתי ידות\u0004 (שני חלקים, שני שליש) \u0003של תרומה, ואחת של חולין. ר' יהודה אומר: נותן לה הכל תרומה, ו\u0004כמות כזאת שתספיק לה שכאשר \u0003היא מוכרת\u0004 בימי טומאתה תוכל להיות \u0003לוקחת\u0004 (קונה) \u0003בדמים\u0004 שקיבלה בתמורה \u0003חולין\u0004 כדי צורכה. \u0003רבן שמעון בן גמליאל אומר: כל מקום שהוזכרה תרומה — נותנין לה כפלים\u0004 מכפי השיעור של \u0003חולין,\u0004 כדי שלא תצטרך לטרוח ולחזר אחר קונים הקונים תרומה (שהרי אין אנשים קופצים לקנות תרומה ומחירה זול יותר, שכן לא כל אדם רשאי לאוכלה), ואולם כיון שההפרש בכמות שקיבלה גדול כל כך, בודאי תמצא קונים בנקל.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין שיטת ר' יהודה לשיטת רבן שמעון הלכה למעשה? ומשיבים: \u0003איכא בינייהו טירחא\u0004 \u0005[יש ביניהם\u0006 הבדל \u0005טירחה],\u0006 שלדעת ר' יהודה עליה לטרוח ולמצוא קונים שיספקו לה חולין די צורכה. ולרבן שמעון בן גמליאל מוסיף לה הרבה יותר תרומה כדי למנוע ממנה את הטורח במכירה.","שנינו במשנה ש \u0003היבם אינו מאכיל בתרומה.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003\"קנין כספו\"\u0004 (ויקרא כב, יא) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 שאוכל בתרומה, \u0003והאי\u0004 \u0005[וזו]\u0006 היבמה \u0003קנין\u0004 של \u0003אחיו הוא,\u0004 שאין ליבם קנין ביבמה עד שיבוא עליה.","שנינו במשנה שאם \u0003עשתה ששה חדשים\u0004 מזמן התביעה \u0003בפני הבעל\u0004 ושישה חודשים אחרים בפני היבם, ואחר כך שנינו שאם עשתה אפילו רוב השנה בפני הבעל, ואחר כך שנינו עוד שגם אם עשתה רוב הזמן בפני היבם — אין לה מזונות. ושואלים: \u0003השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 אפילו אם עשתה את רוב השנה \u0003בפני הבעל\u0004 ורק מקצתה בפני היבם \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003לא\u0004 מקבלת ממנו מזונות, כיון שלא עשתה את כולה בפניו, האם \u0003בפני היבם מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006 ומשיבים: בסגנון של \u0003\"זו ואין צריך לומר זו\" קתני\u0004 \u0005[שנה]\u0006 את המשנה, כלומר, המקרים מסודרים מן הקשה אל הקל, שקודם דובר באופן שעשתה רוב הזמן בפני בעלה, ואין צריך לומר במקרה הפשוט יותר כשעשתה רק מקצת בפני הבעל. וכן אין צריך לומר הלאה, במקרה הפשוט יותר של יבם ולא של בעל.","שנינו במשנה שכל ההלכות הללו שאשה אוכלת בתרומה בעודה בבית אביה כאשר הגיע זמנה להינשא, \u0003זו\u0004 היא שיטת \u0003משנה ראשונה,\u0004 אבל חכמים אחרונים אמרו שאין המאורסת לכהן אוכלת בתרומה ואפילו כשהגיע הזמן, אלא מכשתיכנס לחופה ממש. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של בית דין אחרון זה? \u0003אמר עולא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב שמואל בר יהודה: משום סימפון,\u0004 שאנו חוששים שמא ימצא בה פגם, ויתבטלו הנישואין, ונמצא שאכלה תרומה שלא כדין.","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003עולא,\u0004 אם כן \u0003קמייתא\u0004 \u0005[\u0006הגזירה \u0005הראשונה]\u0006 שגזרו חכמים במשנה ראשונה שאינה אוכלת בתרומה מיד משנתארסה, לדבריו הטעם הוא \u0003שמא ימזגו לה כוס בבית אביה, ובתרייתא\u0004 \u0005[ו\u0006המשנה, התקנה \u0005האחרונה]\u0006 שגזרו שלא תאכל עד שתכנס לחופה היא \u0003משום סימפון,\u0004 לפי זה יש פה שני טעמים שונים לשתי שיטות ההלכה."],["\u0003אלא ל\u0004דעת \u0003רב שמואל בר יהודה, קמייתא\u0004 \u0005[\u0006התקנה \u0005הראשונה]\u0006 \u0003משום סימפון ובתרייתא\u0004 \u0005[והאחרונה]\u0006 גם כן \u0003משום סימפון,\u0004 ואם כן \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין טעמם של הראשונים לטעמם של האחרונים?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת לענין \u0003בדיקת חוץ,\u0004 כלומר, הבדיקה הראשונה שבדק ביד קרובותיו, והן יכלו לבדוק רק בדיקה שטחית. ש\u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 של המשנה הראשונה \u0003סבר\u0004 כי \u0003בדיקת חוץ שמה בדיקה,\u0004 ולכן כיון שתבעה להינשא והגיע הזמן, הרי היא כאשתו, ומאחר שבדקה על ידי קרובותיו אין לחשוש עוד לסימפון. \u0003ומר\u0004 \u0005[וחכם]\u0006 זה\u0005,\u0006 בית דין אחרון, \u0003סבר\u0004 ש\u0003בדיקת חוץ לא שמה בדיקה\u0004 ועדיין יש לחשוש שמא, כאשר יתייחד איתה, ימצא בה מום ויתחרט על הנישואין.","\u0003המקדיש מעשה ידי אשתו,\u0004 כלומר, מה שאשתו \"עושה\" (עובדת) בבית כתקנת חכמים — \u0003הרי זו\u0004 האשה \u0003עושה\u0004 (עובדת) \u0003ואוכלת\u0004 ממה שעושה, ואין מעשה ידיה קדושים. ולא נחלקו אלא לגבי \u0003המותר,\u0004 כלומר, אם עשתה יותר מן השיעור הקצוב, מה יהיה דינו, ש\u0003ר' מאיר אומר:\u0004 המותר הוא \u0003הקדש,\u0004 ו\u0003ר' יוחנן הסנדלר אומר:\u0004 אף המותר הוא \u0003חולין.\u0004","\u0003אמר רב הונא אמר רב, יכולה אשה לומר לבעלה: \"איני ניזונת\u0004 משלך \u0003ואיני עושה\u0004 (ואינני עובדת עבורך) \u0003\".\u0004 וטעם הדבר: מכיון ש\u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003כי תקינו רבנן\u0004 \u0005[כאשר תיקנו חכמים]\u0006 את החובות והזכויות בין הבעל והאשה, תקנת \u0003מזוני\u0004 (מזונות), \u0003עיקר,\u0004 שהתקנה שהבעל יפרנס היא עיקר התקנה, \u0003ו\u0004חזרו ותיקנו ש\u0003מעשה ידיה\u0004 יהיו שלו, \u0003משום איבה,\u0004 שאם הוא יפרנסנה, והיא תעבוד ולא תתן לו את שכר עבודתה, תהיה לו איבה כלפיה. \u0003ו\u0004משום כך \u0003כי אמרה\u0004 \u0005[כאשר\u0006 היא \u0005אומרת]\u0006 \u0003\"איני ניזונת ואיני עושה\" — הרשות בידה,\u0004 שיכולה האשה לוותר על עיקר התקנה שהיתה לטובתה.","על סברה זו \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003תקנו מזונות תחת\u0004 (במקום) \u0003מעשה ידיה,\u0004 משמע שמעשה ידיה היא החובה הבסיסית, וכיון שחייבת בעבודה תיקנו כנגד זה שיפרנסנה בעלה! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 ושנה ש\u0003תקנו מעשה ידיה תחת מזונות.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם אפשר \u0005לומר שמסייע לו]\u0006 לרב הונא ממה ששנינו במשנתנו: \u0003המקדיש מעשה ידי אשתו — הרי היא עושה ואוכלת. מאי לאו\u0004 \u0005[האם לא\u0006 מדובר\u0005]\u0006 \u0003בניזונת\u0004 משל בעלה, כלומר, שהוא רוצה לזונה והיא מוותרת על כך ולכן אין מעשה ידיה ברשותו שיוכל להקדישם? ודוחים: \u0003לא,\u0004 מדובר פה \u0003בשאינה ניזונת\u0004 מבעלה.","ומקשים: \u0003אי\u0004 \u0005[אם\u0006 מדובר\u0005]\u0006 \u0003בשאינה ניזונת — מאי למימרא\u0004 \u0005[מה\u0006 יש \u0005לומר]\u0006 בזה שאין הוא יכול להקדיש את מעשה ידיה? \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003יכול הרב\u0004 (האדון) \u0003לומר לעבד\u0004 הכנעני: \u0003\"עשה עמי\u0004 (עבוד בשבילי) \u0003ואיני זנך\",\u0004 שאין חובה עלי לפרנסך — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003בעבד כנעני,\u0004 ש\u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"עמך\", אבל עבד עברי דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"\u0004כי טוב לו \u0003עמך\"\u0004 (דברים טו, טז) — \u0003לא,\u0004 שחייב לפרנסו כשם שמפרנס את בני ביתו, \u0003וכל שכן אשתו\u0004 שחייב לפרנסה. ואם כן, כיון שאינו יכול לומר לאשתו שתעבוד ולא תיזון משלו, הרי כאשר אינו זן אותה — ודאי שאין לו זכות במעשה ידיה ובודאי לא זאת באה משנתנו לומר!","ומשיבים: אמנם דין זה לא היה צורך לשנותו אבל \u0003סיפא איצטריך ליה\u0004 \u0005[הסוף הוצרך לו]\u0006 שיש בו חידוש לגבי \u0003מותר,\u0004 ש\u0003ר' מאיר אומר: הקדש,\u0004 ו\u0003ר' יוחנן הסנדלר אומר: חולין.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטה זו של רב הונא על דברי \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש: לא תימא\u0004 \u0005[אל תאמר]\u0006 \u0003טעמא\u0004 \u0005[\u0006ש\u0005הטעם]\u0006 של \u0003ר' מאיר משום דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]\u0006 \u0003אדם מקדיש דבר שלא בא לעולם,\u0004 ולכן חל ההקדש על מעשה ידיה אף על פי שעדיין לא עשתה אותם. \u0003אלא טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' מאיר: מתוך שיכול לכופה\u0004 (לכפות אותה) \u0003למעשה ידיה\u0004 — הרי יש לו זכות מסויימת על ידיה, ולכן \u0003נעשה\u0004 באותה שעה \u0003כאומר לה \"יקדשו ידיך לעושיהם\",\u0004 שהידיים בנוגע למה שהן עושות תהיינה כהקדש, ונמצא שההקדש חל על דבר הקיים כבר בעולם (הידיים עצמן). ומכיון שאמר ריש לקיש \"שיכול לכופה למעשה ידיה\" משמע שאינה יכולה לומר \"איני נזונית ואינה עושה\".","על עצם דבריו של ריש לקיש מקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא אמר לה הכי\u0004 \u0005[כך],\u0006 אלא אמר: \"מעשה ידיך יקדשו\"! ומשיבים: \u0003כיון דשמעינן ליה\u0004 \u0005[ששמענו אותו],\u0006 את \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 כלל: \u0003אין אדם מוציא דבריו לבטלה,\u0004 ולפי הכלל הזה, כאשר אדם אומר דבר שמבחינת ההלכה אין לו משמעות, אנו נותנים לו פירוש שיהיה לו תוקף הלכתי — אף כאן, מה שאמר שמעשה ידיה יקדשו — לא אמר דבר שיש בו ממש, ולכן אנו מפרשים את דבריו באופן אחר, ו\u0003נעשה כאומר לה: \"יקדשו ידיך לעושיהם\".\u0004","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' מאיר\u0004 בדרך כלל כי \u0003אין אדם מקדיש דבר שלא בא לעולם? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 גוי \u0003האומר לאשה: \"הרי את מקודשת לי לאחר שאתגייר\", או\u0004 שהיא גוייה, ואומר לה: \u0003\"לאחר שתתגיירי\u0004 את \u0003\",\u0004 או שהיה עבד ואמר לה שהיא מקודשת \u0003\"לאחר שאשתחרר\",\u0004 או שהיתה שפחה ואמר לה: \u0003\"לאחר שתשתחררי\",\u0004 או שהיתה אשת איש ואמר לה: \u0003\"לאחר שימות בעליך\", או\u0004 שהוא בעל אחותה ואמר לה שתתקדש לו \u0003\"\u0004לאחר \u0003שתמות אחותיך\"\u0004 שאז יוכלו הקידושין לחול עליה, \u0003או\u0004 שהיתה שומרת יבם ואמר לה: \u0003\"לאחר שיחלוץ ליך יבמיך\", ר' מאיר אומר:\u0004 אם אירעו כל הדברים הללו — \u0003מקודשת.\u0004 ומשמע שר' מאיר סבור שהקידושין חלים גם על דבר שאיננו עתה בעולם!","ואומרים: אכן, \u0003מההיא\u0004 מאותה ברייתא — \u0003אין\u0004 \u0005[כן]\u0006 אפשר ללמוד שר' מאיר אמנם סבור כך, אלא שריש לקיש רצה לומר כי \u0003מהא ליכא למשמע מינה\u0004 \u0005[מזו,\u0006 שלנו, \u0005אין לשמוע ממנה].\u0006 דבר זה, שהרי אפשר לפרש דבריו גם באופן אחר, מצד שאין אדם מוציא דבריו לבטלה.","שנינו במשנה שאם הקדיש את \u0003המותר\u0004 מהקיצבה הקבועה למעשה ידיה, \u0003ר' מאיר אומר\u0004 שהוא \u0003הקדש.\u0004 ושואלים: לשיטה זו, \u0003אימת\u0004 (מתי) נעשה המותר \u0003קדוש? רב ושמואל דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מותר\u0004 רק \u0003לאחר מיתה\u0004 של האשה הוא \u0003קדוש. רב אדא בר אהבה אמר: מותר\u0004 כבר \u0003מחיים\u0004 הוא \u0003קדוש.\u0004","\u0003הוי\u0004 \u0005[עסק,\u0006 התקשה\u0005]\u0006 \u0003בה רב פפא: במאי\u0004 \u0005[במה,\u0006 באיזה מקרה מדובר\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי מדובר \u0003ב\u0004מקרה שבעלה \u0003מעלה\u0004 (נותן) \u0003לה מזונות, ומעלה לה\u0004 גם \u0003מעה כסף\u0004 לשבוע \u0003ל\u0004שאר \u0003צרכיה\u0004 — אם כן \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 שרק \u0003לאחר מיתה קדוש?\u0004 שהרי יש מותר ניכר בכל שבוע ושבוע!","\u0003ואלא\u0004 תאמר שמדובר \u0003כשאין מעלה לה מזונות, ולא מעלה לה מעה כסף לצרכיה\u0004 והיא צריכה לפרנס את עצמה לגמרי — אם כן \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה הטעם של מי שאומר]\u0006 ש\u0003מחיים קדוש?\u0004 הלא ייתכן שבשבוע אחד או שניים לא תמצא עבודה, וכיון שאינו נותן לה מזונות תצטרך לכסף, ואין כאן מותר כלל!","ומשיבים: \u0003לעולם\u0004 תפרש שמדובר \u0003ב\u0004מקרה ש\u0003מעלה לה מזונות, ו\u0004אולם \u0003אינו מעלה לה מעה כסף לצרכיה,\u0004 ובכך נחלקו: \u0003רב ושמואל סברי\u0004 \u0005[סבורים]\u0006 שעיקר התקנה היא ש\u0003תקנו\u0004"],["\u0003מזונות תחת מעשה ידיה, ומעה כסף\u0004 שנותן לה \u0003תחת\u0004 (במקום) \u0003מותר\u0004 שמוסיפה לעשות יותר מן השיעור, \u0003וכיון דלא קא יהיב\u0004 \u0005[שאינו נותן]\u0006 \u0003לה מעה כסף —\u0004 ה\u0003מותר דידה הוי\u0004 \u0005[שלה הוא],\u0006 אלא אם כן נשאר ממנו לאחר מותה והבעל יורש אותה. \u0003רב אדא בר אהבה סבר: תקנו מזונות תחת מותר, ומעה כסף תחת מעשה ידיה, וכיון דקא יהיב\u0004 \u0005[שהוא נותן]\u0006 \u0003לה מזוני\u0004 \u0005[מזונות],\u0006 אם כן ה\u0003מותר דידיה הוי\u0004 \u0005[שלו הוא]\u0006 ולכן חלה עליו קדושה מיד כשהותירה.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]\u0006 ומה טעמם? ומסבירים: \u0003מר סבר\u0004 \u0005[חכם\u0006 זה, רב ושמואל \u0005סבורים]\u0006 שתיקנו \u0003מידי דשכיח ממידי דשכיח\u0004 \u0005[דבר מצוי מדבר מצוי]\u0006 ולכן תיקנו מזונות שהם מצויים, תחת מעשה ידיה שהוא מצוי. \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, רב אדא בר אהבה, \u0005סבור]\u0006 כי תיקנו \u0003מידי דקייץ ממידי דקייץ\u0004 \u0005[דבר קצוב מדבר קצוב]\u0006 וכיון שיש קיצבה במעה כסף, וקיצבה כמה היא צריכה לעשות במעשה ידיה, תיקנו זה כנגד זה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב אדא בר אהבה, הלא אמרו: \u0003\"תקנו מזונות תחת מעשה ידיה\",\u0004 ולא \"תחת מותר\"! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 ושנה: \u0003\"תחת מותר מעשה ידיה\".\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003אם אינו נותן לה מעה כסף לצורכיה — מעשה ידיה שלה.\u0004 משמע שמעשה ידיה תיקנו כנגד המעה, וכדעת רב אדא! ודוחים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003מותר מעשה ידיה שלה.\u0004 ומקשים: \u0003והא עלה קתני\u0004 \u0005[והרי עליה שנה]\u0006 והסביר באותה משנה: \u0003מה היא עושה לו,\u0004 מה שיעור ההתחייבות שלה לעשות עבורו — \u0003משקל חמש סלעים שתי\u0004 שהיא טווה \u0003ביהודה,\u0004 שהן משקל עשר סלעים במשקל של גליל, ששם היו הסלעים קטנים יותר. משמע מכאן שהברייתא אינה מדברת במותר אלא במעשה ידיה עצמם!","ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003מעשה ידיה כמה הוי\u0004 \u0005[הם]\u0006 \u0003דלידע\u0004 \u0005[\u0006כדי \u0005שנדע]\u0006 את ה\u0003מותר דידה\u0004 \u0005[שלה]\u0006 \u0003כמה\u0004 הוא, לכן אמרו שמעשה ידיה הקצוב הוא \u0003משקל חמש סלעים שתי ביהודה, שהן עשר סלעים בגליל.\u0004","\u0003אמר שמואל: הלכה כר' יוחנן הסנדלר,\u0004 שאף את המותר אינו יכול להקדיש. ולפי זה יוצא שאינו יכול כלל להקדיש את מעשה ידי אשתו לפי שאינם עתה בעולם.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 אמרה אשה \u0003\"קונם\u0004 אסור בנדר כל מה \u0003שאני עושה לפיך\u0004 (עבורך) \u0003\"\u0004— \u0003אינו צריך\u0004 הבעל \u0003להפר\u0004 כלל נדר זה, משום שיש לה התחייבות מוקדמת לעשות עבורו ולכן אין הקונם חל על דבר שאינו שלה. \u0003ר' עקיבא אומר:\u0004 אף על פי כן \u0003יפר\u0004 הבעל, \u0003שמא תעדיף\u0004 (תוסיף) \u0003עליו\u0004 על מעשה ידיה \u0003יתר מן הראוי לו,\u0004 ונמצא הקונם חל על המותר. \u0003ר' יוחנן בן נורי אמר: יפר,\u0004 ומטעם אחר: \u0003שמא יגרשנה\u0004 ויחול הנדר מן הגירושין ואילך, \u0003ו\u0004כיון שאסרה עליו את מעשה ידיה \u0003תהא אסורה לחזור\u0004 לו לאחר גירושיה, שלא יוכל לחזור ולשאתה לאשה, שאי אפשר שלא יהנה כלל ממעשה ידי אשתו.","\u0003ואמר שמואל: הלכה כר' יוחנן בן נורי.\u0004 ואם הלכה כר' יוחנן בן נורי בזה שיכולה לאסור מעשה ידיה לעולם גם לאחר גירושין אף שלא באו לעולם — משמע שיש אפשרות להקדיש דבר שלא בא לעולם, ובניגוד לדברי ר' יוחנן הסנדלר! ומשיבים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל\u0004 כי \u0003הלכה כר' יוחנן בן נורי,\u0004 הרי זה רק \u0003ל\u0004ענין \u0003העדפה,\u0004 שהנדר חל רק על מותר מעשי ידיה.","ומקשים: אם כן, \u0003ולימא\u0004 \u0005[ושיאמר\u0006 במפורש\u0005]:\u0006 \u0003הלכה כר' יוחנן בן נורי להעדפה! אי נמי\u0004 \u0005[או גם כן]\u0006 יאמר: \u0003אין הלכה כ\u0004שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]!\u0006 \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יאמר באופן פשוט: \u0003הלכה כר' עקיבא\u0004 שהוא־הוא החושש להעדפה!","\u0003אלא\u0004 יש לחזור מתירוץ זה ולהסביר באופן אחר, ש\u0003אמר רב יוסף: קונמות קאמרת\u0004 \u0005[אומר אתה]\u0006 להוכיח משם את דבריך שאדם יכול להקדיש דבר שלא בא לעולם? — \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003קונמות\u0004 שיש להם דין מיוחד, \u0003מתוך ש\u0004בדין קונמות \u0003אדם אוסר פירות חבירו עליו.\u0004 שאם אמר אדם \"קונם פירותיך עלי\" נאסר בהם, אף שפירות אלה אינם שלו, ויחול האיסור עליהם רק כאשר יגיעו לרשותו, ולכן יש בקונם גם כוח ש\u0003אדם מקדיש\u0004 ואוסר גם \u0003דבר שלא בא לעולם\u0004 אף שעדיין לא בא לרשותו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין השוואה זו מוכיחה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 זה ש\u0003אדם אוסר פירות חבירו עליו,\u0004 מדוע יכול הוא לעשות כן — \u0003שכן\u0004 ידוע הדין ש\u0003אדם אוסר פירותיו\u0004 שלו \u0003על חבירו\u0004 שבשני המקרים יש לפחות צד אחד באיסור שהוא ברשותו, אם כשאוסר דבר על עצמו, או שאוסר דבר שברשותו על אחרים. אולם, וכי \u0003יאסר דבר שלא בא לעולם על חבירו, שכן אין אדם אוסר פירות חבירו על חבירו,\u0004 שכשם שאינו יכול לאסור בקונם פירות שאינם ברשותו על אדם שאינו ברשותו, כך אינו יכול לאסור פירות שלא באו לעולם (שאינם עדיין ברשותו) על אדם אחר. ואם כן, כיצד יכולה האשה לאסור מעשי ידיה שעדיין לא באו לעולם, על בעלה?","\u0003אלא אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 יש לחזור מהסבר זה ולומר כי מדובר שם לא כשאמרה \"קונם מעשה ידיה\", אלא \u0003באומרת \"יקדשו ידי לעושיהם\",\u0004 שה\u0003ידים\u0004 עצמן \u0003איתנהו\u0004 \u0005[מצויות]\u0006 \u0003בעולם,\u0004 ולכן חל עליהן ההקדש.","ושואלים: \u0003וכי קאמרה הכי מי מקדשן\u0004 \u0005[וכאשר\u0006 היא \u0005אומרת כך,\u0006 בסגנון זה, \u0005האם\u0006 הן \u0005מתקדשות]?\u0006 \u0003הא משעבדא ליה\u0004 \u0005[הרי\u0006 היא \u0005משועבדת לו]\u0006 לבעלה, למעשה ידיה, ואיך היא יכולה להקדיש דבר שאינו שלה! ומשיבים: \u0003דאמרה לכי מיגרשה\u0004 \u0005[ש\u0006היא \u0005אומרת, שכאשר תתגרש\u0006 מבעלה\u0005]\u0006 אז יחול ההקדש.","ומקשים: \u0003ומי איכא מידי דאילו השתא לא קדיש ולקמיה קדיש\u0004 \u0005[והאם יש דבר שאילו\u0006 היה עושה אותו \u0005עכשיו אין\u0006 חלה עליו \u0005קדושה ולאחר מכן יתקדש]?\u0006 \u0003אמר ר' אלעאי: אלמה\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004 הרי מוצאים אנו מקרים כאלה, \u0003אילו האומר לחבירו \"שדה זו שאני מוכר לך לכשאקחנה ממך\u0004 (כשאקנה אותה ממך בחזרה) \u0003תיקדש\" — מי\u0004 \u0005[האם]\u0006 \u0003לא קדשה\u0004 \u0005[תתקדש]\u0006 אותה שדה כאשר יחזור ויקחנה? משמע שאדם יכול להקדיש לאחר זמן, לעתיד, דבר שעתה אינו יכול להקדישו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' ירמיה: מי דמי\u0004 \u0005[האם\u0006 הדבר \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 בענין השדה, כיון שהשדה שהוא מוכר, הוא עדיין שלו בזמן המכירה, ו\u0003בידו להקדישה\u0004 כעת, לכן יכול להחיל עליו קדושה גם לאחר זמן. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 הלא \u0003אין בידה לגרש את עצמה,\u0004 ואין אפשרות להקדיש עכשיו את מעשי ידיה, וכיון שאין בידה לעשות כן \u0003הא לא דמיא\u0004 \u0005[זו אינה דומה]\u0006 \u0003אלא\u0004 למקרה אחר, \u0003לאומר לחבירו \"שדה זו שמכרתי לך\u0004 כבר, \u0003לכשאקחנה\u0004 (אקנה אותה) \u0003ממך — תיקדש\".\u0004 שבמקרה כזה \u0003לא קדשה,\u0004 משום שעכשיו כשאומר זאת אין השדה שלו, ואינו יכול להקדיש דבר שלא בא לעולם.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: מי דמי\u0004 \u0005[האם\u0006 הענין הזה שאמר ר' ירמיה \u0005דומה]?\u0006 \u0003התם, גופא\u0004 \u0005[שם גוף\u0006 השדה עצמו\u0005]\u0006 \u0003ו\u0004גם ה\u0003פירות בידא דלוקח\u0004 \u0005[בידי הקונה]\u0006 ולכן איננו יכול להקדיש, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003גופה בידה הוא\u0004 ויש לה בעלות על ידיה, \u0003הא לא דמיא\u0004 \u0005[זו אינו דומה]\u0006 \u0003אלא לאומר לחבירו\u0004"],["\u0003\"שדה זו שמשכנתי לך\u0004 ואתה אוכל את פירותיה, \u0003לכשאפדנה ממך — תיקדש\", דקדשה\u0004 \u0005[שהתקדשה].\u0006 משום שגוף השדה לא עבר ליד אחרת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: מי דמי\u0004 \u0005[האם\u0006 השוואה זו \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 כאשר הוא ממשכן את השדה, הלא \u0003בידו לפדותה,\u0004 ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 האשה המקדישה \u0003אין בידה לגרש עצמה! הא לא דמיא\u0004 \u0005[זו אינה דומה]\u0006 \u0003אלא לאומר לחבירו \"שדה זו שמשכנתי לך לעשר שנים לכשאפדנה ממך — תיקדש\", דקדשה\u0004 \u0005[שמקודשת].\u0006 ואף כאן, למרות שמעשה ידיה הם של הבעל, אולם כאשר מתגרשת הריהם שלה, וכיון שגוף הידיים תמיד היו שלה — יכולה להקדיש את מעשה ידיה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003ל\u0004אחר \u0003עשר שנים מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003בידו לפדותה,\u0004 שיש לזה זמן קצוב, ואפשר לומר שהדבר הוא בידיו, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 באשה, הלא \u0003אין בידה לגרש\u0004 את \u0003עצמה לעולם,\u0004 ואם כן אין לה שליטה כלל על מעשה ידיה, ואין לנו דוגמא לדבר.","\u0003אלא,\u0004 יש לחזור ולדחות בדרך אחרת את הראיה מקונמות. \u0003אמר רב אשי: קונמות קא אמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003קונמות\u0004 שכעין \u0003קדושת הגוף נינהו\u0004 \u0005[הם],\u0006 שעל ידי הקונם הרי זה כאילו חלה קדושה על דבר מסויים והוא מפקיע את השעבוד. \u0003וכ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא:\u0004 כוח \u0003הקדש,\u0004 וכן איסור \u0003חמץ, ו\u0004כן \u0003שחרור\u0004 של עבד — \u0003מפקיעין מידי שיעבוד.\u0004 שגם אם היו כל אלה משועבדים לאדם אחר, מכל מקום אם מקדישם, או בא חג הפסח ונאסר החמץ המשועבד, או משתחרר עבד המשועבד לאחר — מעשים אלה מועילים להפקיע מהם את שעבודם. ומשום שהקונם הוא כעין הקדש הריהו חל על חפץ אף שאינו נמצא בזמן שנאסר ברשות בעליו, שהוא משועבד לאחרים.","ומקשים: אם כן, שהקונם מפקיע מן השעבוד — \u0003ונקדשו מהשתא\u0004 \u0005[ושיתקדשו\u0006 מעשה הידיים \u0005מעכשיו]\u0006 עוד לפני שגירש אותה בשל כוח הקונם להפקיע את השעבוד שלהם לבעל? ומשיבים: \u0003אלמוה רבנן לשיעבודיה\u0004 \u0005[חיזקו חכמים את שיעבודו]\u0006 של ה\u0003בעל\u0004 בעודה נשואה לו יותר משאר שעבודים, \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תיקדש מהשתא\u0004 \u0005[תתקדש מעכשיו].\u0006 אבל כיון שבעיקרו של דבר יש כוח בקונם לחול גם על דברים משועבדים, לכן חל הקונם על מעשה ידיה לאחר שהיא יוצאת מרשות בעלה.","\u0003ואלו\u0004 ה\u0003מלאכות שהאשה עושה לבעלה: טוחנת, ואופה, ומכבסת, מבשלת, ומניקה את בנה, מצעת לו המטה, ועושה\u0004 עבודה גם \u0003בצמר\u0004 (בטוויית צמר). אם \u0003הכניסה לו שפחה אחת\u0004 — הרי הכנסה זו היא כנגד חלק מעבודתה, ומשום כך היא \u0003לא טוחנת ולא אופה ולא מכבסת.\u0004 הכניסה לו \u0003שתים\u0004 (שתי שפחות) — \u0003אין מבשלת, ואין מניקה את בנה,\u0004 אלא נותנת אותו למינקת. הכניסה לו \u0003שלש\u0004 שפחות — \u0003אין מצעת לו המטה, ואין עושה בצמר.\u0004 הכניסה לו \u0003ארבע\u0004 שפחות — \u0003יושבת בקתדרא.\u0004 כלומר, יכולה לשבת על כסא כמלכה, ולא לעשות דבר, משום שהשפחות עושות את הכל.","\u0003ר' אליעזר אומר: אפילו הכניסה לו מאה שפחות\u0004 בעלה \u0003כופה\u0004 (כופה אותה) \u0003לעשות\u0004 עבודה \u0003בצמר,\u0004 משום \u0003שהבטלה מביאה לידי זימה,\u0004 ולכן טוב לה לאשה שתעשה מלאכה כלשהי. \u0003רבן שמעון בן גמליאל אומר\u0004 יותר מכך: \u0003אף המדיר את אשתו מלעשות מלאכה — יוציא\u0004 (יגרש אותה) \u0003ויתן\u0004 לה \u0003כתובה.\u0004 ומדוע — \u0003שהבטלה מביאה לידי שיעמום\u0004 (שיגעון).","על לשון המשנה שואלים: \u0003טוחנת סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 הרי כרגיל הטחינה נעשית בריחיים גדולות המונעות על ידי מים או בעלי חיים והאשה עצמה אינה טוחנת! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003מטחנת.\u0004 כלומר, היא מביאה את החיטים לריחיים ודואגת לטחינתן. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003בריחיא דידא\u0004 \u0005[בריחיים של יד]\u0006 שהיא עצמה טוחנת.","ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' חייא, דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: אין אשה אלא ליופי, אין אשה אלא לבנים,\u0004 ולא לעשיית מלאכה. \u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003ר' חייא: אין אשה אלא לתכשיטי אשה. ותני\u0004 \u0005[ושנה]\u0006 \u0003ר' חייא: הרוצה שיעדן\u0004 (ייפה) \u0003את אשתו\u0004 — \u0003ילבישנה כלי פשתן. הרוצה שילבין את בתו\u0004 (שיהיה לה עור לבן) — \u0003יאכילנה אפרוחים, וישקנה חלב סמוך לפירקה\u0004 (לזמן בגרותה).","במשנה נמנה בין חיובי האשה ש \u0003מניקה את בנה.\u0004 ומציעים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004דברי \u0003בית שמאי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נדרה\u0004 האשה \u0003שלא להניק את בנה, בית שמאי אומרים:\u0004 כיון שנדרה — \u0003שומטת דד\u0004 (את השד) \u0003מפיו\u0004 ואינה מניקתו. \u0003בית הלל אומרים:\u0004 בעלה \u0003כופה\u0004 (כופה אותה), \u0003ומניקתו\u0004 בעל כרחה. אולם אם \u0003נתגרשה\u0004 ושוב אין לה חיוב כלפי בעלה — \u0003אינו כופה. ואם היה\u0004 התינוק \u0003מכירה\u0004 — הרי גם לאחר גירושין \u0003נותן לה\u0004 הבעל \u0003שכרה\u0004 כמינקת \u0003וכופה, ומניקתו מפני הסכנה.\u0004 שמא לא ירצה הילד לינוק מאשה אחרת, ויסתכן. ולענייננו נלמד מברייתא זו שלדעת בית שמאי אין חובה על האשה להניק את בנה, שהרי על ידי נדר מפקיעה עצמה מחיוב זה.","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו גם כדעת \u0003בית שמאי, הכא\u0004 \u0005[כאן]\u0006 בברייתא שהבאנו \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 \u0003כגון שנדרה היא\u0004 נדר זה, \u0003וקיים לה הוא,\u0004 הבעל, את הנדר. \u0003וקסברי\u0004 \u0005[וסבורים]\u0006 \u0003בית שמאי\u0004 כי במקרה כזה תלויה האשמה בבעל וכאילו ש\u0003הוא נותן אצבע בין שיניה,\u0004 והיא \"הנושכת את האצבע\", שבמקרה זה האשמה מוטלת עליו. ולכן כיון שלא הפר את נדרה — בטל ממנה החיוב להניק. \u0003ו\u0004אילו \u0003בית הלל סברי\u0004 \u0005[סבורים]\u0006 שבמקרה כזה אנו מניחים שהיא האשמה וכאילו ש\u0003היא נתנה אצבע בין שיניה\u0004 ונשכתה. ולכן אף שהוא קיים את נדרה מכל מקום האחריות מוטלת עליה, ומשום כך לא בטלה התחייבותה.","ומקשים: אם כן, שמחלוקת זו היא בשאלה על מי חלה האחריות כאשר האשה נודרת ובעלה מקיים, \u0003ונפלגו\u0004 \u0005[ושיחלקו]\u0006 \u0003בכתובה בעלמא\u0004 \u0005[בכלל],\u0006 כגון באשה שנדרה הנאה מבעלה והוא קיים לה את נדרה, האם תחול עליו החובה לתת לה כתובה, או לא. \u0003ועוד:\u0004 הלא \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003בית שמאי אומרים\u0004 במפורש לגבי כל הנשים (ולא דווקא לנודרות): \u0003אינה מניקה\u0004 אם אינה רוצה בכך! \u0003אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003בית שמאי\u0004 היא.","בברייתא שהובאה כאן שנינו ש\u0003אם היה\u0004 התינוק \u0003מכירה,\u0004 את האם, יכול הבעל לכפותה שתמשיך ותניק אותו גם לאחר שנתגרשה, אלא שצריך לשלם לה עבור ההנקה."],["\u0003עד כמה?\u0004 בן כמה צריך להיות תינוק שנוכל להניח שהוא כבר מכיר את אמו? \u0003אמר רבא אמר רב ירמיה בר אבא אמר רב:\u0004 מבן \u0003שלשה חדשים, ושמואל אמר:\u0004 מבן \u0003שלשים יום. ור' יצחק אמר\u0004 בשם \u0003ר' יוחנן:\u0004 מבן \u0003חמשים יום. אמר רב שימי בר אביי: הלכה כר' יצחק\u0004 ש\u0003אמר משום\u0004 (בשם) \u0003ר' יוחנן.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רב ור' יוחנן\u0004 שנחלקו בהבדל בין חמישים יום לשלושה חודשים — אפשר לומר ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מן התינוקות \u0003כי חורפיה\u0004 \u0005[לפי חריפותו],\u0006 שיש תינוק מפותח יותר שמכיר את אמו בחמישים יום, ויש תינוק שמכיר בשלושה חודשים. \u0003אלא לשמואל, כי האי גוונא מי משכחת לה\u0004 \u0005[כגון זה האם אתה מוצא אותה]\u0006 שתינוק בן חודש כבר יכיר את אמו?","ואכן מספרים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רמי בר יחזקאל\u0004 מארץ ישראל לבבל, \u0003אמר: לא תציתינהו להני כללי דכייל\u0004 \u0005[אל תקשיבו,\u0006 תקבלו, \u0005לאותם כללים שכלל]\u0006 \u0003יהודה אחי משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל,\u0004 כי שמואל לא קבע זמן מסויים לדבר זה. אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: כל זמן שמכירה.\u0004 שאין לדבר שיעור זמן קבוע, אלא יש לבדוק בכל תינוק אם הוא מכיר את אמו.","ומסופר: \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006גרושה \u0005אחת שבאה לפני]\u0006 \u0003שמואל,\u0004 שלא רצתה להניק את בנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל \u0003לרב דימי בר יוסף: זיל בדקה\u0004 \u0005[לך בדוק אותה],\u0006 כלומר, בדוק האם התינוק מכיר את אמו. \u0003אזל אותבה בדרי דנשי\u0004 \u0005[הלך הושיב\u0006 את \u0005אותה\u0006 אשה \u0005בשורה של נשים],\u0006 \u0003ושקליה לברה וקמהדר ליה עלייהו\u0004 \u0005[ולקח את בנה\u0006 בידיו \u0005והחזיר אותו עליהן]\u0006 לראות כיצד יגיב התינוק. \u0003כי מטא לגבה, הות קא מסוי לאפה\u0004 \u0005[כאשר הגיע\u0006 התינוק \u0005אליה,\u0006 אל אמו, \u0005היה מסתכל בפניה]\u0006 \u0003כבשתנהי לעינה מיניה\u0004 \u0005[כבשה את עיניה ממנו],\u0006 שלא רצתה להביט בו. \u0003אמר לה: נטף\u0004 \u0005[הרימי]\u0006 את \u0003עיניך, קום דרי בריך\u0004 \u0005[קחי, שאי,\u0006 את \u0005בנך]\u0006 שהרי ניכר שהוא מכיר אותך. ושואלים: \u0003סומא מנא ידע\u0004 \u0005[\u0006תינוק \u0005עיוור מניין הוא יודע]\u0006 ומכיר באמו? \u0003אמר רב אשי: בריחא ובטעמא\u0004 \u0005[בריח ובטעם]\u0006 של החלב.","כיון שדנו כאן בזמן יניקת התינוק, דנים בכמה צדדים אחרים של הדבר. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יונק תינוק והולך\u0004 (וממשיך) משדי אמו \u0003עד עשרים וארבעה חדש, מכאן ואילך\u0004 — הרי זה \u0003כיונק שקץ,\u0004 שלא התירו לו לשתות חלב של אשה, אלו \u0003דברי ר' אליעזר. ר' יהושע אומר:\u0004 אינו כן, אלא אם הוא ממשיך לינוק — \u0003אפילו ארבע וחמש שנים\u0004 מותר לו. אבל אם \u0003פירש\u0004 (הפסיק לינוק) \u0003לאחר עשרים וארבעה חדש, וחזר\u0004 לינוק — אז דינו \u0003כיונק שקץ.\u0004 ודנים בברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מכאן ואילך כיונק שקץ,\u0004 ומשמע שחלב אדם אסור. \u0003ורמינהי\u0004 \u0005[ומקשים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003יכול יהא חלב מהלכי שתים,\u0004 כלומר, חלב אדם, \u0003טמא\u0004 ואסור באכילה כדין בהמות טמאות. \u0003ו\u0004לכאורה \u0003דין\u0004 (קל וחומר) \u0003הוא: ומה בהמה\u0004 טמאה \u0003שהקלת במגעה\u0004 שאין בה טומאת מגע בחייה — \u0003החמרת בחלבה,\u0004 שאסור לשתות חלב בהמה טמאה, \u0003אדם שהחמרת במגעו,\u0004 שיש בו דיני טומאה אף בחייו (וכגון טומאת נידה) — \u0003אינו דין שתחמיר בחלבו\u0004 שיהא אסור משום טומאה?","\u0003תלמוד לומר: \"את הגמל כי מעלה גרה הוא\u0004 ופרסה איננו מפריס טמא הוא לכם\u0003\"\u0004 (ויקרא יא, ד), וההדגשה \"הוא\" באה לומר: \u0003הוא\u0004 בלבד \u0003טמא, ואין חלב מהלכי שתים טמא, אלא טהור.\u0004 ועוד: \u0003יכול אוציא\u0004 דווקא \u0003את החלב\u0004 של אדם מכלל איסור אכילה, \u0003שאינו שוה בכל\u0004 שהרי החלב מצוי רק בנשים, אבל \u0003ולא אוציא את הדם\u0004 של אדם \u0003שהוא שוה בכל,\u0004 ויהיה אסור דם של אדם באכילה — \u0003תלמוד לומר\u0004 מן ההדגשה \u0003\"הוא\"\u0004 האמור בגמל, לומר: \u0003הוא טמא ואין דם מהלכי שתים טמא, אלא טהור.\u0004","\u0003ואמר רב ששת:\u0004 עד כדי כך אין איסור בחלב אשה, ש\u0003אפילו מצות פרישה\u0004 מדברי סופרים \u0003אין בו.\u0004 ואם כן מדוע אומרים שהתינוק נחשב כיונק שקץ?","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שאין בו איסור, הרי זה דווקא באופן \u0003דפריש\u0004 \u0005[ש\u0006כבר \u0005פרש\u0006 ממנה\u0005],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרו שהוא אסור, הרי זה באופן \u0003דלא פריש\u0004 \u0005[ש\u0006עדיין \u0005לא פרש],\u0006 שכל עוד החלב בשדי האשה יש בו איסור מדברי חכמים. ונחשב כיונק שקץ.","\u0003וחלופא\u0004 \u0005[וחילופו\u0006 של דבר\u0005]\u0006 \u0003בדם.\u0004 שדם אדם שפרש אסור מדברי סופרים, אבל אם לא פרש — אין בו איסור. \u0003כדתניא\u0004 \u0005[\u0006ו\u0005כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003דם\u0004 אדם \u0003ש\u0004היה \u0003על גבי ככר — גוררו,\u0004 מגרד את הדם מן המקום, \u0003ואוכלו,\u0004 את הככר. שכיון שפירש אסור לאוכלו מדברי סופרים עד שיגרור, אבל דם \u0003ש\u0004היה \u0003בין השינים\u0004 של אדם — \u0003מוצצו, ואינו חושש,\u0004 שאין בדם זה איסור אכילה כלל כל זמן שלא פירש.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003ר' יהושע אומר אפילו\u0004 בן \u0003ארבע וחמש שנים\u0004 רשאי לינוק. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת, \u0003ר' יהושע אומר: אפילו\u0004 הוא גדול כל כך עד ש\u0003חבילתו על כתיפיו,\u0004 עדיין יכול להמשיך לינוק, ומשמע שהוא יותר מבן ארבע וחמש שנים! ומשיבים: אין זו סתירה, \u0003אידי ואידי חד שיעורא\u0004 \u0005[זה וזה שיעור אחד]\u0006 \u0003הוא\u0004 ואין ההבדל אלא בלשון. \u0003אמר רב יוסף: הלכה כר' יהושע.\u0004","ובנושא דומה \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' מרינוס אומר:\u0004 אדם שהיה \u0003גונח\u0004 (משתעל) וצריך לרפואתו חלב, ואין לו חלב מוכן — \u0003יונק חלב\u0004 מבהמה \u0003בשבת,\u0004 אף על פי שאסור לחלוב בהמה בשבת. \u0003מאי טעמא\u0004 \u0005[ומה טעם] —\u0006 פעולת ה\u0003יונק\u0004 נחשבת רק כ\u0003מפרק כלאחר יד.\u0004 שאמנם מלאכת החליבה היא תולדה של מלאכת \"מפרק\" (\"דש\") שהגדרתה היא שמוציא את התוך הנאכל מתוך מעטה שאינו נאכל, אבל זה דווקא בחליבה שאז נעשית מלאכה זו כדרכה, אבל היונק חלב מבהמה עושה אמנם מלאכה של מפרק אך לא כדרך עשייתה, אלא כמי שעושה מעשה באחורי ידו, ואין מלאכה כזו אסורה אלא מדברי סופרים, \u0003ובמקום צערא\u0004 \u0005[צער,\u0006 כאב\u0005],\u0006 כמו במקרה של גונח, \u0003לא גזרו רבנן\u0004 \u0005[חכמים].\u0006 \u0003אמר רב יוסף: הלכה כר' מרינוס.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 שכתוב בה כעין אותה הלכה שהזכרנו, \u0003נחום איש גליא אומר: צינור שעלו בו קשקשין\u0004 (קש ועשבים) המעכבים את זרימת המים בתוכו — \u0003ממעכן ברגלו בצנעא בשבת, ואינו חושש\u0004 משום מלאכת מתקן כלי. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההיתר — מלאכה זו שעושה \u0003מתקן כלאחר יד הוא,\u0004 שהרי אין דרך תיקון אלא כשעושה זאת בידו או בכלי, וכשעושה אותה ברגל היא נחשבת כמלאכה הנעשית שלא כדרכה, ואינה אסורה אלא מגזירת חכמים, \u0003ובמקום פסידא\u0004 \u0005[הפסד]\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים].\u0006 \u0003אמר רב יוסף: הלכה כנחום איש גליא.\u0004","ועוד לענין הברייתא שדנו בה: נאמר שאם \u0003פירש\u0004 התינוק מלינוק \u0003לאחר עשרים וארבעה חדש וחזר\u0004 — הרי הוא \u0003כיונק שקץ.\u0004 ושואלים: \u0003וכמה\u0004 זמן של פרישה? \u0003אמר רב יהודה בר חביבא אמר שמואל: שלשה ימים. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, שלא היתה זו מימרה של אמורא אלא ברייתא, ש\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יהודה בר חביבא קמיה\u0004 \u0005[לפני]\u0006 \u0003שמואל\u0004 ברייתא זו: שהזמן הוא \u0003שלשה ימים.\u0004","ומכאן באים לדון בהלכות אחרות הקשורות ביניקה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אשה \u0003מינקת שמת בעלה בתוך עשרים וארבעה חדש\u0004 ללידת הילד — \u0003הרי זו לא תתארס ולא תינשא,\u0004"],["\u0003עד עשרים וארבעה חדש\u0004 מיום שהתינוק נולד. שאם תינשא עלולה היא להתעבר, ולא תוכל להניק עוד, אלו \u0003דברי ר' מאיר. ור' יהודה מתיר בשמונה עשר חדש. אמר ר' נתן בר יוסף: הן הן דברי בית שמאי, הן הן דברי בית הלל.\u0004 כלומר, מחלוקת זו היא מחלוקת עתיקה, \u0003שבית שמאי אומרים: עשרים וארבעה חדש, ובית הלל אומרים: שמונה עשר חדש.\u0004","\u0003אמר רבן שמעון בן גמליאל: אני אכריע. לדברי האומר עשרים וארבעה חדש — מותרת לינשא בעשרים ואחד חדש,\u0004 משום שעד שלושה חדשים אפילו אם תתעבר לא ימנע העיבור מלהניק. \u0003לדברי האומר בשמונה עשר חדש — מותרת להנשא בחמשה עשר חדש.\u0004 וטעמו — \u0003לפי שאין החלב נעכר\u0004 על ידי ההריון \u0003אלא לאחר שלשה חדשים.\u0004","\u0003אמר עולא: הלכה כר' יהודה\u0004 שדי בשמונה עשר חודש. \u0003ואמר מר עוקבא: לי התיר ר' חנינא לשאת\u0004 אשה מינקת \u0003לאחר חמשה עשר חדש\u0004 וכשיטת ר' יהודה לדברי רבן שמעון בן גמליאל. מסופר: \u0003אריסיה\u0004 \u0005[אריסו]\u0006 של \u0003אביי אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003אביי\u0004 לשאול, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהו ליארס\u0004 עם אשה שמניקה את בנה והוא בן \u0003חמשה עשר חדש? אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003חדא\u0004 \u0005[\u0006טעם \u0005אחד]\u0006 שמותר משום שבמחלוקת \u0003ר' מאיר\u0004 ו\u0003ר' יהודה — הלכה כר' יהודה. ועוד,\u0004 הלא זו מחלוקת ראשונים, \u0003בית שמאי ובית הלל,\u0004 ובמקרה כזה \u0003הלכה כבית הלל. ו\u0004עוד, הרי \u0003אמר עולא: הלכה כר' יהודה, ו\u0004כן \u0003אמר מר עוקבא: לי התיר ר' חנינא לשאת לאחר חמשה עשר חדש, כל שכן\u0004 שלך מותר \u0003דאת ליארס\u0004 \u0005[שאתה\u0006 בא רק \u0005לארס\u0006 אשה\u0005]\u0006 ולא לשאת אותה.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 אביי \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב יוסף, אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף בענין זה: \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003צריכה להמתין עשרים וארבעה חדש\u0004 ואפילו מלהתארס, וחודשים אלו נמנים \u0003חוץ מיום שנולד בו וחוץ מיום שנתארסה בו.\u0004 כיון ששמע אביי כך \u0003רהט בתריה תלתא פרסי\u0004 \u0005[רץ אחריו,\u0006 אחרי אותו אריס, \u0005שלוש פרסות]\u0006 \u0003ואמרי לה פרסא בחלא\u0004 \u0005[ויש אומרים\u0006 שרץ אחריו \u0005פרסה\u0006 בתוך \u0005חול]\u0006 שרצה להזכירו שלא יסמוך על ההיתר, אלא כפי שאמרו רב ושמואל שהדבר אסור, \u0003ולא אדרכיה\u0004 \u0005[השיג אותו].\u0006","\u0003אמר אביי\u0004 שלמד מתוך מעשה זה: \u0003האי מילתא דאמור רבנן\u0004 \u0005[דבר זה שאמרו חכמים]\u0006 \u0003אפילו\u0004 לאכול \u0003ביעתא בכותחא\u0004 \u0005[ביצה בכותח]\u0006 שיש בו מעט חלב \u0003לא לישרי איניש\u0004 \u0005[יתיר אדם]\u0006 \u0003במקום רביה\u0004 \u0005[במקום רבו],\u0006 שאף שלכאורה היא שאלה פשוטה מאד, שאין הביצה נחשבת כבשר, ומותר לאוכלה עם חלב, ואין בה שום צדדים של חומרה — בכל זאת לא יפסוק אדם הלכה זו במקום רבו. ואמר אביי שהטעם \u0003לא משום דמיחזי כאפקירותא\u0004 \u0005[שנראה כחוצפה]\u0006 שמורה הלכה במקום רבו, שהרי הוא דבר פשוט שאין צורך בו בידיעה מרובה של ההלכה, \u0003אלא משום\u0004 ש\u0003לא מסתייעא מילתא למימרא\u0004 \u0005[מסתייע הדבר לומר]\u0006 דבר הלכה לאמיתו. \u0003דהא אנא הוה גמירנא ליה להא\u0004 \u0005[שהרי אני למדתי את\u0006 ההלכה \u0005הזו]\u0006 של \u0003רב ושמואל\u0004 ו\u0003אפילו הכי לא מסתייעא\u0004 \u0005[הסתייע]\u0006 \u0003לי מילתא\u0004 \u0005[הדבר]\u0006 \u0003למימר\u0004 \u0005[לומר]\u0006 אותו כראוי, מפני שפסק במקום רבו רב יוסף, ופסק בטעות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003נתנה בנה למינקת\u0004 בתוך הזמן, \u0003או גמלתו\u0004 מלינוק, \u0003או מת — מותרת לינשא מיד.\u0004 מסופר: \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע סבור למיעבד עובדא כי הא מתניתא\u0004 \u0005[חשבו לעשות מעשה כמו ברייתא זו].\u0006 \u0003אמרה להו\u0004 \u0005[להם]\u0006 \u0003ההיא סבתא\u0004 \u0005[זקנה אחת]:\u0006 \u0003בדידי הוה עובדא\u0004 \u0005[בי היה מעשה]\u0006 בשאלה כגון זו, \u0003ואסר לי רב נחמן.\u0004","ותוהים: \u0003איני\u0004 \u0005[וכן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב נחמן שרא להו לבי ריש גלותא\u0004 \u0005[התיר להם ל\u0006בני בית \u0005ראש הגולה]\u0006 בכגון זה! ומשיבים: \u0003שאני בי ריש גלותא דלא הדר בהו\u0004 \u0005[שונים\u0006 בני \u0005בית ראש הגולה, שאין\u0006 המניקות \u0005חוזרות בהן],\u0006 שאם נתנה אחת מהנשים הללו את הילד למינקת — ודאי לא תחזור בה המינקת מפני מורא ראש הגולה, מה שאין כן באדם אחר, שמא יימצא התינוק בלא מינקת כלל.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפי\u0004 לרב פפא ורב הונא בנו של רב יהושע: \u0003ואתון לא תסברוה\u0004 \u0005[ואתם אינכם סבורים כך]\u0006 לאסור, ומנין — \u0003מהא דתניא\u0004 \u0005[מזו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיתה\u0004 האשה \u0003רדופה\u0004 (רגילה ונוהגת) \u0003לילך לבית אביה\u0004 ושהתה שם זמן מרובה, \u0003או שהיה לה כעס בבית בעלה\u0004 ולא היתה עמו, \u0003או שהיה בעלה חבוש בבית האסורין, או שהלך בעלה למדינת הים, או שהיה בעלה זקן, או חולה, או שהיתה\u0004 היא \u0003עקרה\u0004 או \u0003זקנה\u0004 או \u0003איילונית\u0004 או \u0003קטנה, ו\u0004כן \u0003המפלת אחר מיתת בעלה, ושאינה ראויה לילד\u0004 מאיזה טעם אחר — אף על פי שבכל אלה אין לחשוש שהן מעוברות — \u0003כולן צריכות להמתין\u0004 לפחות \u0003שלשה חדשים,\u0004 שאמרו חכמים שלא תינשא אשה אלא אחר שלושה חדשים למות בעלה, כדי שלא יווצר ספק בן מי הוא הילד הנולד לה, וגזרו שלא לחלק בין אשה ואשה, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יוסי מתיר ליארס ולינשא מיד\u0004 בכל המקרים הללו, משום שאין לחשוש בהם להריון. \u0003ואמר רב נחמן אמר שמואל: הלכה כר' מאיר בגזירותיו,\u0004 שבכל מקום שגזר ר' מאיר להחמיר כדי שלא יבואו לידי טעות — הלכה כמותו. ואף כאן במינקת יש לומר שלא חילקו חכמים בין מקרה למקרה, ולא תינשא בכל אופן שהוא.","\u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003לאו אדעתין\u0004 \u0005[לא\u0006 היה הדבר \u0005בדעתנו],\u0006 כלומר, שכחנו דבר זה. \u0003והלכתא\u0004 \u0005[והלכה]\u0006 לסיכום הדברים: אם \u0003מת\u0004 הילד — \u0003מותר\u0004 לאשה להינשא מיד, ואם \u0003גמלתו\u0004 (מהנקה) — \u0003אסור,\u0004 שיש לחשוש שמא תגמלנו בעל כרחו לפני זמנו. \u0003מר בר רב אשי אמר: אפילו מת נמי\u0004 \u0005[גם כן]\u0006 \u0003אסור.\u0004 שאם תתיר במקרה שמת התינוק יש לחשוש \u0003דלמא קטלה ליה ואזלא ומינסבא\u0004 \u0005[שמא תהרוג אותו\u0006 לשם כך \u0005ותלך ותתחתן].\u0006 ומספרים: אכן \u0003הוה עובדא וחנקתיה\u0004 \u0005[היה מעשה וחנקה אותו]\u0006 את הילד לשם כך. ומסכמים להלכה: \u0003ולא היא,\u0004 אין ללמוד מכאן, כי האישה \u0003ההיא שוטה הואי\u0004 \u0005[היתה],\u0006 \u0003דלא עבדי נשי דחנקן בנייהו\u0004 \u0005[שאין נשים עשויות לחנוק\u0006 את \u0005בניהן],\u0006 ואין לחשוש לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרי שנתנו לה\u0004 לאשה מינקת \u0003בן להניק\u0004 בשכר — \u0003הרי זו לא תניק עמו לא\u0004 את \u0003בנה, ולא\u0004 את \u0003בן חברתה,\u0004 שלא יתמעט החלב לתינוק שנשכרה להניקו. \u0003פסקה קימעא,\u0004 אם הסכימה לקבל בשכר הנקה מזונות מעטים — \u0003אוכלת הרבה\u0004 כדי שיהיה לה מספיק חלב, ו\u0003לא תאכל עמו,\u0004 כלומר, בזמן שהיא מניקה אותו, \u0003דברים הרעים\u0004 והמזיקים \u0003לחלב.\u0004","ומבררים את פרטי ברייתא זו: \u0003השתא\u0004 \u0005[עכשיו],\u0006 הרי, שתניק את \u0003בנה\u0004 עם הילד \u0003אמרת\u0004 ש\u0003לא, בן חברתה מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאין מניקה אותו כשנשכרה להניק?! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003בנה הוא דחייס עילויה\u0004 \u0005[ש\u0006היא \u0005חסה עליו]\u0006 ולכן \u0003ממציא ליה טפי\u0004 \u0005[מוציאה לו יותר]\u0006 חלב מהשני. לכן לא תניק בנה אתו, \u0003אבל בן חברתה, אי לאו דהוה\u0004 \u0005[אם לא שהיה]\u0006 \u0003לה מותר\u0004 \u0005[\u0006חלב \u0005מיותר]\u0006 \u0003לא הוה ממציא ליה\u0004 \u0005[היתה מוציאה לו\u0006 יותר\u0005],\u0006 ולפיכך אולי מותר לה להניקו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לחלק בדבר.","אמרנו ש\u0003פסקה קימעא,\u0004 כלומר, שפסקו לה מזונות בשכר ההנקה — \u0003אוכלת הרבה.\u0004 ושואלים: \u0003מהיכא\u0004 \u0005[מהיכן]\u0006 משל מי? \u0003אמר רב ששת: משלה.\u0004 שהרי התחייבה להניק אותו, והיא צריכה לדאוג לכך.","שנינו שם: \u0003לא תאכל עמו דברים הרעים.\u0004 ושואלים: \u0003מאי נינהו\u0004 \u0005[מה הם]\u0006 הדברים הרעים לחלב? \u0003אמר רב כהנא: כגון כשות וחזיז\u0004 (נבטי תבואה) \u0003ודגים קטנים, ואדמה. אביי אמר: אפילו קרא וחבושא\u0004 \u0005[דלעת וחבוש].\u0006 \u0003רב פפא אמר: אפילו קרא וכופרא\u0004 \u0005[דלעת וענפי דקל].\u0006 \u0003רב אשי אמר: אפילו כמכא והרסנא\u0004 \u0005[כותח ודגים קטנים],\u0006 כי מכל אלה \u0003מינייהו פסקי חלבא, מינייהו עכרי חלבא\u0004 \u0005[מהם\u0006 ה\u0005מפסיקים את החלב, מהם\u0006 ה\u0005עוכרים את החלב].\u0006","ומאחר שנגענו בדברים אלה, מביאים עוד כמה דברים לגבי התוצאות העלולות לבוא לוולדות מחמת התנהגות האם: \u0003דמשמשא בי ריחיא\u0004 \u0005[\u0006מי \u0005שמשמשת,\u0006 מזדווגת, ב\u0005בית הריחיים] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני נכפי\u0004 \u0005[בנים נכפים,\u0006 חולים במחלת נפילה\u0005].\u0006 \u0003דמשמשא\u0004 \u0005[\u0006מי \u0005שמשמשת]\u0006 \u0003על ארעא\u0004 \u0005[הארץ\u0006 הקרקע\u0005] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני שמוטי\u0004 \u0005[בנים ארוכי צוואר].\u0006 \u0003דדרכא\u0004 \u0005[\u0006זו \u0005הדורכת]\u0006 \u0003על רמא דחמרא\u0004 \u0005[גללי חמור]\u0006 בזמן ההריון — \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני גירדני\u0004 \u0005[בנים קרחים].\u0006 \u0003דאכלה חרדלא\u0004 \u0005[האוכלת חרדל]\u0006 בזמן ההריון — \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני זלזלני\u0004 \u0005[בנים זוללים].\u0006 \u0003דאכלה תחלי\u0004 \u0005[האוכלת שחלים] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני דולפני\u0004 \u0005[בנים זולגי דמעה].\u0006 \u0003דאכלה מוניני\u0004 \u0005[האוכלת ציר דגים] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני מציצי עינא\u0004 \u0005[בנים מניעי עיניים].\u0006 \u0003דאכלה גרגושתא\u0004 \u0005[האוכלת אדמה] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני מכוערי\u0004 \u0005[בנים מכוערים].\u0006 \u0003דשתיא שיכרא\u0004 \u0005[השותה שיכר] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני אוכמי\u0004 \u0005[בנים שחורים].\u0006 \u0003דאכלה בישרא ושתיא חמרא\u0004 \u0005[האוכלת בשר ושותה יין]\u0006 בזמן ההריון — \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני\u0004 \u0005[בנים]\u0006"],["\u0003בריי\u0004 \u0005[בריאים].\u0006 \u0003דאכלה ביעי\u0004 \u0005[שאוכלת ביצים]\u0006 בזמן הריונה — \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני עינני\u0004 \u0005[בנים בעלי עיניים\u0006 גדולות\u0005].\u0006 \u0003דאכלה כוורי\u0004 \u0005[שאוכלת דגים] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני חינני\u0004 \u0005[בנים חינניים,\u0006 בעלי חן\u0005].\u0006 \u0003דאכלה כרפסא\u0004 \u0005[שאוכלת כרפס] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני זיותני\u0004 \u0005[בנים יפים,\u0006 בעלי זיו\u0005].\u0006 ועוד: \u0003דאכלה כוסברתא\u0004 \u0005[שאוכלת כוסבר] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני בישרני\u0004 \u0005[בנים בעלי בשר,\u0006 שמנים\u0005].\u0006 \u0003דאכלה אתרוגא\u0004 \u0005[שאוכלת אתרוג] —\u0006 \u0003הוו\u0004 \u0005[יהיו]\u0006 \u0003לה בני ריחני\u0004 \u0005[בנים ריחניים].\u0006 מסופר: \u0003ברתיה\u0004 \u0005[בתו]\u0006 של \u0003שבור מלכא\u0004 \u0005[המלך],\u0006 מלך פרס, \u0003אכלה בה אמה\u0004 בזמן ההריון \u0003אתרוגא\u0004 \u0005[אתרוג],\u0006 \u0003והוו מסקי לה לקמיה אבוה בריש ריחני\u0004 \u0005[והיו מעלים אותה לפני אביה בראש הבשמים]\u0006 משום שהיתה ריחנית כל כך.","ושוב לענין הלכה. \u0003אמר רב הונא: בדק\u0004 (שאל) \u0003לן\u0004 \u0005[אותנו]\u0006 \u0003רב הונא בר חיננא: היא,\u0004 האשה, אם הילד, \u0003אומרת\u0004 שרצונה \u0003להניק, והוא,\u0004 הבעל, \u0003אומר שלא להניק\u0004 אלא למסור את הילד למינקת — \u0003שומעין לה.\u0004 ומדוע — \u0003צערא דידה\u0004 \u0005[הצער שלה]\u0006 \u0003הוא\u0004 שסובלת מעודף החלב. \u0003הוא אומר להניק, והיא אומרת שלא להניק, מהו\u0004 הדין? ויש עוד לצמצם את השאלה: \u0003כל היכא\u0004 \u0005[מקום]\u0006 \u0003דלאו אורחה\u0004 \u0005[שאין\u0006 זו \u0005דרכה],\u0006 שבמשפחתה לא היו נשי הבית מניקות את בניהן אלא מוסרות אותם למיניקות — \u0003שומעין לה.\u0004 אולם אם \u0003היא אורחה\u0004 \u0005[דרכה]\u0006 להניק \u0003והוא לאו אורחיה\u0004 \u0005[לא דרכו],\u0006 כלומר, במשפחתו אין נוהגים כן, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 \u0003בתר דידיה אזלינן או בתר דידה אזלינן\u0004 \u0005[אחריו אנו הולכים או אחריה אנו הולכים]?\u0006","\u0003ופשיטנא ליה מהא\u0004 \u0005[ופתרנו לו\u0006 את הבעיה \u0005מזו]\u0006 ששנינו: אשה הנישאת לאיש \u0003עולה עמו,\u0004 למעמדו, ונוהגת כמשפחתו אם הוא יותר ממה שנהוג במשפחתה, \u0003ואינה יורדת עמו.\u0004 וכיון שבמשפחתו לא נהגו להניק, גם היא אינה חייבת בזה. \u0003אמר רב הונא: מאי קראה\u0004 \u0005[מה הכתוב]\u0006 המרמז על כך — \u0003\"והיא בעלת בעל\"\u0004 (בראשית כ, ג), ומפרשים: \"בעולת\" משמעו \u0003בעלייתו של בעל ולא בירידתו של בעל. ר' אלעזר אמר:\u0004 רמז לדבר \u0003מהכא\u0004 \u0005[מכאן],\u0006 מהנאמר בחוה \u0003\"כי הוא היתה אם כל חי\"\u0004 (בראשית ג, כ), לומר: \u0003לחיים ניתנה, ולא לצער ניתנה.\u0004","שנינו במשנה שאם \u0003הכניסה לו שפחה\u0004 אחת, אינה טוחנת ולא אופה ולא מכבסת. ומדייקים: \u0003הא שארא עבדא\u0004 \u0005[הרי\u0006 את \u0005שאר\u0006 העבודות, האשה \u0005עושה],\u0006 ושואלים: \u0003ותימא ליה\u0004 \u0005[ותאמר לו\u0006 האשה\u0005]:\u0006 \u0003עיילית\u0004 \u0005[הכנסתי]\u0006 \u0003לך,\u0004 הבאתי לך, \u0003איתתא בחריקאי\u0004 \u0005[אשה במקומי]\u0006 והיא עושה את כל המלאכות שאני צריכה לעשות! ומשיבים: \u0003משום\u0004 ש\u0003אמר\u0004 \u0005[ש\u0006הוא יכול \u0005לומר]\u0006 \u0003לה: הא טרחא לדידי ולדידה\u0004 \u0005[זו טורחת בשבילי ובשבילה\u0006 כמו אשה אחרת\u0005],\u0006 אולם \u0003קמי דידך מאן טרח\u0004 \u0005[לפניך מי יטרח]?\u0006 ואם כן יש צורך שתעבוד האשה מעט כדי לדאוג לצרכי עצמה.","שנינו במשנה שאם הביאה לו \u0003שתים\u0004 (שתי שפחות) \u0003אינה מבשלת ואינה מניקה.\u0004 ומדייקים: \u0003הא שארא עבדא\u0004 \u0005[הרי שאר\u0006 המלאכות היא \u0005עושה],\u0006 ושואלים: \u0003ותימא ליה\u0004 \u0005[ושתאמר לו\u0006 האשה\u0005]:\u0006 \u0003עיילית לך איתתא אחריתי דטרחה לדידי ולדידה, וחדא לדידך ולדידה\u0004 \u0005[הכנסתי,\u0006 הבאתי, \u0005לך אשה אחרת שטורחת בשבילי ובשבילה, ו\u0006עוד \u0005אחת\u0006 שטורחת \u0005בשבילך ובשבילה]\u0006 ואני איני צריכה עוד לעבוד! ומשיבים: \u0003משום דאמר\u0004 \u0005[ש\u0006הוא יכול \u0005לומר]\u0006 \u0003לה: קמי אורחי ופרחי מאן טרח\u0004 \u0005[לפני אורחים\u0006 מזדמנים, עוברי דרך, \u0005מי יטרח]?\u0006 ועדיין יש צורך במישהו, שיעשה את שאר העבודות.","שנינו במשנה שאם הביאה לו \u0003שלש\u0004 שפחות, \u0003אינה מצעת המטה.\u0004 ושואלים: \u0003הא שארא עבדא\u0004 \u0005[הרי\u0006 את \u0005השאר\u0006 היא \u0005עושה],\u0006 \u0003ותימא ליה\u0004 \u0005[ותאמר לו]:\u0006 \u0003עיילית לך אחריתי לאורחי ופרחי\u0004 \u0005[הכנסתי לך\u0006 עוד אשה \u0005אחרת\u0006 לטרוח \u0005ל\u0006פני \u0005אורחים ומזדמנים]\u0006 ואינני צריכה לעבוד עוד! ומשיבים: \u0003משום דאמר\u0004 \u0005[ש\u0006הוא יכול \u0005לומר]\u0006 \u0003לה: נפיש בני ביתא, נפיש אורחי ופרחי\u0004 \u0005[\u0006כש\u0005מתרבים בני הבית, מתרבים גם אורחים ומזדמנים]\u0006 ולכן יש צורך בעוד אדם שיעשה משהו.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו\u0004 הכניסה לו \u0003ארבע\u0004 שפחות \u0003נמי\u0004 \u0005[גם כן]\u0006 תצטרך לעבוד, שהרי יתרבו האורחים עוד יותר, ואילו במשנה אמרנו שבהכניסה ארבע שפחות אינה עושה דבר! ומשיבים: \u0003ארבע כיון דנפישי להו\u0004 \u0005[שרבות הן,\u0006 השפחות\u0005],\u0006 הרי הן \u0003מסייען אהדדי\u0004 \u0005[מסייעות זו לזו]\u0006 ומתוך כך הן עושות את כל העבודות הדרושות.","\u0003אמר רב חנא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' שמואל בר נחמני: לא\u0004 הכוונה ש\u0003הכניסה לו\u0004 שפחות \u0003ממש, אלא כיון שראויה להכניס,\u0004 שאם הביאה נדוניה בסכום כזה שאפשר לקנות בו שפחות, הדין כן \u0003אף על פי שלא הכניסה. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003אחד\u0004 הדין כ\u0003שהכניסה לו\u0004 שפחות בפועל, \u0003ואחד\u0004 הדין כ\u0003שצמצמה לו משלה\u0004 ועל ידי כך יש לבעל די כסף כדי להכניס שפחה לעבוד.","שנינו במשנה שאם היו \u0003ארבע\u0004 שפחות הרי האשה \u0003יושבת בקתדרא\u0004 (מושב כבוד) ואינה עושה דבר. \u0003אמר רב יצחק בר חנניא אמר רב הונא: אף על פי שאמרו\u0004 שהיא \u0003יושבת בקתדרא\u0004 ואינה צריכה לעבוד, \u0003אבל מוזגת לו כוס ומצעת לו את המטה ומרחצת לו פניו ידיו ורגליו.\u0004 שדברים אלה אינם כחובות של מלאכה, אלא הם דברים של חיבה שהאשה עושה לבעלה, ודבר זה אין מוסרים לשפחה.","והלכה דומה \u0003אמר רב יצחק בר חנניא אמר רב הונא: כל מלאכות שהאשה עושה לבעלה\u0004 גם כאשר היא \u0003נדה, עושה\u0004 האשה \u0003לבעלה\u0004 אף כאשר הכניסה לו הרבה שפחות, \u0003חוץ ממזיגת הכוס, והצעת המטה והרחצת פניו ידיו ורגליו,\u0004 שכפי שאמרנו אלה הן מלאכות של חיבה, ואם היא נדה אל תעשה זאת, שלא יבואו לידי קירבה יתירה.","שנינו שם שהנידה אסורה ב\u0003הצעת המטה\u0004 לבעלה. \u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 כן, \u0003אלא\u0004 כאשר היא מציעה את המיטה \u0003בפניו, אבל\u0004 כאשר היא מציעה את המיטה \u0003שלא בפניו — לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור. \u0003ו\u0004לגבי איסור \u0003מזיגת הכוס,\u0004 מעירים: \u0003שמואל מחלפא ליה דביתהו בידא דשמאלא\u0004 \u0005[היתה מחליפה לו אשתו\u0006 בזמן נידתה ומוזגת \u0005ביד שמאל],\u0006 שכיון שעושה שינוי כלשהו במזיגה, שם לב לכך, ואין חשש לקירבה יתירה. אשתו של \u0003אביי מנחא ליה\u0004 \u0005[היתה מניחה לו\u0006 בימי נידותה את הכוס \u0003אפומא דכובא\u0004 \u0005[על פי החבית],\u0006 אשתו של \u0003רבא\u0004 היתה מניחה לו \u0003אבי סדיא\u0004 \u0005[למראשותיו],\u0006 אשתו של \u0003רב פפא\u0004 היתה מניחה לו את הכוס \u0003אשרשיפא\u0004 \u0005[על הספסל]\u0006 לשם שינוי.","כיון שהוזכרו דברים שאמר רב יצחק בר חנניא, מביאים מדבריו בנושא אחר. \u0003אמר רב יצחק בר חנניא אמר רב הונא: הכל משהין בפני השמש,\u0004 שהמשמש בסעודה ממתין עד שיאכלו האחרים כל מאכל, ואחר כך הוא אוכל, \u0003חוץ מבשר ויין,\u0004 שהם מעוררים תיאבון יתר, ונגרם לו צער אם לא יאכל מהם יחד עם הסועדים. \u0003אמר רב חסדא:\u0004 הכוונה היא דווקא ל\u0003בשר שמן ויין ישן. אמר רבא: בשר שמן\u0004 — \u0003כל השנה כולה, יין ישן — בתקופת תמוז\u0004 דווקא, שבגלל החום ריחו של היין נודף ביותר.","\u0003אמר רב ענן בר תחליפא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003מר שמואל ואייתו ליה תבשילא דארדי\u0004 \u0005[והביאו לו תבשיל של פטריות],\u0006 \u0003ואי לאו דיהב\u0004 \u0005[ואם לא שהיה\u0006 \u0005נותן]\u0006 \u0003לי\u0004 ממנו, \u0003איסתכני\u0004 \u0005[הייתי מסתכן],\u0006 מחמת תאוות האוכל שתקפה אותי. \u0003אמר רב אשי: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003רב כהנא ואייתו ליה גרגלידי דליפתא בחלא\u0004 \u0005[והביאו לו עיגול של לפת בחומץ],\u0006 \u0003ואי לאו דיהב\u0004 \u0005[ואם לא שהיה נותן]\u0006 \u0003לי\u0004 ממנו, \u0003איסתכני\u0004 \u0005[הייתי מסתכן].\u0006 \u0003רב פפא אמר: אפילו תמרתא דהנוניתא\u0004 \u0005[תמר ריחני]\u0006 יש להאכיל לשמש. ומסכמים: \u0003כללא דמילתא\u0004 \u0005[כללו של דבר]:\u0006 \u0003כל דאית ליה ריחא ואית ליה קיוהא\u0004 \u0005[שיש לו ריח או שיש בו חריפות],\u0006 יש לתת ממנו לאדם הנמצא במקום, כדי שלא ינזק.","מסופר על שני חכמים, \u0003אבוה בר איהי ומנימין בר איהי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 היה נוהג ש\u0003ספי\u0004 \u0005[היה מאכיל\u0006 לשמש\u0005]\u0006 \u0003מכל מינא ומינא\u0004 \u0005[מין ומין]\u0006 שהיה אוכל, \u0003וחד ספי מחד מינא\u0004 \u0005[ואחד\u0006 מהם \u0005היה מאכיל\u0006 אותו רק \u0005ממין אחד\u0006 מן האוכל\u0005].\u0006 ואומרים: \u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 — \u0003משתעי\u0004 \u0005[\u0006היה \u0005מדבר]\u0006 \u0003אליהו\u0004 הנביא \u0003בהדיה\u0004 \u0005[איתו],\u0006 \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 — \u0003לא משתעי\u0004 \u0005[\u0006היה \u0005מדבר]\u0006 \u0003אליהו\u0004 הנביא \u0003בהדיה\u0004 \u0005[איתו],\u0006 שכן לא נהג מנהג חסידות וציער את השמש.","וכן \u0003הנהו תרתין חסידי\u0004 \u0005[אותם שני חסידים]\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בנוסח שמפרש את שמם \u0003רב מרי ורב פנחס בני רב חסדא, מר קדים ספי\u0004 \u0005[חכם\u0006 אחד \u0005היה מקדים\u0006 לפני האוכל ו\u0005מאכיל\u0006 את השמש\u0005],\u0006 \u0003ומר מאחר ספי\u0004 \u0005[וחכם\u0006 אחד היה מאחר ו\u0005מאכיל\u0006 אותו\u0005]\u0006 אחר שאכלו האורחים. \u0003דקדים ספי\u0004 \u0005[\u0006זה \u0005שהיה מקדים\u0006 ו\u0005מאכיל] —\u0006 היה \u0003אליהו\u0004 הנביא \u0003משתעי בהדיה\u0004 \u0005[מדבר איתו],\u0006 וזה שהיה \u0003מאחר ספי\u0004 \u0005[\u0006ו\u0005מאכיל] —\u0006 \u0003לא\u0004 היה \u0003משתעי\u0004 \u0005[מדבר]\u0006 \u0003אליהו בהדיה\u0004 \u0005[איתו].\u0006","ועוד מסופר בענין זה, \u0003אמימר ומר זוטרא ורב אשי הוו קא יתבי אפיתחא דבי\u0004 \u0005[היו יושבים על פתחו של בית]\u0006 \u0003אזגור מלכא\u0004 \u0005[המלך],\u0006 מלך פרס. \u0003חליף ואזיל אטורנגא דמלכא\u0004 \u0005[היה עובר והולך המלצר הראשי של המלך]\u0006 עם מיני מאכלים. \u0003חזייה\u0004 \u0005[ראה אותו]\u0006 \u0003רב אשי למר זוטרא\u0004"],["\u0003דחוור אפיה\u0004 \u0005[שהלבינו פניו]\u0006 מפני שהתאווה לאוכל, \u0003שקל באצבעתיה אנח ליה בפומיה\u0004 \u0005[לקח באצבעו\u0006 מן המאכל ו\u0005הניח בפיו\u0006 של מר זוטרא\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ראש המלצרים: \u0003אפסדת לסעודתא דמלכא\u0004 \u0005[הפסדת\u0006 איפוא \u0005את סעודת המלך].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]\u0006 האנשים שמסביב, שוטרי המלך: \u0003אמאי תיעביד הכי\u0004 \u0005[מדוע עשית כך]\u0006 לטעום מן המאכל השייך למלך? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאן דעביד הכי פסיל למאכל דמלכא\u0004 \u0005[מי שעושה כך\u0006 מאכל גרוע זה \u0005פוסל את מאכל המלך].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 אתה אומר כן? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דבר אחר\u0004 (צרעת), \u0003חזאי ביה\u0004 \u0005[ראיתי בו\u0006 בבשר\u0005].\u0006 \u0003בדקו ולא אשכחו\u0004 \u0005[מצאו].\u0006 \u0003שקל אצבעתיה, אנח עליה,\u0004 \u0005[לקח אצבעו\u0006 ו\u0005הניח עליו,\u0006 על הבשר\u0005]\u0006 ו\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכא מי בדקיתו\u0004 \u0005[כאן האם בדקתם]?\u0006 \u0003בדקו\u0004 ואכן \u0003אשכחו\u0004 \u0005[מצאו]\u0006 כדבריו. \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 לאחר מכן: \u0003מאי טעמא סמכת אניסא\u0004 \u0005[מה טעם סמכת על הנס]\u0006 שתימצא שם צרעת? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003חזאי\u0004 \u0005[ראיתי]\u0006 \u0003רוח צרעת דקא פרחה עילויה\u0004 \u0005[שפורחת עליו]\u0006 על המאכל הזה, והבנתי שיש בו פגם זה.","ועוד באותו ענין, \u0003ההוא רומאה\u0004 \u0005[רומאי אחד]\u0006 ש\u0003אמר לה לההיא איתתא\u0004 \u0005[לאשה אחת]:\u0006 \u0003מינסבת\u0004 \u0005[\u0006האם \u0005את\u0006 רוצה \u0005להינשא]\u0006 \u0003לי? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא.\u0004 מה עשה כדי לכפותה, \u0003אזיל אייתי, רימני פלי\u0004 \u0005[הלך הביא רימונים, קילף]\u0006 \u0003ואכל קמה\u0004 \u0005[לפניה]\u0006 ולא נתן לה מהם. \u0003כל מיא דצערי לה, בלעתיה\u0004 \u0005[כל המים,\u0006 הרוק, \u0005שציער אותה\u0006 מפני תאות האוכל, \u0005בלעה אותו],\u0006 \u0003ולא הב\u0004 \u0005[נתן]\u0006 \u0003לה עד דזג לה\u0004 \u0005[עד\u0006 שחלתה ו\u0005התנפחה].\u0006 \u0003לסוף אמר לה: אי מסינא לך, מינסבת\u0004 \u0005[אם ארפא אותך,\u0006 האם \u0005תנשאי]\u0006 \u0003לי? אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אזיל אייתי רימני, פלי\u0004 \u0005[הלך הביא רימונים, קילף]\u0006 \u0003ואכל קמה\u0004 \u0005[לפניה].\u0006 \u0003אמר לה: כל מיא דצערי לך תוף שדאי תוף שדאי\u0004 \u0005[כל מים,\u0006 רוק, \u0005שמצער אותך רקי\u0006 ו\u0005זרקי! רקי\u0006 ו\u0005זרקי!],\u0006 \u0003עד דנפקא מינה כי הוצא ירקא ואתסיאת\u0004 \u0005[שיצא ממנה כמו עלה ירוק ונרפאה].\u0006","שנינו במשנה בין המלאכות שהאשה עושה לבעלה, שהיא \u0003עושה בצמר.\u0004 ומדייקים: \u0003בצמר — אין\u0004 \u0005[כן],\u0006 \u0003בפשתים — לא.\u0004 ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי] —\u0006 כשיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אינו כופה\u0004 את האשה \u0003לא לעמוד\u0004 לשרת לא \u0003לפני אביו, ולא לעמוד לפני בנו\u0004 מנישואיו לאחרת, \u0003ולא ליתן תבן לפני בהמתו,\u0004 סוסים וחמורים שלו. \u0003אבל כופה\u0004 אותה \u0003ליתן תבן לפני בקרו,\u0004 פרות ושוורים שלו. \u0003ר' יהודה אומר: אף אינו כופה לעשות בפשתן, מפני שפשתן\u0004 בזמן שטווים אותו \u0003מסריח את הפה, ומשרבט\u0004 (ומשרבב) \u0003את השפתים.\u0004 ומעירים: \u0003והני מילי בכיתנא רומאה\u0004 \u0005[ודברים אלה\u0006 אמורים דווקא \u0005בפשתן רומי]\u0006 שמזיק ביותר, אבל בפשתן אחר, יכול לכופה.","עוד שנינו במשנה, ש \u0003ר' אליעזר אומר, שאפילו\u0004 אם \u0003הכניסה לו\u0004 אשתו \u0003מאה שפחות,\u0004 מכל מקום תעשה מלאכה, כדי שלא תבוא לידי זימה. \u0003אמר רב מלכיו אמר רב אדא בר אהבה: הלכה כר' אליעזר.\u0004","\u0003אמר ר' חנינא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 ההלכות בענין \u0003שפוד\u0004 לענין יום טוב, ובענין \u0003שפחות\u0004 במשנתנו, \u0003ו\u0004בענין \u0003גומות\u0004 לקביעת בגרות, הן של \u0003רב מלכיו,\u0004","אבל הלכות בענין \u0003בלורית,\u0004 בענין \u0003אפר מקלה ו\u0004בענין \u0003גבינה —\u0004 הן של \u0003רב מלכיא.\u0004","\u0003רב פפא אמר:\u0004 אותן הלכות המתייחסות ל\u0003מתניתין\u0004 \u0005[\u0006ל\u0005משנתנו]\u0006 \u0003ומתניתא\u0004 \u0005[ו\u0006ל\u0005ברייתא]\u0006 הן הלכות של \u0003רב מלכיא. שמעתתא\u0004 \u0005[השמועות,\u0006 דברי האמוראים\u0005]\u0006 הם של \u0003רב מלכיו. וסימנך\u0004 שתזכור: \u0003מתניתא מלכתא\u0004 \u0005[המשנה\u0006 היא \u0005מלכה]\u0006 והרי זה סימן לרב מלכיא (ששמו דומה למלכתא) שדבריו מתייחסים אל המשנה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין ר' חנינא בריה דרב איקא ורב פפא, בפרטים אלה — \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי \u0003שפחות,\u0004 שלפי גירסת ר' חנינא, רב מלכיו הוא שאמר את ההלכה בשפחות, ולדעת רב פפא, כיון שההלכה מתייחסת למשנתנו לפיכך היא מדברי רב מלכיא.","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר\u0004 שהבטלה מביאה לידי שעמום־שיגעון. ושואלים: \u0003היינו\u0004 \u0005[הרי זו\u0006 שיטתו\u0005]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ר' אליעזר! ומשיבים: \u0003איכא בינייהו דמיטללא בגורייתא קיטנייתא ונדרשיר\u0004 \u0005[יש ביניהם\u0006 הבדל כאשר \u0005משחקת בכלבים קטנים או במשחק\u0006 כמשחק שחמט\u0005],\u0006 שכיון שיש משהו שמעסיק אותה — אינה מגיעה לידי שיגעון, אבל עיסוק זה יכול להביא לידי זימה.","\u0003המדיר את אשתו,\u0004 שנדר באופן כזה שנאסר \u0003מתשמיש המטה, בית שמאי אומרים:\u0004 עד \u0003שתי שבתות\u0004 (שני שבועות) יכול להישאר במצב זה, ולאחר מכן צריך לגרש אותה ולתת לה את כתובתה. ו\u0003בית הלל אומרים: שבת אחת\u0004 (שבוע אחד).","מאחר שאנו דנים בחובתו של הבעל בענין תשמיש המיטה, נאמרו עוד כמה דברים בענין זה: \u0003התלמידים יוצאין לתלמוד תורה שלא ברשות\u0004 נשותיהם עד \u0003שלשים יום. הפועלים\u0004 יוצאים מן הבית שלא ברשות האשה \u0003שבת אחת\u0004 (שבוע אחד). \u0003העונה האמורה בתורה,\u0004 הזמן הקצוב לתשמיש, שהיא חובת הבעל בסתם (אם לא התנו ביניהם אחרת) משתנה לפי המצאותם של האנשים בבית, ולפי טיב עיסוקיהם. \u0003הטיילין,\u0004 אנשים שאינם עובדים — \u0003בכל יום. הפועלים — שתים\u0004 (פעמיים) \u0003בשבת. החמרים — אחת בשבת. הגמלים — אחת לשלשים יום. הספנים — אחת לששה חדשים.\u0004 אלו \u0003דברי ר' אליעזר.\u0004","ושואלים: \u0003מאי טעמייהו\u0004 \u0005[מה טעמם]\u0006 של \u0003בית שמאי\u0004 שאומרים שזמן הפרישה הוא עד שבועיים? \u0003גמרי\u0004 \u0005[לומדים\u0006 הם\u0005]\u0006 \u0003מיולדת נקבה,\u0004 שהיא טמאה ואסורה לבעלה שבועיים לאחר הלידה ומכאן הם למדים שעד שבועיים אין זה בבחינת סבל. \u0003ובית הלל,\u0004 מנין ראיה לשיטתם? \u0003גמרי\u0004 \u0005[לומדים\u0006 הם\u0005]\u0006 \u0003מיולדת זכר\u0004 שטמאה שבוע אחד.","ומקשים: \u0003ובית הלל נמי נגמרו\u0004 \u0005[גם כן ילמדו]\u0006 \u0003מיולדת נקבה,\u0004 שהרי מצאנו בתורה שיעור זמן גדול יותר, של שבועיים! ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מיולדת גמרי לה\u0004 \u0005[\u0006היו \u0005לומדים זאת]\u0006 — אכן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 היה צריך ללמוד, \u0003אלא בית הלל מנדה גמרי לה\u0004 \u0005[\u0006הם \u0005לומדים זאת],\u0006 שהיא אסורה בתשמיש שבעה ימים (מדין התורה).","ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]\u0006 לפי זה — \u0003מר סבר מידי דשכיח ממידי דשכיח\u0004 \u0005[חכם\u0006 זה, בית הלל, \u0005סבורים\u0006 שלמדים \u0005דבר מצוי מדבר מצוי],\u0006 ולכן למדים שיעור פרישה בזה הכועס על אשתו ומתוך כך מדירה שהוא דבר מצוי, מדין נידה המצוי, \u0003ומר סבר מידי דהוא גרים\u0004 \u0005[וחכם\u0006 זה, בית שמאי, \u0005סבורים,\u0006 למדים \u0005דבר שהוא גרם]\u0006 \u0003לה,\u0004 נדר, \u0003ממידי דהוא גרים\u0004 \u0005[מדבר שהוא גרם]\u0006 \u0003לה,\u0004 כלידה, ולא מנידה שהוא דבר שאינו תלוי בבעל.","\u0003אמר רב: מחלוקת\u0004 זו בין בית הלל ובית שמאי היא \u0003במפרש,\u0004 כשהוא אומר שנודר ממנה לזמן מסויים זה, או לזמן ארוך יותר. \u0003אבל\u0004 אם נדר ממנה מתשמיש המיטה \u0003בסתם — דברי הכל יוציא לאלתר\u0004 (מיד) \u0003ויתן כתובה,\u0004 שכיון שלא פירש לכמה זמן נודר — יש לה כבר צער מעכשיו. \u0003ושמואל אמר: אפילו בסתם נמי\u0004 \u0005[גם כן]\u0006 \u0003ימתין\u0004 עד שיעור זמן זה, \u0003שמא ימצא פתח\u0004 התרה \u0003לנדרו,\u0004 ולא יצטרך לגרשה.","ושואלים: \u0003הא פליגי\u0004 \u0005[\u0006ו\u0005הרי\u0006 כבר \u0005נחלקו]\u0006 \u0003בה\u0004 רב ושמואל, באותה בעיה עקרונית \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המדיר את אשתו מליהנות לו\u0004 (ממנו), \u0003עד שלשים יום — יעמיד פרנס.\u0004 שימנה אדם אחר שיטפל בפרנסתה. \u0003יותר מכאן — יוציא ויתן כתובה. ואמר רב: לא שנו אלא במפרש\u0004 זמן מסויים, \u0003אבל בסתם — יוציא לאלתר ויתן כתובה. ושמואל אמר: אפילו בסתם נמי\u0004 \u0005[גם כן]\u0006 \u0003ימתין, שמא\u0004 בתוך כך \u0003ימצא פתח\u0004 התרה \u0003לנדרו!\u0004","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 לפרש את המחלוקת בשני המקרים \u0003דאי איתמר בהא\u0004 \u0005[שאם היה נאמר\u0006 רק \u0005בזו],\u0006 במדיר את אשתו מתשמיש, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003רב\u0004 כך — \u0003משום\u0004 ש\u0003לא אפשר בפרנס\u0004 שהרי לענין תשמיש אי אפשר על ידי אחר, \u0003אבל ב\u0004הלכה \u0003ההיא,\u0004 במקרה שנודר מהנאה אחרת, שהלא \u0003אפשר\u0004 לבעל למלא את חובתו כלפיה \u0003בפרנס, אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לשמואל\u0004 שיכול להמתין. ולהיפך: \u0003ואי איתמר\u0004 \u0005[ואילו היתה נאמרת]\u0006 המחלוקת רק \u0003בההיא,\u0004 במדיר את אשתו משאר הנאות, היינו אומרים כי דווקא \u0003בהך קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003שמואל\u0004 שימתין, \u0003אבל בהא\u0004 \u0005[בזו],\u0006 במדיר מתשמיש — \u0003אימא מודי ליה\u0004 \u0005[אמור\u0006 ש\u0005מודה לו]\u0006 \u0003לרב,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני המקרים.","שנינו במשנה ש \u0003התלמידים יוצאין לתלמוד\u0004 תורה שלא ברשות שלושים יום. ושואלים: ואם יוצאים \u0003ברשות, כמה?\u0004 ותוהים על השאלה: אם ברשות ובהסכמת האשה הם יוצאים, שיצאו \u0003כמה דבעי\u0004 \u0005[ש\u0006הם \u0005רוצים]\u0006 ומה לנו להתערב בדבר שהסכימו בו הבעל והאשה?"]]};
